# --------------------------------------------------------------------------- #
# Session 1031: Task-agent routing override                                    #
# Prevents LLM-generated next_steps from sending specialist tasks to the       #
# wrong agents (e.g. competitor audit -> WorkflowAgent).                       #
# --------------------------------------------------------------------------- #
import re as _re

_TASK_ROUTING_OVERRIDES = [
    (_re.compile(r'competitor\s+(audit|analysis|landscape|benchmark)', _re.I), 'CompetitorAnalysisAgent'),
    (_re.compile(r'trend\s+(analysis|report|summary)', _re.I), 'TrendAnalysisAgent'),
    (_re.compile(r'customer\s+(research|interview|persona)', _re.I), 'CustomerResearchAgent'),
    (_re.compile(r'brand\s+(strategy|positioning|audit)', _re.I), 'BrandStrategyAgent'),
    (_re.compile(r'market(ing)?\s+(strategy|plan|recommendation)', _re.I), 'MarketingStrategyAgent'),
]

_NON_RESEARCH_AGENTS = frozenset({
    'WorkflowAgent', 'VideoAgent', 'CodeGeneratorAgent', 'DevOpsAgent',
    'FullStackDeveloperAgent', 'CodeReviewAgent', 'ContentDistributionAgent',
    'COOAgent', 'CTOAgent', 'AudioAgent',  # Session 1032: Sync with _NON_SPECIALIST in agent_router.py
})

# Session 1036: Media agents can ONLY generate content — block non-generative tasks
# like "list recent images", "review workspace", "catalog assets" etc.
_MEDIA_AGENTS = frozenset({
    'ImageAgent', 'VideoAgent', 'ThreeDAgent', 'AudioAgent',
    'ImageEditingAgent', 'VideoEditingAgent',
})
_MEDIA_GENERATION_PATTERN = _re.compile(
    r'(generat|creat|design|draw|render|produc|make|build|edit|enhance|'
    r'upscale|retouch|composit|illustrat|paint|sketch|draft|style|transform)',
    _re.I,
)


def _apply_task_routing_override(agent_name: str, task_text: str) -> str:
    """Reroute specialist tasks away from non-specialist agents."""
    for pattern, correct_agent in _TASK_ROUTING_OVERRIDES:
        if pattern.search(task_text):
            if agent_name != correct_agent and agent_name in _NON_RESEARCH_AGENTS:
                logger.info(
                    f"[routing-override] Rerouting '{task_text[:60]}' "
                    f"from {agent_name} -> {correct_agent}"
                )
                return correct_agent
    return agent_name


def _is_media_task_blocked(agent_name: str, task_text: str) -> bool:
    """Session 1036: Block non-generative tasks for media agents.

    Media agents (ImageAgent, VideoAgent, etc.) can only generate/edit content.
    Tasks like "list recent images", "review workspace assets", or
    "catalog available media" are not generative and waste API spend.
    """
    if agent_name not in _MEDIA_AGENTS:
        return False
    if _MEDIA_GENERATION_PATTERN.search(task_text):
        return False  # Looks like a real generation task
    return True


# Session 781: Import opener extraction for de-duplication
def _extract_opener(text: str) -> str:
    """Extract the opening phrase from a response (inline version for tasks.py)."""
    if not text:
        return ""
    text = text.strip()
    break_chars = ['.', '!', '?', '—', ' - ', ':']
    first_break = len(text)
    for char in break_chars:
        pos = text.find(char)
        if pos > 0 and pos < first_break:
            first_break = pos
    opener = text[:min(first_break, 60)].strip()
    return opener if len(opener) >= 10 else ""


# Session 781 Level 3: Discourse markers to track for repetition prevention
_DISCOURSE_MARKERS = [
    # Transitions
    "however", "that said", "building on that", "additionally", "furthermore",
    "moreover", "on the other hand", "nevertheless", "in contrast",
    # Agreement
    "i see your point", "that makes sense", "you're right", "i agree with",
    "exactly", "precisely", "indeed",
    # Disagreement
    "i'd question", "the concern is", "but have we considered", "i'm not sure about",
    "the risk here is", "my concern is",
    # Fillers
    "to be honest", "in my view", "from my perspective", "i think that",
    "it seems to me", "in my opinion", "i believe that",
    # Hedges
    "sort of", "kind of", "a bit", "slightly", "somewhat", "perhaps", "maybe",
]


def _extract_discourse_markers(text: str) -> list:
    """Extract discourse markers from text for repetition tracking."""
    if not text:
        return []
    text_lower = text.lower()
    return [m for m in _DISCOURSE_MARKERS if m in text_lower]


def _get_overused_markers(markers: list, threshold: int = 2) -> list:
    """Get markers that have been used more than threshold times."""
    from collections import Counter
    counts = Counter(markers)
    return [m for m, c in counts.most_common(5) if c >= threshold]


# ==================== SESSION 356: MYTHOLOGY VALIDATION FOR AGENT OUTPUTS ====================

def validate_agent_output(agent_name: str, output: str) -> str:
    """
    Session 356: Validate and correct agent output for mythology violations.

    This ensures agents don't hallucinate unrealistic claims when communicating
    with each other (Hive Mind, Conversations, Dreams).

    Args:
        agent_name: Name of the agent producing the output
        output: The LLM-generated output to validate

    Returns:
        Corrected output (or original if no violations)
    """
    try:
        from ai_core.agents.mythology_validator import mythology_enforcer
        result = mythology_enforcer.enforce(agent_name, output)

        if result.get('mythology_corrected'):
            logger.warning(f"🚨 [MYTHOLOGY] {agent_name} output corrected: {result.get('violations', 0)} violations")
            return result.get('result', output)

        return output
    except Exception as e:
        logger.warning(f"⚠️ [MYTHOLOGY] Validation failed for {agent_name}: {e}")
        return output  # Return original if validation fails


# ==================== SESSION 835: STALE EXECUTION CLEANUP ====================


@shared_task(bind=True)
def cleanup_stale_agent_executions(self, minutes_threshold: int = 60):
    """
    Session 835: Clean up agent executions stuck in 'running'/'in_progress' status.
    Session 842: Added detailed logging for debugging.
    Session 911: Fixed to check both 'running' and 'in_progress' statuses.
    Session 925: Added to Celery Beat schedule - runs every 30 min with 2hr threshold.
    Session 1017: Changed default from 30 to 60 min. Beat kwargs (120) weren't being
                  passed — 30 min was too aggressive for slow agents (WorkflowAgent
                  max 22 min, MeetingCoordinatorAgent max 24 min).

    Tasks that have been running for more than the threshold are
    marked as 'failed' since they clearly didn't complete properly.

    Args:
        minutes_threshold: Mark tasks as failed after this many minutes (default 30)
    """
    from django.utils import timezone
    from datetime import timedelta
    from core.models_unified_system import AgentExecution

    task_id = self.request.id if self.request else 'unknown'
    logger.info(f"🧹 [CLEANUP] Task {task_id} STARTED - threshold: {minutes_threshold} minutes")

    try:
        now = timezone.now()
        cutoff_time = now - timedelta(minutes=minutes_threshold)
        logger.info(f"🧹 [CLEANUP] Current time: {now.isoformat()}, cutoff: {cutoff_time.isoformat()}")

        # Session 911: Check both 'running' and 'in_progress' statuses
        # Tasks can be stuck in either state depending on how they were created
        running_statuses = ['running', 'in_progress']
        all_running = AgentExecution.objects.filter(status__in=running_statuses).count()
        logger.info(f"🧹 [CLEANUP] Total running/in_progress executions: {all_running}")

        # Find stale tasks (either running or in_progress)
        stale_tasks = AgentExecution.objects.filter(
            status__in=running_statuses,
            created_at__lt=cutoff_time
        )

        count = stale_tasks.count()
        logger.info(f"🧹 [CLEANUP] Stale executions (>{minutes_threshold}min old): {count}")

        if count > 0:
            # Log details of what we're cleaning up
            sample_tasks = list(stale_tasks.values('id', 'agent__name', 'created_at')[:5])
            for task in sample_tasks:
                age_min = (now - task['created_at']).total_seconds() / 60
                logger.info(f"🧹 [CLEANUP] Marking stale: {task['agent__name']} - {age_min:.0f}min old - ID: {task['id']}")

            # Perform the cleanup
            updated = stale_tasks.update(
                status='failed',
                error_message=f'Task timed out after {minutes_threshold} minutes - marked as failed by cleanup',
                completed_at=now
            )
            logger.info(f"🧹 [CLEANUP] SUCCESS - Cleaned up {updated} stale agent executions")
        else:
            logger.info(f"🧹 [CLEANUP] No stale executions found - nothing to clean")

        logger.info(f"🧹 [CLEANUP] Task {task_id} COMPLETED - cleaned: {count}")
        return {'cleaned': count, 'total_running': all_running, 'task_id': task_id}

    except Exception as e:
        logger.error(f"🧹 [CLEANUP] Task {task_id} FAILED with error: {e}", exc_info=True)
        raise


@shared_task
def reap_zombie_work(
    deliberation_stale_minutes: int = 60,
    pilot_stale_days: int = 7,
):
    """
    Session 1075: Close zombie deliberation sessions and stale pilot executions.

    Deliberation sessions that are 'active' with 0 turns after the threshold
    are clearly stalled — mark them 'failed'. Pilot executions stuck in
    'running' for over a week are completed as 'partial'.

    Args:
        deliberation_stale_minutes: Close active sessions older than this (default 60)
        pilot_stale_days: Complete running pilots older than this (default 7)
    """
    from django.utils import timezone
    from datetime import timedelta

    now = timezone.now()
    stats = {'deliberations_reaped': 0, 'pilots_reaped': 0}

    # --- Deliberation sessions ---
    try:
        from core.models_deliberation import DeliberationSession
        cutoff = now - timedelta(minutes=deliberation_stale_minutes)
        zombies = DeliberationSession.objects.filter(
            status='active',
            created_at__lt=cutoff,
        )
        count = zombies.update(status='failed')
        stats['deliberations_reaped'] = count
        if count:
            logger.info(f"🧹 [ZOMBIE-REAPER] Closed {count} stalled deliberation sessions")
    except Exception as e:
        logger.error(f"🧹 [ZOMBIE-REAPER] Deliberation cleanup error: {e}")

    # --- Pilot executions ---
    try:
        from core.models_pilot_readiness import PilotExecution
        cutoff = now - timedelta(days=pilot_stale_days)
        stale = PilotExecution.objects.filter(
            status='running',
            created_at__lt=cutoff,
        )
        count = stale.update(status='completed', outcome='partial')
        stats['pilots_reaped'] = count
        if count:
            logger.info(f"🧹 [ZOMBIE-REAPER] Completed {count} stale pilot executions as partial")
    except Exception as e:
        logger.error(f"🧹 [ZOMBIE-REAPER] Pilot cleanup error: {e}")

    total = stats['deliberations_reaped'] + stats['pilots_reaped']
    if total == 0:
        logger.info("🧹 [ZOMBIE-REAPER] No zombies found")
    return stats


@shared_task
def cleanup_junk_initiatives(stale_days: int = 7):
    """
    Session 926/943: Clean up junk initiatives to prevent pipeline backlogs.

    Session 943 UPDATE: Now attempts to FIX names using title generator before deleting.
    Only deletes if name cannot be fixed (no usable content to extract from).

    FIXES initiatives with junk name patterns by regenerating clean titles.
    DELETES initiatives that have no salvageable content.
    ARCHIVES initiatives that are stale (might be legitimate, just slow).

    Args:
        stale_days: Archive initiatives with no Stage 1 doc after this many days

    Returns:
        Dict with cleanup statistics
    """
    from django.utils import timezone
    from datetime import timedelta
    from django.db.models import Q
    from core.models_document_registry import Initiative, InitiativeStage
    from core.services.initiative_title_generator import generate_initiative_title, _is_valid_title

    logger.info(f"🧹 [INITIATIVE-CLEANUP] Starting cleanup...")

    try:
        now = timezone.now()
        cutoff = now - timedelta(days=stale_days)

        stats = {
            'names_fixed': 0,
            'junk_deleted': 0,
            'stale_archived': 0,
            'stage_invariant_fixed': 0,
        }

        # 1. FIX or DELETE junk name patterns
        # Session 943: Try to fix names before deleting
        # Session 945: Added Auto-created and other common junk patterns
        junk_patterns = Q(name__icontains='[Learned]') | \
                       Q(name__icontains='[Synthesis]') | \
                       Q(name__startswith='driven ') | \
                       Q(name__startswith='plan ') | \
                       Q(name__startswith='of-') | \
                       Q(name__startswith='analysis ') | \
                       Q(name__startswith="Feature name:") | \
                       Q(name__startswith="Auto-created From") | \
                       Q(name__startswith="A '") | \
                       Q(name__startswith="An '") | \
                       Q(name__regex=r'^[a-z]')  # Starts with lowercase (fragment)

        junk_initiatives = Initiative.objects.filter(
            status='ACTIVE'
        ).filter(junk_patterns)

        for init in junk_initiatives:
            old_name = init.name[:60]

            # Session 943: Try to generate a clean title from available content
            # Use description, parent_topic, or original name as sources
            content_sources = [
                init.description or '',
                init.parent_topic or '',
                init.name or '',
            ]
            combined_content = ' '.join(content_sources)

            # Try to generate a valid title
            new_title = generate_initiative_title(
                content=combined_content,
                topic_hint=init.parent_topic,
                max_length=60,
                use_llm=False  # Use heuristics only for speed
            )

            # Session 945: Check if new title is still junk (Auto-created, etc.)
            new_title_is_junk = (
                new_title and (
                    new_title.startswith("Auto-created") or
                    new_title.startswith("A '") or
                    new_title.startswith("An '") or
                    new_title[0].islower()  # Starts lowercase
                )
            )

            # Check if the new title is valid, different, and NOT still junk
            if new_title and _is_valid_title(new_title) and new_title != init.name and not new_title_is_junk:
                # Session 943: Check for duplicate name before saving
                if Initiative.objects.filter(name=new_title).exclude(id=init.id).exists():
                    # Add unique suffix to avoid duplicate
                    import uuid
                    suffix = str(uuid.uuid4())[:6]
                    new_title = f"{new_title[:53]} ({suffix})"

                try:
                    init.name = new_title
                    init.save(skip_invariant_check=True)  # Skip stage check for name-only fix
                    stats['names_fixed'] += 1
                    logger.info(f"✨ [INITIATIVE-CLEANUP] Fixed name: '{old_name}' → '{new_title}'")
                except Exception as save_err:
                    logger.warning(f"⚠️ Could not fix name '{old_name}': {save_err}")
                    continue  # Skip deletion, leave as-is
            else:
                # Cannot fix or new title still junk - delete it
                init.delete()
                stats['junk_deleted'] += 1
                logger.info(f"🗑️ [INITIATIVE-CLEANUP] Deleted unfixable: {old_name}")

        # 2. Session 943: Fix stage invariant violations
        # Find initiatives where current_stage > max_approved + 1
        for init in Initiative.objects.filter(status='ACTIVE'):
            max_approved = init.get_max_approved_stage()
            max_allowed = max_approved + 1
            if init.current_stage > max_allowed:
                old_stage = init.current_stage
                init.current_stage = max_allowed
                init.save(skip_invariant_check=True)
                stats['stage_invariant_fixed'] += 1
                logger.info(
                    f"🔧 [INITIATIVE-CLEANUP] Fixed stage: {init.name[:40]}... "
                    f"(was {old_stage}, now {max_allowed})"
                )

        # 3. ARCHIVE stale initiatives (no Stage 1 doc after X days)
        # These might be legitimate, just slow - archive instead of delete
        # Session 945: Skip if founder_intent_set or has recent conversation activity
        from core.models_unified_system import HiveMindSession

        stale_initiatives = Initiative.objects.filter(
            status='ACTIVE',
            created_at__lt=cutoff
        ).exclude(
            id__in=InitiativeStage.objects.filter(
                stage=1,
                document__isnull=False
            ).values_list('initiative_id', flat=True)
        )

        stats['skipped_with_activity'] = 0

        for init in stale_initiatives:
            # Session 945: Don't archive if founder has explicitly set intent
            if init.founder_intent_set:
                stats['skipped_with_activity'] += 1
                logger.debug(f"⏭️ [INITIATIVE-CLEANUP] Skipped (founder intent): {init.name[:40]}")
                continue

            # Session 945: Don't archive if there's recent activity
            recent_activity_cutoff = now - timedelta(days=3)

            # Check last_activity_at field first (most accurate)
            if init.last_activity_at and init.last_activity_at >= recent_activity_cutoff:
                stats['skipped_with_activity'] += 1
                logger.debug(f"⏭️ [INITIATIVE-CLEANUP] Skipped (recent activity): {init.name[:40]}")
                continue

            # Fallback: check for recent conversations
            has_recent_convo = HiveMindSession.objects.filter(
                initiative_id=init.id,
                created_at__gte=recent_activity_cutoff
            ).exists()

            if has_recent_convo:
                stats['skipped_with_activity'] += 1
                logger.debug(f"⏭️ [INITIATIVE-CLEANUP] Skipped (recent convo): {init.name[:40]}")
                continue

            init.status = 'ARCHIVED'
            init.save(skip_invariant_check=True)
            stats['stale_archived'] += 1
            logger.info(f"📦 [INITIATIVE-CLEANUP] Archived stale: {init.name[:50]}")

        logger.info(
            f"🧹 [INITIATIVE-CLEANUP] Complete - "
            f"fixed {stats['names_fixed']} names, "
            f"deleted {stats['junk_deleted']} junk, "
            f"archived {stats['stale_archived']} stale, "
            f"skipped {stats.get('skipped_with_activity', 0)} with activity, "
            f"fixed {stats['stage_invariant_fixed']} stage violations"
        )

        return stats

    except Exception as e:
        logger.error(f"🧹 [INITIATIVE-CLEANUP] Failed: {e}", exc_info=True)
        raise


@shared_task
def run_learning_loop_cycle(lookback_days: int = 7):
    """
    Session 945: Run the learning loop cycle to extract patterns from execution data.

    Analyzes ToolCallRecord and DecisionRecord data to extract actionable learnings
    that are then persisted to LearningPattern for injection into agent prompts.

    Args:
        lookback_days: How many days of data to analyze

    Returns:
        Dict with cycle statistics
    """
    from core.services.learning_loop_orchestrator import LearningLoopOrchestrator

    logger.info(f"🧠 [LEARNING-LOOP] Starting learning cycle (lookback={lookback_days}d)...")

    try:
        orchestrator = LearningLoopOrchestrator(lookback_days=lookback_days)
        result = orchestrator.run_learning_cycle()

        logger.info(
            f"🧠 [LEARNING-LOOP] Complete - "
            f"extracted {result['learnings_extracted']} learnings, "
            f"persisted {result['patterns_persisted']} patterns"
        )

        return result

    except Exception as e:
        logger.error(f"🧠 [LEARNING-LOOP] Failed: {e}", exc_info=True)
        raise


@shared_task
def cleanup_boardroom_junk(spider_action_hours: int = 6):
    """
    Session 927/977: Clean up boardroom junk to prevent backlog accumulation.

    DELETES:
    - spider_action items older than 6h (news headlines go stale fast)
    - arbitrage items older than 12h (time-sensitive, useless if old)
    - Items with [Learned] in title (auto-generated junk)
    - Draft decisions with [Learned] in topic

    Args:
        spider_action_hours: Delete spider_action items older than this (default 6h)

    Returns:
        Dict with cleanup statistics
    """
    from django.utils import timezone
    from datetime import timedelta
    from core.models_human_interface import HumanAttentionItem
    from core.models_unified_system import AgentDecisionSummary

    logger.info(f"🧹 [BOARDROOM-CLEANUP] Starting cleanup...")

    try:
        now = timezone.now()
        spider_cutoff = now - timedelta(hours=spider_action_hours)
        arbitrage_cutoff = now - timedelta(hours=12)

        stats = {
            'spider_actions_deleted': 0,
            'arbitrage_deleted': 0,
            'learned_attention_deleted': 0,
            'learned_decisions_deleted': 0,
        }

        # 1. Delete old spider_action items (pending only, they're just news)
        # Session 977: Reduced from 24h to 6h — headlines go stale quickly
        spider_deleted = HumanAttentionItem.objects.filter(
            status='pending',
            item_type='spider_action',
            created_at__lt=spider_cutoff
        ).delete()
        stats['spider_actions_deleted'] = spider_deleted[0]

        # 2. Session 977: Delete old arbitrage items (time-sensitive, useless after 12h)
        arb_deleted = HumanAttentionItem.objects.filter(
            status='pending',
            item_type='arbitrage',
            created_at__lt=arbitrage_cutoff
        ).delete()
        stats['arbitrage_deleted'] = arb_deleted[0]

        # 3. Delete [Learned] junk from HumanAttentionItem
        learned_hai = HumanAttentionItem.objects.filter(
            status='pending',
            title__icontains='[Learned]'
        ).delete()
        stats['learned_attention_deleted'] = learned_hai[0]

        # 4. Delete [Learned] junk from AgentDecisionSummary (draft only)
        learned_decisions = AgentDecisionSummary.objects.filter(
            status='draft',
            topic__icontains='[Learned]'
        ).delete()
        stats['learned_decisions_deleted'] = learned_decisions[0]

        # 5. Session 1017: Delete [Learned] junk conversations from AgentConversation
        # These are circular meta-discussions where agents discuss their own instructions
        from core.models_unified_system import AgentConversation
        learned_convos = AgentConversation.objects.filter(
            topic__icontains='[Learned]'
        ).delete()
        stats['learned_conversations_deleted'] = learned_convos[0]

        # 6. Session 1017: Delete conversations with agent instructions as topics
        instruction_convos = AgentConversation.objects.filter(
            topic__icontains='EXTERNAL sources'
        ).delete()
        stats['instruction_conversations_deleted'] = instruction_convos[0]

        total = sum(stats.values())
        logger.info(f"🧹 [BOARDROOM-CLEANUP] Complete - deleted {total} items "
                   f"(spider: {stats['spider_actions_deleted']}, "
                   f"arbitrage: {stats['arbitrage_deleted']}, "
                   f"learned_attention: {stats['learned_attention_deleted']}, "
                   f"learned_decisions: {stats['learned_decisions_deleted']}, "
                   f"learned_convos: {stats.get('learned_conversations_deleted', 0)}, "
                   f"instruction_convos: {stats.get('instruction_conversations_deleted', 0)})")

        return stats

    except Exception as e:
        logger.error(f"🧹 [BOARDROOM-CLEANUP] Failed: {e}", exc_info=True)
        raise


@shared_task
def auto_approve_boardroom_items():
    """
    Session 941/977: Auto-approve low-risk boardroom items to prevent backlog.

    AUTO-APPROVES (HumanAttentionItem):
    - insight items (informational only)
    - review items with non-critical urgency
    - opportunity items with non-critical urgency
    - spider_action items with low/medium urgency (bulk noise)

    AUTO-PROMOTES (AgentDecisionSummary):
    - experiment decisions
    - pipeline decisions
    - research decisions (informational, low risk)
    - guideline decisions (advisory, low risk)

    Returns:
        Dict with auto-approve statistics
    """
    from datetime import timedelta
    from django.utils import timezone
    from core.models_human_interface import HumanAttentionItem
    from core.models_unified_system import AgentDecisionSummary

    logger.info("✅ [BOARDROOM-AUTO-APPROVE] Starting auto-approve...")

    try:
        now = timezone.now()
        # Session 988: Aggressive auto-approve to keep Boardroom focused.
        # Insights clear immediately (informational). Spider actions clear immediately
        # (non-critical) or at 48h (critical). Reviews clear at 6h (non-critical) or
        # 24h (critical). Everything else has a 48h hard ceiling.
        age_6h = now - timedelta(hours=6)
        age_24h = now - timedelta(hours=24)
        age_48h = now - timedelta(hours=48)
        stats = {
            'insights_approved': 0,
            'reviews_approved': 0,
            'reviews_critical_approved': 0,
            'opportunities_approved': 0,
            'spider_actions_approved': 0,
            'spider_actions_stale_resolved': 0,
            'stale_catchall_resolved': 0,
            'experiments_promoted': 0,
            'pipelines_promoted': 0,
            'research_promoted': 0,
            'guidelines_promoted': 0,
        }

        # 1. Auto-approve ALL insight/error_review/arbitrage items immediately
        # These are informational or automated — no human action needed
        noise_types = HumanAttentionItem.objects.filter(
            status='pending',
            item_type__in=['insight', 'error_review', 'arbitrage'],
        )
        stats['insights_approved'] = noise_types.update(status='acted', decided_at=now)

        # 2. Auto-approve non-critical review items older than 6h
        reviews = HumanAttentionItem.objects.filter(
            status='pending',
            item_type='review',
            created_at__lt=age_6h,
        ).exclude(urgency='critical')
        stats['reviews_approved'] = reviews.update(status='acted', decided_at=now)

        # 2b. Auto-approve critical review items older than 24h
        reviews_critical = HumanAttentionItem.objects.filter(
            status='pending',
            item_type='review',
            urgency='critical',
            created_at__lt=age_24h,
        )
        stats['reviews_critical_approved'] = reviews_critical.update(status='acted', decided_at=now)

        # 3. Auto-approve non-critical opportunity items older than 6h
        opportunities = HumanAttentionItem.objects.filter(
            status='pending',
            item_type='opportunity',
            created_at__lt=age_6h,
        ).exclude(urgency='critical')
        stats['opportunities_approved'] = opportunities.update(status='acted', decided_at=now)

        # 4. Auto-approve ALL non-critical spider_action items immediately
        spider_actions = HumanAttentionItem.objects.filter(
            status='pending',
            item_type='spider_action',
        ).exclude(urgency='critical')
        stats['spider_actions_approved'] = spider_actions.update(status='acted', decided_at=now)

        # 4b. Hard ceiling: auto-resolve ALL spider_actions older than 48h (incl critical)
        stale_spider_actions = HumanAttentionItem.objects.filter(
            item_type='spider_action',
            status='pending',
            created_at__lt=age_48h,
        )
        stale_count = stale_spider_actions.update(status='auto_resolved', decided_at=now)
        stats['spider_actions_stale_resolved'] = stale_count

        # 5. Hard ceiling: auto-resolve ANY remaining pending items older than 48h
        # Catches alerts, arbitrage, opportunity_approval, etc.
        stale_any = HumanAttentionItem.objects.filter(
            status='pending',
            created_at__lt=age_48h,
        )
        stats['stale_catchall_resolved'] = stale_any.update(status='auto_resolved', decided_at=now)

        # 5. Auto-promote experiment decisions
        stats['experiments_promoted'] = AgentDecisionSummary.objects.filter(
            status='draft',
            decision_type='experiment'
        ).update(status='canonical')

        # 6. Auto-promote pipeline decisions
        stats['pipelines_promoted'] = AgentDecisionSummary.objects.filter(
            status='draft',
            decision_type='pipeline'
        ).update(status='canonical')

        # 7. Session 977: Auto-promote research decisions (informational)
        stats['research_promoted'] = AgentDecisionSummary.objects.filter(
            status='draft',
            decision_type='research'
        ).update(status='canonical')

        # 8. Session 977: Auto-promote guideline decisions (advisory)
        stats['guidelines_promoted'] = AgentDecisionSummary.objects.filter(
            status='draft',
            decision_type='guideline'
        ).update(status='canonical')

        total = sum(stats.values())
        logger.info(f"✅ [BOARDROOM-AUTO-APPROVE] Complete - processed {total} items "
                   f"(insights: {stats['insights_approved']}, "
                   f"reviews: {stats['reviews_approved']}, "
                   f"reviews_critical: {stats['reviews_critical_approved']}, "
                   f"opportunities: {stats['opportunities_approved']}, "
                   f"spider_actions: {stats['spider_actions_approved']}, "
                   f"spider_stale_48h: {stats['spider_actions_stale_resolved']}, "
                   f"stale_catchall: {stats['stale_catchall_resolved']}, "
                   f"experiments: {stats['experiments_promoted']}, "
                   f"pipelines: {stats['pipelines_promoted']}, "
                   f"research: {stats['research_promoted']}, "
                   f"guidelines: {stats['guidelines_promoted']})")

        return stats

    except Exception as e:
        logger.error(f"✅ [BOARDROOM-AUTO-APPROVE] Failed: {e}", exc_info=True)
        raise


@shared_task
def cleanup_expired_boardroom_items(days_old: int = 7):
    """
    Session 971/977: Delete expired and stale boardroom items.
    Items with status='expired' are past their useful life.
    Pending items older than 7 days were never triaged = stale.
    Stale draft decisions older than 14 days are also cleaned up.
    """
    from django.utils import timezone
    from datetime import timedelta
    from core.models_human_interface import HumanAttentionItem
    from core.models_unified_system import AgentDecisionSummary

    logger.info("🗑️ [BOARDROOM-EXPIRED-CLEANUP] Starting expired item cleanup...")

    try:
        now = timezone.now()
        stats = {
            'expired_deleted': 0,
            'stale_pending_deleted': 0,
            'stale_drafts_deleted': 0,
        }

        # 1. Delete all items with status='expired'
        expired = HumanAttentionItem.objects.filter(status='expired')
        stats['expired_deleted'] = expired.delete()[0]

        # 2. Session 977: Delete pending items older than 7 days (was 30 days)
        # If nobody triaged it in a week, it's stale
        stale_cutoff = now - timedelta(days=7)
        stale = HumanAttentionItem.objects.filter(
            status='pending',
            created_at__lt=stale_cutoff
        )
        stats['stale_pending_deleted'] = stale.delete()[0]

        # 3. Session 977: Delete draft decisions older than 14 days
        # Product/architecture drafts that sit for 2 weeks are abandoned
        draft_cutoff = now - timedelta(days=14)
        stale_drafts = AgentDecisionSummary.objects.filter(
            status='draft',
            created_at__lt=draft_cutoff
        )
        stats['stale_drafts_deleted'] = stale_drafts.delete()[0]

        total = sum(stats.values())
        logger.info(f"🗑️ [BOARDROOM-EXPIRED-CLEANUP] Complete - deleted {total} items "
                   f"(expired: {stats['expired_deleted']}, "
                   f"stale_pending: {stats['stale_pending_deleted']}, "
                   f"stale_drafts: {stats['stale_drafts_deleted']})")

        return stats

    except Exception as e:
        logger.error(f"🗑️ [BOARDROOM-EXPIRED-CLEANUP] Failed: {e}", exc_info=True)
        raise


@shared_task(ignore_result=True)
def auto_process_extracted_artifacts(
    stale_days: int = 7,
    archive_days: int = 14,
    batch_size: int = 2000,
    aggressive: bool = True
):
    """
    Session 943: Auto-process ExtractedArtifacts to prevent backlog accumulation.

    Processes 42K+ pending artifacts based on type, age, and score.

    AGGRESSIVE MODE (default=True) - Session 943 update:
    - ALL insights → approved (informational, no action needed)
    - proposals older than 10 days with score < 0.6 → rejected
    - proposals with score < 0.4 (any age) → rejected
    - experiments older than 7 days → rejected (stale experiments)
    - data_specs with score < 0.5 → rejected (low-value specs)
    - questions older than 7 days → rejected
    - risks with score < 0.4 → rejected (low-priority risks)
    - action_items older than 14 days with score < 0.5 → rejected

    STANDARD MODE (aggressive=False):
    - insights with score < 0.5 → approved
    - questions older than 14 days → rejected
    - items older than 30 days with score < 0.4 → rejected
    - duplicate titles → rejected (keep highest score)
    - data_specs with confidence < 0.3 → deferred

    ALWAYS KEEP PENDING (needs human review):
    - high-score risks (score >= 0.4)
    - recent action_items with good scores (score >= 0.5, age < 14 days)
    - high-score proposals (score >= 0.6, age < 10 days)

    Args:
        stale_days: Days after which questions/experiments become stale (default: 7)
        archive_days: Days after which low-score items get rejected (default: 14)
        batch_size: Max items to process per run (default: 2000)
        aggressive: Use aggressive cleanup rules (default: True)

    Returns:
        Dict with processing statistics
    """
    from django.utils import timezone
    from datetime import timedelta
    from django.db.models import Count
    from core.models_conversation_artifacts import ExtractedArtifact

    mode = "AGGRESSIVE" if aggressive else "STANDARD"
    logger.info(f"🔄 [ARTIFACT-AUTO-PROCESS] Starting auto-processing ({mode} mode)...")

    try:
        now = timezone.now()
        stale_cutoff = now - timedelta(days=stale_days)  # 7 days for questions/experiments
        archive_cutoff = now - timedelta(days=archive_days)  # 14 days for action_items
        proposal_cutoff = now - timedelta(days=10)  # 10 days for proposals
        experiment_cutoff = now - timedelta(days=stale_days)  # Same as questions (7 days)

        stats = {
            'insights_approved': 0,
            'questions_rejected': 0,
            'stale_rejected': 0,
            'duplicates_rejected': 0,
            'specs_rejected': 0,
            'proposals_rejected': 0,
            'experiments_rejected': 0,
            'risks_rejected': 0,
            'action_items_rejected': 0,
            'specs_deferred': 0,
            'total_processed': 0,
            'still_pending': 0,
        }

        # =====================================================================
        # 1. Session 1070: AUTO-REJECT very low-score noise insights only.
        # All other insights stay 'pending' until human classifies + approves.
        # (Previously this block auto-approved insights, which bypassed
        #  the decision gate — the core semantic bug this session fixes.)
        # =====================================================================
        noise_insights = ExtractedArtifact.objects.filter(
            status='pending',
            artifact_type='insight',
            composite_score__lt=0.3
        )[:batch_size]
        noise_note = 'Auto-rejected: Very low-score insight (noise, composite < 0.3)'

        for artifact in noise_insights:
            artifact.status = 'rejected'
            artifact.decided_at = now
            artifact.decision_notes = noise_note
            artifact.save(update_fields=['status', 'decided_at', 'decision_notes'])
            stats['insights_approved'] += 1  # reusing key for backwards compat
            stats['total_processed'] += 1

        # =====================================================================
        # 2. AUTO-REJECT: Stale questions (older than stale_days)
        # =====================================================================
        stale_questions = ExtractedArtifact.objects.filter(
            status='pending',
            artifact_type='question',
            extracted_at__lt=stale_cutoff
        )[:batch_size]

        for artifact in stale_questions:
            artifact.status = 'rejected'
            artifact.decided_at = now
            artifact.decision_notes = f'Auto-rejected: Stale question (>{stale_days} days old)'
            artifact.save(update_fields=['status', 'decided_at', 'decision_notes'])
            stats['questions_rejected'] += 1
            stats['total_processed'] += 1

        # =====================================================================
        # 3. AUTO-REJECT: Old low-score artifacts (older than archive_days, score < 0.4)
        # =====================================================================
        stale_low_score = ExtractedArtifact.objects.filter(
            status='pending',
            extracted_at__lt=archive_cutoff,
            composite_score__lt=0.4
        )[:batch_size]

        for artifact in stale_low_score:
            artifact.status = 'rejected'
            artifact.decided_at = now
            artifact.decision_notes = f'Auto-rejected: Stale and low-priority (>{archive_days} days, score<0.4)'
            artifact.save(update_fields=['status', 'decided_at', 'decision_notes'])
            stats['stale_rejected'] += 1
            stats['total_processed'] += 1

        # =====================================================================
        # 4. AUTO-REJECT: Duplicate titles (keep highest score)
        # =====================================================================
        # Find duplicate titles within each artifact type
        duplicates = (
            ExtractedArtifact.objects
            .filter(status='pending')
            .values('artifact_type', 'title')
            .annotate(count=Count('id'))
            .filter(count__gt=1)
        )[:100]  # Limit duplicate groups to check

        for dup in duplicates:
            # Get all artifacts with this title/type, ordered by score desc
            matching = ExtractedArtifact.objects.filter(
                status='pending',
                artifact_type=dup['artifact_type'],
                title=dup['title']
            ).order_by('-composite_score')

            # Keep the first (highest score), reject the rest
            for artifact in matching[1:]:
                artifact.status = 'rejected'
                artifact.decided_at = now
                artifact.decision_notes = 'Auto-rejected: Duplicate (lower score copy)'
                artifact.save(update_fields=['status', 'decided_at', 'decision_notes'])
                stats['duplicates_rejected'] += 1
                stats['total_processed'] += 1

        # =====================================================================
        # 5. AGGRESSIVE: Reject proposals (two rules)
        # Rule A: older than 10 days with score < 0.6 → rejected
        # Rule B: very low score < 0.4 (any age) → rejected
        # =====================================================================
        if aggressive:
            # Rule A: Old proposals with mediocre scores
            old_proposals = ExtractedArtifact.objects.filter(
                status='pending',
                artifact_type='proposal',
                extracted_at__lt=proposal_cutoff,
                composite_score__lt=0.6
            )[:batch_size]

            for artifact in old_proposals:
                artifact.status = 'rejected'
                artifact.decided_at = now
                artifact.decision_notes = 'Auto-rejected: Stale proposal (>10 days, score<0.6)'
                artifact.save(update_fields=['status', 'decided_at', 'decision_notes'])
                stats['proposals_rejected'] += 1
                stats['total_processed'] += 1

            # Rule B: Very low-score proposals (any age)
            low_score_proposals = ExtractedArtifact.objects.filter(
                status='pending',
                artifact_type='proposal',
                composite_score__lt=0.4
            )[:batch_size]

            for artifact in low_score_proposals:
                artifact.status = 'rejected'
                artifact.decided_at = now
                artifact.decision_notes = 'Auto-rejected: Low-score proposal (score<0.4)'
                artifact.save(update_fields=['status', 'decided_at', 'decision_notes'])
                stats['proposals_rejected'] += 1
                stats['total_processed'] += 1

        # =====================================================================
        # 6. AGGRESSIVE: Reject old experiments (>14 days)
        # =====================================================================
        if aggressive:
            old_experiments = ExtractedArtifact.objects.filter(
                status='pending',
                artifact_type='experiment',
                extracted_at__lt=experiment_cutoff
            )[:batch_size]

            for artifact in old_experiments:
                artifact.status = 'rejected'
                artifact.decided_at = now
                artifact.decision_notes = f'Auto-rejected: Stale experiment (>{stale_days} days old)'
                artifact.save(update_fields=['status', 'decided_at', 'decision_notes'])
                stats['experiments_rejected'] += 1
                stats['total_processed'] += 1

        # =====================================================================
        # 7. AGGRESSIVE: Reject low-score data_specs (score < 0.5)
        # Standard: Defer low-confidence specs
        # =====================================================================
        if aggressive:
            low_specs = ExtractedArtifact.objects.filter(
                status='pending',
                artifact_type='data_spec',
                composite_score__lt=0.5
            )[:batch_size]

            for artifact in low_specs:
                artifact.status = 'rejected'
                artifact.decided_at = now
                artifact.decision_notes = 'Auto-rejected: Low-score data spec (score<0.5)'
                artifact.save(update_fields=['status', 'decided_at', 'decision_notes'])
                stats['specs_rejected'] += 1
                stats['total_processed'] += 1
        else:
            # Standard mode: just defer unclear specs
            unclear_specs = ExtractedArtifact.objects.filter(
                status='pending',
                artifact_type='data_spec',
                confidence_score__lt=0.3
            )[:batch_size]

            for artifact in unclear_specs:
                artifact.status = 'deferred'
                artifact.decided_at = now
                artifact.decision_notes = 'Auto-deferred: Low-confidence spec needs clarification'
                artifact.save(update_fields=['status', 'decided_at', 'decision_notes'])
                stats['specs_deferred'] += 1
                stats['total_processed'] += 1

        # =====================================================================
        # 8. AGGRESSIVE: Reject low-score risks (score < 0.4)
        # Low-score risks aren't actionable enough to keep
        # =====================================================================
        if aggressive:
            low_risks = ExtractedArtifact.objects.filter(
                status='pending',
                artifact_type='risk',
                composite_score__lt=0.4
            )[:batch_size]

            for artifact in low_risks:
                artifact.status = 'rejected'
                artifact.decided_at = now
                artifact.decision_notes = 'Auto-rejected: Low-score risk (score<0.4)'
                artifact.save(update_fields=['status', 'decided_at', 'decision_notes'])
                stats['risks_rejected'] += 1
                stats['total_processed'] += 1

        # =====================================================================
        # 9. AGGRESSIVE: Reject old low-score action_items (>14 days, score<0.5)
        # Old action items that weren't actioned can be cleared
        # =====================================================================
        if aggressive:
            old_action_items = ExtractedArtifact.objects.filter(
                status='pending',
                artifact_type='action_item',
                extracted_at__lt=archive_cutoff,
                composite_score__lt=0.5
            )[:batch_size]

            for artifact in old_action_items:
                artifact.status = 'rejected'
                artifact.decided_at = now
                artifact.decision_notes = 'Auto-rejected: Stale action item (>14 days, score<0.5)'
                artifact.save(update_fields=['status', 'decided_at', 'decision_notes'])
                stats['action_items_rejected'] += 1
                stats['total_processed'] += 1

        # =====================================================================
        # 10. Count remaining pending
        # =====================================================================
        stats['still_pending'] = ExtractedArtifact.objects.filter(status='pending').count()

        total_rejected = (
            stats['questions_rejected'] + stats['stale_rejected'] +
            stats['duplicates_rejected'] + stats['specs_rejected'] +
            stats['proposals_rejected'] + stats['experiments_rejected'] +
            stats['risks_rejected'] + stats['action_items_rejected']
        )
        logger.info(
            f"🔄 [ARTIFACT-AUTO-PROCESS] Complete ({mode}) - processed {stats['total_processed']} items: "
            f"approved={stats['insights_approved']}, "
            f"rejected={total_rejected} "
            f"(questions={stats['questions_rejected']}, proposals={stats['proposals_rejected']}, "
            f"experiments={stats['experiments_rejected']}, specs={stats['specs_rejected']}, "
            f"risks={stats['risks_rejected']}, action_items={stats['action_items_rejected']}, "
            f"dupes={stats['duplicates_rejected']}, stale={stats['stale_rejected']}), "
            f"deferred={stats['specs_deferred']}, "
            f"still_pending={stats['still_pending']}"
        )

        return stats

    except Exception as e:
        logger.error(f"🔄 [ARTIFACT-AUTO-PROCESS] Failed: {e}", exc_info=True)
        raise


@shared_task
def cleanup_automated_conversation_artifacts(batch_size: int = 5000, prefix: str = None):
    """
    Session 943: Bulk-reject pending artifacts from automated conversations.

    Automated conversations (Discussion:, Panel:) are multi-agent brainstorming
    sessions. Their artifacts are hypothetical ideas, not actionable items
    requiring human review.

    Args:
        batch_size: Max items to process per run (default: 5000)
        prefix: Topic prefix to filter (e.g., 'Discussion:', 'Panel:')
                If None, cleans both Discussion: and Panel: artifacts

    Returns:
        Dict with cleanup statistics
    """
    from django.utils import timezone
    from django.db.models import Q
    from core.models_conversation_artifacts import ExtractedArtifact

    prefixes = [prefix] if prefix else ['Discussion:', 'Panel:']
    prefix_label = prefix or 'Discussion/Panel'

    logger.info(f"🧹 [AUTO-CONV-CLEANUP] Starting cleanup for {prefix_label} artifacts...")

    now = timezone.now()

    # Build query for specified prefixes
    query = Q()
    for p in prefixes:
        query |= Q(conversation__topic__startswith=p)

    # Find all pending artifacts from automated conversations
    auto_artifacts = ExtractedArtifact.objects.filter(
        status='pending'
    ).filter(query)[:batch_size]

    total_count = ExtractedArtifact.objects.filter(
        status='pending'
    ).filter(query).count()

    rejected_count = 0
    for artifact in auto_artifacts:
        artifact.status = 'rejected'
        artifact.decided_at = now
        artifact.decision_notes = f'Auto-rejected: Automated conversation artifact (brainstorming, not actionable)'
        artifact.save(update_fields=['status', 'decided_at', 'decision_notes'])
        rejected_count += 1

    still_pending = ExtractedArtifact.objects.filter(
        status='pending'
    ).filter(query).count()

    logger.info(
        f"🧹 [AUTO-CONV-CLEANUP] Complete - rejected {rejected_count} of {total_count} "
        f"{prefix_label} artifacts. Still pending: {still_pending}"
    )

    return {
        'rejected': rejected_count,
        'total_auto_pending': total_count,
        'still_pending': still_pending,
        'all_pending': ExtractedArtifact.objects.filter(status='pending').count(),
    }


# Backwards compatibility alias
def cleanup_discussion_artifacts(batch_size: int = 5000):
    """Alias for cleanup_automated_conversation_artifacts with Discussion prefix."""
    return cleanup_automated_conversation_artifacts(batch_size=batch_size, prefix='Discussion:')


@shared_task
def cleanup_halted_experiments(days_old: int = 7):
    """
    Session 942: Delete old halted experiments to prevent cluttering system reviews.

    DELETES experiments that are:
    - is_halted=True AND older than X days
    - outcome_classification in ('fail', 'learn') OR status in ('failure', 'partial')

    This prevents ThinkingAgent and other system reviews from repeatedly
    flagging the same old halted experiments.

    Args:
        days_old: Delete halted experiments older than this many days (default: 7)

    Returns:
        Dict with cleanup statistics
    """
    from django.utils import timezone
    from datetime import timedelta
    from core.models_pilot_readiness import Experiment

    logger.info(f"🧹 [EXPERIMENT-CLEANUP] Starting halted experiment cleanup (>{days_old} days old)...")

    try:
        cutoff = timezone.now() - timedelta(days=days_old)

        stats = {
            'failed_deleted': 0,
            'partial_deleted': 0,
            'total_deleted': 0,
        }

        # Find halted experiments older than cutoff with failed outcomes
        halted_failed = Experiment.objects.filter(
            is_halted=True,
            halted_at__lt=cutoff,
            outcome_classification__in=['fail', 'learn']
        )

        # Also catch ones with failure/partial status but pending outcome
        halted_by_status = Experiment.objects.filter(
            is_halted=True,
            halted_at__lt=cutoff,
            status__in=['failure', 'partial']
        ).exclude(
            outcome_classification__in=['fail', 'learn']  # Don't double count
        )

        # Delete failed outcome experiments
        for exp in halted_failed:
            exp_name = exp.name[:50] if exp.name else str(exp.id)[:8]
            logger.debug(f"🗑️ [EXPERIMENT-CLEANUP] Deleting halted experiment: {exp_name} "
                        f"(outcome: {exp.outcome_classification}, halted: {exp.halted_at})")
            if exp.outcome_classification == 'fail':
                stats['failed_deleted'] += 1
            else:
                stats['partial_deleted'] += 1
            exp.delete()

        # Delete by status
        for exp in halted_by_status:
            exp_name = exp.name[:50] if exp.name else str(exp.id)[:8]
            logger.debug(f"🗑️ [EXPERIMENT-CLEANUP] Deleting halted experiment: {exp_name} "
                        f"(status: {exp.status}, halted: {exp.halted_at})")
            if exp.status == 'failure':
                stats['failed_deleted'] += 1
            else:
                stats['partial_deleted'] += 1
            exp.delete()

        stats['total_deleted'] = stats['failed_deleted'] + stats['partial_deleted']

        logger.info(f"🧹 [EXPERIMENT-CLEANUP] Complete - deleted {stats['total_deleted']} experiments "
                   f"(failed: {stats['failed_deleted']}, partial: {stats['partial_deleted']})")

        return stats

    except Exception as e:
        logger.error(f"🧹 [EXPERIMENT-CLEANUP] Failed: {e}", exc_info=True)
        raise


# ==================== SESSION 265 PHASE 6: AUTONOMY ENGINE ====================


@shared_task
def run_autonomy_cycle(user_id: int = None):
    """
    Run an autonomy cycle for a user or all users.

    Session 265 Phase 6: Autonomy Engine

    This task:
    - Scans for actionable opportunities
    - Assesses risk and value
    - Executes approved autonomous actions
    - Records outcomes for learning

    Args:
        user_id: Specific user ID, or None for all users with autonomy enabled
    """
    from django.contrib.auth import get_user_model
    from core.super_platform.autonomy_engine import get_autonomy_engine, AutonomyLevel

    User = get_user_model()

    results = {
        'users_processed': 0,
        'total_actions': 0,
        'successful_actions': 0,
        'total_value': 0.0,
    }

    try:
        if user_id:
            users = User.objects.filter(id=user_id)
        else:
            # Get all users with autonomy enabled
            from core.models_unified_system import AutonomyConfiguration
            enabled_configs = AutonomyConfiguration.objects.exclude(
                autonomy_level='observe'
            ).values_list('user_id', flat=True)
            users = User.objects.filter(id__in=enabled_configs)

        for user in users:
            try:
                engine = get_autonomy_engine(user)

                # Skip if observe-only
                if engine.config.level == AutonomyLevel.OBSERVE:
                    continue

                # Run cycle
                cycle_result = engine.run_autonomy_cycle()

                results['users_processed'] += 1
                results['total_actions'] += cycle_result.get('actions_executed', 0)
                results['successful_actions'] += cycle_result.get('actions_succeeded', 0)
                results['total_value'] += float(cycle_result.get('total_value_generated', 0))

                logger.info(
                    f"Autonomy cycle for {user.username}: "
                    f"{cycle_result.get('actions_executed', 0)} actions, "
                    f"${cycle_result.get('total_value_generated', 0)} value"
                )

            except Exception as user_error:
                logger.error(f"Autonomy cycle failed for user {user.id}: {user_error}")

        logger.info(
            f"Autonomy cycle complete: {results['users_processed']} users, "
            f"{results['total_actions']} actions, ${results['total_value']:.2f} value"
        )

        return results

    except Exception as e:
        logger.exception(f"Autonomy cycle task failed: {e}")
        return {'error': str(e)}


# ==================== SESSION 811: CONVERSATION ACTION EXECUTION ====================


@shared_task(bind=True, max_retries=2, default_retry_delay=60, soft_time_limit=3600, time_limit=3900)
def execute_agent_task(
    self,
    agent_name: str,
    task: str,
    context: Dict[str, Any] = None
) -> Dict[str, Any]:
    """
    Session 811: Execute a task via a specific agent from conversation next_steps.
    Session 1017: Added soft_time_limit=2700 (45 min) to kill hung agents.
    Session 1058: Raised to 3600/3900 (60/65 min) — WorkflowAgent/TrendAnalysisAgent hit 43-44 min.
    NOTE: soft_time_limit does NOT enforce on --pool=threads (Railway) — SIGUSR1
    only works with prefork. The WorkflowAgent wall-clock guard is the real timeout.

    This task is queued by ConversationActionDispatcher when a conversation
    produces next_steps that should be executed.

    Args:
        agent_name: Name of the agent to execute the task (e.g., "ResearchAgent")
        task: Task description from conversation next_steps
        context: Additional context including conversation_id, participants

    Returns:
        Dict with execution result including status and output
    """
    from core.agent_router import AgentRouter
    from core.models_unified_system import Agent, AgentExecution
    from core.services.context_tracing import ContextTracer, auto_repair_context
    from decimal import Decimal

    # Session 1064: Respect body throttle mode — proportional delay when system stressed
    # Note: body health tasks (run_heartbeat, check_breathing, etc.), PA chat
    # (process_pa_chat_task), and gate progression (process_gate_progression) are
    # separate Celery tasks that never flow through execute_agent_task — they are
    # naturally exempt. All agent work dispatched here is deferrable.
    try:
        from core.services.body_coordinator import BodyCoordinator
        from django.conf import settings as django_settings
        coordinator = BodyCoordinator()
        throttle = coordinator.get_throttle_factor()
        if throttle < 1.0:
            max_delay = getattr(django_settings, 'BODY_THROTTLE_MAX_DELAY_SECONDS', 30)
            delay = int((1.0 - throttle) * max_delay)
            logger.info(f"Body throttle {throttle:.1f}: delaying {agent_name} by {delay}s")
            time.sleep(delay)
    except Exception:
        pass  # Never block agent execution due to body system errors

    # Session 875: Initialize context tracer for bad context forensics
    tracer = ContextTracer(source=f"execute_agent_task:{agent_name}")

    # Session 875: Log context at post-deserialize stage (after Celery receives it)
    tracer.log_post_deserialize(
        context=context,
        agent_name=agent_name,
        task_name="execute_agent_task"
    )

    # Session 875: Ensure context is a dict (defensive fix for list being passed)
    if not isinstance(context, dict):
        logger.warning(f"[execute_agent_task] Received non-dict context (type={type(context).__name__}), using empty dict")
        # Auto-repair the context
        context = auto_repair_context(context)
    else:
        context = context or {}
    conversation_id = context.get('conversation_id', 'unknown')
    execution_start = time.time()

    # Session 1031: Hard-block agents that can't do useful work on Railway
    # Session 1068: Unblocked AudioAgent (ElevenLabs quota replenished)
    _BLOCKED_AGENTS = frozenset({
        'CodeGeneratorAgent',  # No codebase access in Railway sandbox
    })
    if agent_name in _BLOCKED_AGENTS:
        logger.warning(
            f"[execute_agent_task] BLOCKED: {agent_name} disabled on Railway "
            f"(task='{task[:50]}...')"
        )
        return {
            'status': 'blocked',
            'agent': agent_name,
            'reason': f'{agent_name} disabled on Railway since Session 1031',
        }

    # Session 1036: Block non-generative tasks for media agents.
    # ImageAgent, VideoAgent, etc. can only generate/edit content — tasks like
    # "list recent images in workspace" waste API spend ($0.03+) for nothing.
    if _is_media_task_blocked(agent_name, task):
        logger.info(
            f"[execute_agent_task] BLOCKED non-generative task for {agent_name}: "
            f"'{task[:60]}...'"
        )
        return {
            'status': 'blocked',
            'agent': agent_name,
            'reason': f'{agent_name} only handles generation/editing tasks',
        }

    logger.info(
        f"[execute_agent_task] Starting: {agent_name} <- '{task[:50]}...' "
        f"(conversation={conversation_id})"
    )

    try:
        # Create execution record
        agent_obj = Agent.objects.filter(name=agent_name).first()

        # Session 841: Resolve experiment for proper error rate scoping
        experiment = None
        experiment_id = context.get('experiment_id')
        if experiment_id:
            try:
                from core.models import Experiment
                experiment = Experiment.objects.filter(id=experiment_id).first()
            except Exception as e:
                logger.warning(f"Experiment lookup failed for {experiment_id}: {e}")

        execution_record = None
        if agent_obj:
            # Session 1088: Sanitize input_data — context may contain UUID objects
            # (e.g. user_id, experiment_id) that aren't JSON-serializable.
            import json as _json
            _raw_input = {
                'task': task,
                'context': context,
                'source': 'conversation_action_dispatch',
                'celery_task_id': str(self.request.id),
            }
            try:
                input_data = _json.loads(_json.dumps(_raw_input, default=str))
            except (TypeError, ValueError):
                input_data = {'task': task, 'source': 'conversation_action_dispatch',
                              'celery_task_id': str(self.request.id)}

            execution_record = AgentExecution.objects.create(
                agent=agent_obj,
                task=task[:500],  # Truncate for DB field
                status='in_progress',
                input_data=input_data,
                experiment=experiment,  # Session 841: Link to experiment for scoped metrics
            )

        # Session 1031: Routing override — reroute specialist tasks away from
        # non-specialist agents.  E.g. "competitor audit" should never go to
        # WorkflowAgent, VideoAgent, etc.
        agent_name = _apply_task_routing_override(agent_name, task)

        # Session 1031: Dedup — skip if this agent already ran a very similar task recently
        # Exclude the execution_record we just created (it would always match itself)
        # Only dedup against SUCCESSFUL completions — failed/deduped tasks should be retryable
        dedup_qs = AgentExecution.objects.filter(
            agent__name=agent_name,
            created_at__gte=timezone.now() - timedelta(hours=2),
            task__startswith=task[:80],
            status='completed',
        ).exclude(
            output_data__skipped='dedup',
        )
        if execution_record:
            dedup_qs = dedup_qs.exclude(id=execution_record.id)
        recent_dup = dedup_qs.exists()
        if recent_dup:
            logger.info(
                f"[execute_agent_task] Dedup skip: {agent_name} already ran "
                f"'{task[:60]}' in the last 2h"
            )
            if execution_record:
                execution_record.status = 'completed'
                execution_record.output_data = {'skipped': 'dedup', 'reason': 'Similar task ran in last 2h'}
                execution_record.completed_at = timezone.now()
                execution_record.save()
            return {
                'success': True,
                'agent_name': agent_name,
                'task': task,
                'skipped': 'dedup',
                'conversation_id': conversation_id,
            }

        # Route to agent — resolve user from context so media is owned correctly
        _route_user = None
        _route_user_id = context.get('user_id')
        if _route_user_id:
            try:
                from django.contrib.auth import get_user_model
                _route_user = get_user_model().objects.filter(id=_route_user_id).first()
            except Exception:
                pass
        router = AgentRouter(user=_route_user)
        result = router.route(
            agent_name=agent_name,
            task=task,
            context={
                'source': 'conversation_action_dispatch',
                'conversation_id': conversation_id,
                **context
            }
        )

        execution_time_ms = int((time.time() - execution_start) * 1000)

        # Update execution record
        if execution_record:
            execution_record.status = 'completed' if result.success else 'failed'
            execution_record.execution_time_ms = execution_time_ms
            execution_record.output_data = {
                'content': result.content[:5000] if result.content else None,
                'metadata': getattr(result, 'data', {}) or {},
            }
            if not result.success:
                # Session 1068: Ensure error_message is never blank — fall back through
                # error, message, then generic label
                execution_record.error_message = (
                    result.error or result.message or 'Agent returned failure with no error details'
                )[:2000]
            execution_record.completed_at = timezone.now()
            execution_record.save()

            # Update agent metrics
            Agent.objects.filter(pk=agent_obj.pk).update(
                total_executions=F('total_executions') + 1,
                successful_executions=F('successful_executions') + (1 if result.success else 0)
            )

        if execution_time_ms > 2_400_000:  # 40 min
            logger.warning(
                f"[execute_agent_task] SLOW AGENT: {agent_name} took "
                f"{execution_time_ms // 60_000}min — approaching timeout"
            )

        logger.info(
            f"[execute_agent_task] Completed: {agent_name} "
            f"(success={result.success}, time={execution_time_ms}ms)"
        )

        # Push notification for completed media jobs
        _MEDIA_AGENTS = frozenset({
            'ImageAgent', 'VideoAgent', 'AudioAgent', 'TalkingCharacterAgent',
            'ImageEditingAgent', 'VideoEditingAgent', 'ThreeDAgent', 'ResolveAgent',
            # Also match router-normalized names
            'image_generation_agent', 'video_generation_agent',
            'audio_generation_agent', 'talking_character_agent',
        })
        _MEDIA_TYPE_LABELS = {
            'ImageAgent': 'image', 'VideoAgent': 'video',
            'AudioAgent': 'audio', 'TalkingCharacterAgent': 'talking character video',
            'ImageEditingAgent': 'edited image', 'VideoEditingAgent': 'edited video',
            'ThreeDAgent': '3D render', 'ResolveAgent': 'color-graded video',
            'image_generation_agent': 'image', 'video_generation_agent': 'video',
            'audio_generation_agent': 'audio', 'talking_character_agent': 'talking character video',
        }
        if agent_name in _MEDIA_AGENTS and result.success:
            push_user_id = context.get('user_id')
            if push_user_id:
                try:
                    from core.services.expo_push import send_push_to_user
                    media_type = _MEDIA_TYPE_LABELS.get(agent_name, 'media')
                    send_push_to_user(
                        user_id=push_user_id,
                        title=f'Your {media_type} is ready!',
                        body=(task[:80] + '...') if len(task) > 80 else task,
                        route='/media',
                        object_type='media_complete',
                        object_id=str(execution_record.id) if execution_record else None,
                    )
                except Exception as e:
                    logger.warning('[execute_agent_task] Push failed: %s', e)

        return {
            'success': result.success,
            'agent_name': agent_name,
            'task': task,
            'content': result.content[:1000] if result.content else None,
            'execution_time_ms': execution_time_ms,
            'execution_id': str(execution_record.id) if execution_record else None,
            'conversation_id': conversation_id,
        }

    except SoftTimeLimitExceeded:
        execution_time_ms = int((time.time() - execution_start) * 1000)
        logger.error(f"[execute_agent_task] KILLED by soft_time_limit: {agent_name} after {execution_time_ms}ms")
        if execution_record:
            execution_record.status = 'failed'
            execution_record.error_message = 'Celery soft_time_limit exceeded (60 min)'
            execution_record.execution_time_ms = execution_time_ms
            execution_record.completed_at = timezone.now()
            execution_record.save()
        return {
            'success': False,
            'agent_name': agent_name,
            'task': task,
            'error': 'Celery soft_time_limit exceeded (60 min)',
            'execution_time_ms': execution_time_ms,
            'conversation_id': conversation_id,
        }

    except Exception as e:
        execution_time_ms = int((time.time() - execution_start) * 1000)
        logger.error(f"[execute_agent_task] Failed: {agent_name} - {e}")

        # Update execution record on failure
        if execution_record:
            execution_record.status = 'failed'
            execution_record.error_message = str(e) or f'{type(e).__name__}: (no message)'
            execution_record.execution_time_ms = execution_time_ms
            execution_record.completed_at = timezone.now()
            execution_record.save()

        # Retry on certain errors
        if self.request.retries < self.max_retries:
            raise self.retry(exc=e)

        return {
            'success': False,
            'agent_name': agent_name,
            'task': task,
            'error': str(e),
            'execution_time_ms': execution_time_ms,
            'conversation_id': conversation_id,
        }


# ==================== CREATE TALKING VIDEO PIPELINE ====================


@shared_task(bind=True, max_retries=1, default_retry_delay=60, soft_time_limit=3600, time_limit=3900)
def create_talking_video_task(
    self,
    image_prompt: str,
    script: str,
    context: Dict[str, Any] = None
) -> Dict[str, Any]:
    """
    Pipeline task: generate a character image then create a talking video from it.
    Chains ImageAgent → TalkingCharacterAgent in a single Celery task so the PA
    doesn't need to poll across conversation turns.

    Args:
        image_prompt: Description of the character image to generate
        script: Text script for the character to speak
        context: Additional context (voice, mode, duration, color_grade, etc.)
    """
    from core.agent_router import AgentRouter
    from core.models_unified_system import Agent, AgentExecution
    import json as _json

    context = context if isinstance(context, dict) else {}
    execution_start = time.time()

    # Resolve user for media ownership
    _route_user = None
    _route_user_id = context.get('user_id')
    if _route_user_id:
        try:
            from django.contrib.auth import get_user_model
            _route_user = get_user_model().objects.filter(id=_route_user_id).first()
        except Exception:
            pass

    # Create execution record
    agent_obj = Agent.objects.filter(name='TalkingCharacterAgent').first()
    execution_record = None
    if agent_obj:
        _raw_input = {
            'task': f'Pipeline: image "{image_prompt[:100]}" → talking video',
            'image_prompt': image_prompt,
            'script': script[:500],
            'context': context,
            'source': 'create_talking_video_pipeline',
            'celery_task_id': str(self.request.id),
        }
        try:
            input_data = _json.loads(_json.dumps(_raw_input, default=str))
        except (TypeError, ValueError):
            input_data = {'task': 'create_talking_video_pipeline',
                          'celery_task_id': str(self.request.id)}

        execution_record = AgentExecution.objects.create(
            agent=agent_obj,
            task=f'Pipeline: image → talking video: {script[:200]}',
            status='in_progress',
            input_data=input_data,
        )

    try:
        # ── Step 1: Generate character image ──
        logger.info(
            f"[create_talking_video] Step 1/2: Generating image — "
            f"'{image_prompt[:60]}...' (celery_id={self.request.id})"
        )
        router = AgentRouter(user=_route_user)
        # Enhance image prompt for talking-video suitability (front-facing portrait for lip sync)
        _lp = image_prompt.lower()
        if not any(kw in _lp for kw in ('portrait', 'front-facing', 'front facing', 'headshot', 'face closeup')):
            image_prompt = (
                image_prompt.rstrip('. ')
                + ', front-facing portrait, centered composition, clear visible mouth and face,'
                ' studio lighting, suitable for animation and lip sync'
            )
        img_task_text = f'Generate image: {image_prompt}'
        img_result = router.route(
            agent_name='ImageAgent',
            task=img_task_text,
            context={
                'source': 'create_talking_video_pipeline',
                **context,
            }
        )

        if not img_result.success:
            error_msg = img_result.error or img_result.message or 'ImageAgent returned failure'
            logger.error(f"[create_talking_video] Image generation failed: {error_msg}")
            if execution_record:
                execution_record.status = 'failed'
                execution_record.error_message = f'Image generation failed: {error_msg}'[:2000]
                execution_record.execution_time_ms = int((time.time() - execution_start) * 1000)
                execution_record.completed_at = timezone.now()
                execution_record.save()
            return {
                'success': False,
                'agent_name': 'ImageAgent → TalkingCharacterAgent',
                'stage': 'image_generation',
                'error': error_msg,
                'execution_time_ms': int((time.time() - execution_start) * 1000),
            }

        # Extract image URL from result
        img_data = getattr(img_result, 'data', {}) or {}
        image_url = None
        if isinstance(img_data.get('images'), list) and img_data['images']:
            image_url = img_data['images'][0].get('image_url') or img_data['images'][0].get('url')
        if not image_url:
            # Fallback: check other common locations
            image_url = img_data.get('image_url') or img_data.get('url')
        if not image_url:
            logger.error(f"[create_talking_video] No image URL in result: {list(img_data.keys())}")
            if execution_record:
                execution_record.status = 'failed'
                execution_record.error_message = 'Image generated but no URL found in result'
                execution_record.execution_time_ms = int((time.time() - execution_start) * 1000)
                execution_record.completed_at = timezone.now()
                execution_record.save()
            return {
                'success': False,
                'agent_name': 'ImageAgent → TalkingCharacterAgent',
                'stage': 'image_generation',
                'error': 'Image generated but no URL found in result',
                'image_data_keys': list(img_data.keys()),
                'execution_time_ms': int((time.time() - execution_start) * 1000),
            }

        logger.info(f"[create_talking_video] Step 1 complete — image_url: {image_url[:80]}...")

        # ── Step 2: Generate talking video ──
        logger.info(
            f"[create_talking_video] Step 2/2: Generating talking video — "
            f"script='{script[:60]}...' (celery_id={self.request.id})"
        )
        video_context = {
            **context,
            'image_url': image_url,
            'script': script,
            'source': 'create_talking_video_pipeline',
        }
        vid_result = router.route(
            agent_name='TalkingCharacterAgent',
            task=f'Generate talking character video: {script}',
            context=video_context,
        )

        execution_time_ms = int((time.time() - execution_start) * 1000)
        vid_data = getattr(vid_result, 'data', {}) or {}

        if execution_record:
            execution_record.status = 'completed' if vid_result.success else 'failed'
            execution_record.execution_time_ms = execution_time_ms
            execution_record.output_data = {
                'content': vid_result.content[:5000] if vid_result.content else None,
                'metadata': vid_data,
                'image_url': image_url,
                'pipeline': 'ImageAgent → TalkingCharacterAgent',
            }
            if not vid_result.success:
                execution_record.error_message = (
                    vid_result.error or vid_result.message or 'TalkingCharacterAgent returned failure'
                )[:2000]
            execution_record.completed_at = timezone.now()
            execution_record.save()

        # Push notification
        if vid_result.success and _route_user_id:
            try:
                from core.services.expo_push import send_push_to_user
                send_push_to_user(
                    user_id=_route_user_id,
                    title='Your talking video is ready!',
                    body=(script[:80] + '...') if len(script) > 80 else script,
                    route='/media',
                    object_type='media_complete',
                    object_id=str(execution_record.id) if execution_record else None,
                )
            except Exception as e:
                logger.warning('[create_talking_video] Push failed: %s', e)

        logger.info(
            f"[create_talking_video] Completed: success={vid_result.success}, "
            f"time={execution_time_ms}ms"
        )

        return {
            'success': vid_result.success,
            'agent_name': 'ImageAgent → TalkingCharacterAgent',
            'content': vid_result.content[:1000] if vid_result.content else None,
            'image_url': image_url,
            'final_video_url': vid_data.get('final_video_url'),
            'execution_time_ms': execution_time_ms,
            'execution_id': str(execution_record.id) if execution_record else None,
        }

    except SoftTimeLimitExceeded:
        execution_time_ms = int((time.time() - execution_start) * 1000)
        logger.error(f"[create_talking_video] KILLED by soft_time_limit after {execution_time_ms}ms")
        if execution_record:
            execution_record.status = 'failed'
            execution_record.error_message = 'Celery soft_time_limit exceeded (60 min)'
            execution_record.execution_time_ms = execution_time_ms
            execution_record.completed_at = timezone.now()
            execution_record.save()
        return {
            'success': False,
            'agent_name': 'ImageAgent → TalkingCharacterAgent',
            'error': 'Celery soft_time_limit exceeded (60 min)',
            'execution_time_ms': execution_time_ms,
        }

    except Exception as e:
        execution_time_ms = int((time.time() - execution_start) * 1000)
        logger.error(f"[create_talking_video] Failed: {e}")
        if execution_record:
            execution_record.status = 'failed'
            execution_record.error_message = str(e) or f'{type(e).__name__}: (no message)'
            execution_record.execution_time_ms = execution_time_ms
            execution_record.completed_at = timezone.now()
            execution_record.save()
        if self.request.retries < self.max_retries:
            raise self.retry(exc=e)
        return {
            'success': False,
            'agent_name': 'ImageAgent → TalkingCharacterAgent',
            'error': str(e),
            'execution_time_ms': execution_time_ms,
        }


# ==================== SESSION 884: INITIATIVE STAGE EXECUTION ====================


@shared_task(bind=True, max_retries=2, default_retry_delay=60, soft_time_limit=3600, time_limit=3900)
def execute_initiative_stage_task(
    self,
    initiative_id: str,
    stage_num: int,
    agent_name: str,
    task: str,
    context: Dict[str, Any] = None
) -> Dict[str, Any]:
    """
    Session 884: Execute a task linked to an Initiative stage.
    Session 1017: Added soft_time_limit=2700 (45 min) to kill hung agents.
    Session 1058: Raised to 3600/3900 (60/65 min). NOTE: soft_time_limit does NOT
    enforce on --pool=threads (Railway) — SIGUSR1 only works with prefork. The
    WorkflowAgent wall-clock guard is the real timeout protection.

    This task is part of the Conversation-to-Initiative pipeline.
    When complete, it updates the stage and potentially advances the Initiative.

    Args:
        initiative_id: ID of the Initiative
        stage_num: Stage number (1-5)
        agent_name: Name of the agent to execute the task
        task: Task description
        context: Additional context

    Returns:
        Dict with execution result and stage update info
    """
    from core.agent_router import AgentRouter
    from core.services.conversation_initiative_pipeline import handle_stage_task_completion

    context = context or {}
    execution_start = time.time()

    logger.info(
        f"[execute_initiative_stage_task] Starting: {agent_name} for Initiative {initiative_id[:8]} "
        f"Stage {stage_num}: '{task[:50]}...'"
    )

    try:
        # Execute the agent task
        router = AgentRouter()
        result = router.route(
            agent_name=agent_name,
            task=task,
            context={
                'source': 'initiative_stage_task',
                'initiative_id': initiative_id,
                'stage_num': stage_num,
                **context
            }
        )

        execution_time_ms = int((time.time() - execution_start) * 1000)

        # Session 1041: Use helper to extract real content from AgentResult.
        # Many agents put summaries in .message and actual content in .data.
        actual_content = _extract_agent_content(result)

        # Build task result for stage handler
        task_result = {
            'success': result.success,
            'content': actual_content[:5000] if actual_content else '',
            'error': result.error,
            'execution_time_ms': execution_time_ms,
        }

        # Handle stage completion (update stage, advance if ready, enrich deliverable)
        stage_update = handle_stage_task_completion(
            initiative_id=initiative_id,
            stage_num=stage_num,
            agent_name=agent_name,
            task_result=task_result,
        )

        if execution_time_ms > 2_400_000:  # 40 min
            logger.warning(
                f"[execute_initiative_stage_task] SLOW AGENT: {agent_name} took "
                f"{execution_time_ms // 60_000}min — approaching timeout"
            )

        logger.info(
            f"[execute_initiative_stage_task] Completed: {agent_name} Stage {stage_num} "
            f"(success={result.success}, stage_advanced={stage_update.get('stage_advanced')})"
        )

        # Session 908: Create WorkspaceOperation for Initiative tracking
        if result.success and result.content:
            try:
                from core.models_document_registry import Initiative
                from core.models_skin_layer import WorkspaceOperation
                from core.services.workspace_manager import WorkspaceManager
                from django.contrib.auth import get_user_model
                User = get_user_model()

                initiative = Initiative.objects.get(id=initiative_id)

                # Get workspace - prefer initiative's target, fall back to user's active
                workspace = initiative.target_workspace
                if not workspace:
                    # Try to get system user's workspace
                    system_user = User.objects.filter(username='system_autonomous').first()
                    if system_user:
                        manager = WorkspaceManager(system_user)
                        workspace = manager.get_active_workspace()

                if workspace:
                    # Create workspace operation to track this Initiative work
                    WorkspaceOperation.objects.create(
                        workspace=workspace,
                        user=workspace.user,
                        agent_name=agent_name,
                        agent_task=task[:500] if task else '',
                        operation_type='file_create',
                        file_path=f'initiatives/{initiative.name[:50]}/stage_{stage_num}.md',
                        file_content_after=result.content[:10000] if result.content else '',
                        success=True,
                        initiative_id=initiative.id,
                        trigger_source='initiative',
                        run_mode='production',
                        execution_time_ms=execution_time_ms,
                    )
                    logger.info(f"[execute_initiative_stage_task] Created WorkspaceOperation for {initiative.name[:30]} Stage {stage_num}")
            except Exception as ws_error:
                logger.warning(f"[execute_initiative_stage_task] Could not create WorkspaceOperation: {ws_error}")

        return {
            'success': result.success,
            'agent_name': agent_name,
            'initiative_id': initiative_id,
            'stage_num': stage_num,
            'task': task,
            'content': result.content[:1000] if result.content else None,
            'execution_time_ms': execution_time_ms,
            'stage_update': stage_update,
        }

    except SoftTimeLimitExceeded:
        execution_time_ms = int((time.time() - execution_start) * 1000)
        logger.error(f"[execute_initiative_stage_task] KILLED by soft_time_limit: {agent_name} after {execution_time_ms}ms")
        try:
            handle_stage_task_completion(
                initiative_id=initiative_id,
                stage_num=stage_num,
                agent_name=agent_name,
                task_result={'success': False, 'error': 'Celery soft_time_limit exceeded (60 min)'},
            )
        except Exception:
            pass
        return {
            'success': False,
            'agent_name': agent_name,
            'initiative_id': initiative_id,
            'stage_num': stage_num,
            'task': task,
            'error': 'Celery soft_time_limit exceeded (60 min)',
            'execution_time_ms': execution_time_ms,
        }

    except Exception as e:
        execution_time_ms = int((time.time() - execution_start) * 1000)
        logger.error(f"[execute_initiative_stage_task] Failed: {agent_name} - {e}")

        # Still try to update stage with failure info
        try:
            handle_stage_task_completion(
                initiative_id=initiative_id,
                stage_num=stage_num,
                agent_name=agent_name,
                task_result={'success': False, 'error': str(e)},
            )
        except Exception as e2:
            logger.warning(f"Failed to record stage task failure: {e2}")

        if self.request.retries < self.max_retries:
            raise self.retry(exc=e)

        return {
            'success': False,
            'agent_name': agent_name,
            'initiative_id': initiative_id,
            'stage_num': stage_num,
            'task': task,
            'error': str(e),
            'execution_time_ms': execution_time_ms,
        }


# ==================== SESSION 812: CONTENT PRODUCTION ORCHESTRATION ====================


@shared_task(bind=True, max_retries=1, default_retry_delay=120)
def produce_content_package(
    self,
    production_id: str,
    content_type: str,
    topic: str,
    context: Dict[str, Any] = None,
    skip_assets: list = None,
    user_id: int = None
) -> Dict[str, Any]:
    """
    Session 812: Produce a complete content package asynchronously.

    This task orchestrates multiple agents to create complete content packages
    (blog posts with images, podcasts with artwork, etc.).

    Args:
        production_id: Unique ID for this production
        content_type: Type of content (blog_post, podcast, video, etc.)
        topic: Main topic for the content
        context: Additional context (tone, target_audience, etc.)
        skip_assets: List of asset types to skip
        user_id: User ID for context

    Returns:
        Dict with production results including all created assets
    """
    from core.services.content_production_orchestrator import ContentProductionOrchestrator

    context = context or {}
    skip_assets = skip_assets or []

    logger.info(
        f"[produce_content_package] Starting production {production_id}: "
        f"{content_type} - {topic}"
    )

    try:
        # Get user if user_id provided
        user = None
        if user_id:
            from django.contrib.auth import get_user_model
            User = get_user_model()
            user = User.objects.filter(id=user_id).first()

        orchestrator = ContentProductionOrchestrator(user=user)

        # Execute production synchronously (within the async task)
        result = orchestrator.produce_content(
            content_type=content_type,
            topic=topic,
            context=context,
            skip_assets=skip_assets,
            async_mode=False  # Don't re-queue, execute directly
        )

        logger.info(
            f"[produce_content_package] Completed {production_id}: "
            f"status={result.status}, assets={len(result.assets)}"
        )

        return result.to_dict()

    except Exception as e:
        logger.error(f"[produce_content_package] Failed {production_id}: {e}")

        if self.request.retries < self.max_retries:
            raise self.retry(exc=e)

        return {
            'production_id': production_id,
            'content_type': content_type,
            'topic': topic,
            'status': 'failed',
            'error': str(e),
        }


@shared_task(bind=True)
def run_spider_by_category(self, category: str):
    """
    Run spiders for a specific category.

    Session 265 Phase 6: Used by autonomy engine for spider dispatch.
    Session 484: Added SpiderExecutionLog for tracking.
    """
    from ai_core.spiders.spider_registry import SpiderRegistry
    from core.models_unified_system import SpiderExecutionLog
    import traceback

    try:
        registry = SpiderRegistry()
        spiders = registry.get_spiders_by_category(category)

        results = []
        for spider_name in spiders[:3]:  # Limit to 3 spiders per category
            # Session 484: Create execution log
            execution_log = SpiderExecutionLog.start_execution(
                spider_name=spider_name,
                category=category,
                triggered_by='on_demand',
                celery_task_id=self.request.id if self.request else None
            )
            spider_start_time = time.time()

            try:
                spider_class = registry.get_spider_class(spider_name)
                if spider_class:
                    # Session 503: Try both constructor patterns
                    try:
                        spider = spider_class()
                    except TypeError:
                        spider = spider_class(
                            spider_id=spider_name,
                            targets=[],
                            subscribers=[],
                            redis_config={'host': 'localhost', 'port': 6379, 'db': 0}
                        )

                    # Session 503: Support multiple method patterns
                    if hasattr(spider, 'fetch'):
                        data = spider.fetch()
                    elif hasattr(spider, 'fetch_data'):
                        import asyncio
                        import inspect
                        from ai_core.spiders.base_spider import SpiderTarget

                        async def run_fetch():
                            # Session 503: Detect method signature - some spiders use fetch_data(target),
                            # others use fetch_data(max_results=100)
                            fetch_method = spider.fetch_data
                            sig = inspect.signature(fetch_method)
                            params = list(sig.parameters.keys())

                            # Check first param type hint or name
                            first_param = params[0] if params else None
                            if first_param and first_param in ('target', 'url'):
                                # Standard BaseIntelligenceSpider pattern
                                target = SpiderTarget(url='internal://spider-execution')
                                raw = await spider.fetch_data(target)
                            else:
                                # Legal spiders pattern: fetch_data(max_results=100)
                                if asyncio.iscoroutinefunction(fetch_method):
                                    raw = await spider.fetch_data()
                                else:
                                    raw = spider.fetch_data()

                            if raw and hasattr(spider, 'process_data'):
                                target = SpiderTarget(url='internal://spider-execution')
                                if asyncio.iscoroutinefunction(spider.process_data):
                                    result = await spider.process_data(raw, target)
                                else:
                                    result = spider.process_data(raw, target)
                                if result:
                                    return {'items': [result.content] if hasattr(result, 'content') else [], 'raw_data': raw}
                            return raw if raw else {'items': []}

                        data = asyncio.run(run_fetch())
                    else:
                        data = {'items': []}

                    item_count = len(data) if isinstance(data, list) else len(data.get('items', []) if isinstance(data, dict) else [])
                    results.append({
                        'spider': spider_name,
                        'items': item_count,
                    })
                    # Session 484: Mark success
                    execution_log.complete_success(
                        items_collected=item_count,
                        duration_seconds=time.time() - spider_start_time
                    )
            except Exception as spider_error:
                logger.warning(f"Spider {spider_name} failed: {spider_error}")
                # Session 484: Mark error
                execution_log.complete_error(
                    error_message=str(spider_error),
                    error_type=type(spider_error).__name__,
                    error_traceback=traceback.format_exc(),
                    duration_seconds=time.time() - spider_start_time
                )

        logger.info(f"Ran {len(results)} spiders for category {category}")
        return {'category': category, 'results': results}

    except Exception as e:
        logger.error(f"Spider dispatch failed for {category}: {e}")
        return {'error': str(e)}


@shared_task(bind=True)
def execute_single_spider(self, spider_name: str, execution_log_id: str = None):
    """
    Session 484: Execute a single spider with full execution logging.
    Used by manual UI runs and retry operations.
    """
    from ai_core.spiders.spider_registry import SpiderRegistry
    from ai_core.spiders.real_data_collector import collect_spider_data_sync, SPIDER_TARGET_URLS
    from core.models_unified_system import SpiderData, SpiderExecutionLog
    import traceback

    spider_start_time = time.time()
    execution_log = None
    source_urls = []

    try:
        # Get or create execution log
        if execution_log_id:
            try:
                execution_log = SpiderExecutionLog.objects.get(id=execution_log_id)
                execution_log.celery_task_id = self.request.id if self.request else None
                execution_log.save()
            except SpiderExecutionLog.DoesNotExist:
                pass

        if not execution_log:
            # Find most recent running log for this spider
            execution_log = SpiderExecutionLog.objects.filter(
                spider_name=spider_name,
                status='running',
                celery_task_id__isnull=True
            ).order_by('-started_at').first()

            if execution_log:
                execution_log.celery_task_id = self.request.id if self.request else None
                execution_log.save()

        logger.info(f"🕷️ Executing single spider: {spider_name}")

        # Get spider info
        registry = SpiderRegistry()
        spider_config = registry.list_spiders().get(spider_name, {})
        config = spider_config.get('config', {})
        category = config.get('category', spider_config.get('category', 'general'))

        # Execute spider
        if spider_name in SPIDER_TARGET_URLS:
            source_urls = SPIDER_TARGET_URLS.get(spider_name, [])
            data = collect_spider_data_sync(spider_name)
            item_count = data.get('item_count', 0)
        else:
            spider_class = registry.get_spider_class(spider_name)
            if spider_class:
                # Session 503: Try both constructor patterns
                try:
                    spider = spider_class()
                except TypeError:
                    # Spider requires full constructor args
                    spider = spider_class(
                        spider_id=spider_name,
                        targets=[],
                        subscribers=[],
                        redis_config={'host': 'localhost', 'port': 6379, 'db': 0}
                    )

                if hasattr(spider, 'fetch'):
                    data = spider.fetch()
                elif hasattr(spider, 'scrape'):
                    import asyncio
                    data = asyncio.run(spider.scrape())
                elif hasattr(spider, 'fetch_data'):
                    # Session 503: Support for spiders using fetch_data(target) or fetch_data(max_results) pattern
                    import asyncio
                    import inspect
                    from ai_core.spiders.base_spider import SpiderTarget

                    async def run_fetch():
                        # Detect method signature
                        fetch_method = spider.fetch_data
                        sig = inspect.signature(fetch_method)
                        params = list(sig.parameters.keys())

                        first_param = params[0] if params else None
                        if first_param and first_param in ('target', 'url'):
                            # Standard BaseIntelligenceSpider pattern
                            target = SpiderTarget(url='internal://spider-execution')
                            raw = await spider.fetch_data(target)
                        else:
                            # Legal spiders pattern: fetch_data(max_results=100)
                            if asyncio.iscoroutinefunction(fetch_method):
                                raw = await spider.fetch_data()
                            else:
                                raw = spider.fetch_data()

                        if raw and hasattr(spider, 'process_data'):
                            target = SpiderTarget(url='internal://spider-execution')
                            if asyncio.iscoroutinefunction(spider.process_data):
                                result = await spider.process_data(raw, target)
                            else:
                                result = spider.process_data(raw, target)
                            if result:
                                return {'items': [result.content] if hasattr(result, 'content') else [], 'raw_data': raw}
                        # Normalize return value to dict format
                        if raw:
                            if isinstance(raw, list):
                                return {'items': raw, 'source': spider_name}
                            elif isinstance(raw, dict):
                                return raw
                            else:
                                return {'items': [raw], 'source': spider_name}
                        return {'items': []}

                    data = asyncio.run(run_fetch())
                else:
                    data = {'items': [], 'message': 'Spider has no fetch/scrape/fetch_data method'}
                # Handle both list and dict formats
                if isinstance(data, list):
                    item_count = len(data)
                    data = {'items': data, 'source': spider_name}
                else:
                    item_count = len(data.get('items', []))
            else:
                data = {'items': [], 'error': f'Spider class not found: {spider_name}'}
                item_count = 0

        # Session 616: Item-level deduplication
        from core.services.spider_deduplication import deduplicate_spider_items

        items = data.get('items', []) if isinstance(data, dict) else []
        unique_items, dedup_stats = deduplicate_spider_items(spider_name, items, category)

        # Only save if there are unique items
        if unique_items:
            # Update data with only unique items
            if isinstance(data, dict):
                data['items'] = unique_items
                data['dedup_stats'] = dedup_stats

            spider_data = SpiderData.objects.create(
                spider_name=spider_name,
                data_type=category,
                raw_data=data if isinstance(data, dict) else {'data': str(data)},
                source_url=source_urls[0] if source_urls else 'manual',
                relevance_score=70 if len(unique_items) > 0 else 30
            )
            item_count = len(unique_items)
            logger.info(f"✅ Spider {spider_name} completed: {item_count} unique items (dedup: {dedup_stats['duplicates']} removed)")
        else:
            # No unique items - skip creating SpiderData record
            spider_data = None
            item_count = 0
            logger.info(f"⏭️ Spider {spider_name}: all {dedup_stats['total']} items already seen, skipping save")

        # Update execution log
        if execution_log:
            execution_log.source_urls_attempted = source_urls if source_urls else ['manual']
            execution_log.complete_success(
                items_collected=item_count,
                duration_seconds=time.time() - spider_start_time
            )

        return {
            'spider': spider_name,
            'success': True,
            'item_count': item_count,
            'data_id': str(spider_data.id) if spider_data else None,
            'dedup_stats': dedup_stats,  # Session 616: Include dedup stats
        }

    except Exception as e:
        logger.error(f"❌ Spider {spider_name} failed: {e}")

        # Update execution log with error
        if execution_log:
            execution_log.source_urls_attempted = source_urls if source_urls else []
            execution_log.complete_error(
                error_message=str(e),
                error_type=type(e).__name__,
                error_traceback=traceback.format_exc(),
                duration_seconds=time.time() - spider_start_time
            )

        return {
            'spider': spider_name,
            'success': False,
            'error': str(e),
        }


@shared_task(bind=True, max_retries=3)
def isolate_documents_batch(self, batch_size: int = 50, max_batches: int = None):
    """
    Background task to gradually isolate documents with proper namespaces
    
    Args:
        batch_size: Number of documents to process per batch
        max_batches: Maximum number of batches to process (None = all)
    
    Returns:
        Dict with processing statistics
    """
    from content.models import Document, DocumentEmbedding
    
    try:
        logger.info(f"Starting document isolation batch task - batch_size: {batch_size}")
        
        # Import classifier from our batch tagging script
        import sys
        sys.path.append(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
        
        from batch_tag_documents import DocumentClassifier
        classifier = DocumentClassifier()
        
        # Get untagged documents
        untagged_query = Document.objects.exclude(
            metadata__has_key='namespace'
        )
        
        total_untagged = untagged_query.count()
        
        if total_untagged == 0:
            logger.info("No untagged documents found!")
            return {
                'status': 'completed',
                'processed': 0,
                'total_found': 0,
                'message': 'No documents need processing'
            }
        
        logger.info(f"Found {total_untagged} untagged documents")
        
        # Process in batches
        stats = {
            'personal': 0,
            'system': 0,
            'agent_memory': 0,
            'public': 0,
            'errors': 0,
            'processed': 0
        }
        
        batch_count = 0
        start_time = time.time()
        
        while True:
            # Check if we should stop
            if max_batches and batch_count >= max_batches:
                logger.info(f"Reached max_batches limit: {max_batches}")
                break
            
            # Get next batch
            batch = untagged_query[:batch_size]
            
            if not batch:
                logger.info("No more documents to process")
                break
            
            batch_start_time = time.time()
            
            with transaction.atomic():
                for doc in batch:
                    try:
                        # Classify document
                        namespace = classifier.classify_document(doc)
                        
                        # Update metadata
                        if not doc.metadata:
                            doc.metadata = {}
                        
                        doc.metadata.update({
                            'namespace': namespace,
                            'tagged_at': datetime.now().isoformat(),
                            'tagged_by': 'celery_background_task',
                            'searchable_by_agents': namespace != 'personal',
                            'is_private': namespace == 'personal',
                            'task_id': self.request.id  # Track which task processed this
                        })
                        
                        doc.save()
                        
                        # Update associated embeddings
                        embeddings = DocumentEmbedding.objects.filter(document=doc)
                        for emb in embeddings:
                            if not emb.metadata:
                                emb.metadata = {}
                            emb.metadata.update({
                                'namespace': namespace,
                                'is_private': namespace == 'personal',
                                'task_id': self.request.id
                            })
                            emb.save()
                        
                        stats[namespace] += 1
                        stats['processed'] += 1
                        
                    except Exception as e:
                        logger.error(f"Error processing document {doc.id}: {e}")
                        stats['errors'] += 1
                        stats['processed'] += 1
            
            batch_count += 1
            batch_time = time.time() - batch_start_time
            total_time = time.time() - start_time
            
            # Update task progress
            self.update_state(
                state='PROGRESS',
                meta={
                    'processed': stats['processed'],
                    'total_found': total_untagged,
                    'batch_count': batch_count,
                    'stats': stats,
                    'rate_per_second': stats['processed'] / total_time if total_time > 0 else 0,
                    'batch_time': batch_time
                }
            )
            
            logger.info(f"Batch {batch_count} completed: {len(batch)} docs in {batch_time:.1f}s")
            logger.info(f"Progress: {stats['processed']} processed, {stats}")
            
            # Small delay to avoid overwhelming the database
            time.sleep(0.1)
        
        # Final statistics
        total_time = time.time() - start_time
        rate = stats['processed'] / total_time if total_time > 0 else 0
        
        logger.info("=== BACKGROUND DOCUMENT ISOLATION COMPLETED ===")
        logger.info(f"Processed: {stats['processed']} documents in {total_time:.1f} seconds")
        logger.info(f"Rate: {rate:.1f} documents/second")
        logger.info(f"Distribution: {stats}")
        
        return {
            'status': 'completed',
            'processed': stats['processed'],
            'total_found': total_untagged,
            'batch_count': batch_count,
            'total_time': total_time,
            'rate_per_second': rate,
            'distribution': {k: v for k, v in stats.items() if k != 'processed'},
            'message': f'Successfully processed {stats["processed"]} documents'
        }
        
    except Exception as exc:
        logger.error(f"Document isolation task failed: {exc}")
        # Retry with exponential backoff
        raise self.retry(exc=exc, countdown=60 * (2 ** self.request.retries))

@shared_task
def monitor_isolation_progress():
    """
    Monitoring task to check overall isolation progress
    
    Returns:
        Dict with current isolation status
    """
    try:
        from content.models import Document
        
        total = Document.objects.count()
        
        namespace_counts = {}
        namespaces = ['personal', 'system', 'agent_memory', 'public']
        
        for namespace in namespaces:
            count = Document.objects.filter(metadata__namespace=namespace).count()
            namespace_counts[namespace] = count
        
        untagged = Document.objects.exclude(metadata__has_key='namespace').count()
        tagged = total - untagged
        
        progress_pct = (tagged / total * 100) if total > 0 else 0
        
        status = {
            'total_documents': total,
            'tagged': tagged,
            'untagged': untagged,
            'progress_percentage': round(progress_pct, 1),
            'distribution': namespace_counts,
            'timestamp': datetime.now().isoformat()
        }
        
        logger.info(f"Isolation Progress: {progress_pct:.1f}% ({tagged}/{total})")
        logger.info(f"Distribution: {namespace_counts}")
        
        return status
        
    except Exception as e:
        logger.error(f"Monitoring task failed: {e}")
        return {
            'error': str(e),
            'timestamp': datetime.now().isoformat()
        }

@shared_task
def cleanup_isolation_metadata():
    """
    Cleanup task to remove duplicate or corrupted isolation metadata
    """
    try:
        from content.models import Document
        from django.db.models import Q
        
        cleaned_count = 0
        
        # Find documents with invalid namespace values
        invalid_docs = Document.objects.filter(
            ~Q(metadata__namespace__in=['personal', 'system', 'agent_memory', 'public'])
        ).filter(metadata__has_key='namespace')
        
        for doc in invalid_docs:
            logger.info(f"Cleaning invalid namespace for document {doc.id}")
            
            # Remove invalid namespace and let the isolation task re-process
            if 'namespace' in doc.metadata:
                del doc.metadata['namespace']
            if 'tagged_by' in doc.metadata:
                del doc.metadata['tagged_by']
            
            doc.save()
            cleaned_count += 1
        
        logger.info(f"Cleanup completed: {cleaned_count} documents cleaned")
        
        return {
            'status': 'completed',
            'cleaned_count': cleaned_count,
            'timestamp': datetime.now().isoformat()
        }
        
    except Exception as e:
        logger.error(f"Cleanup task failed: {e}")
        return {
            'error': str(e),
            'timestamp': datetime.now().isoformat()
        }

