@shared_task
def score_opportunities_from_spider_data(hours: int = 24, limit: int = 100):
    """
    Score spider data and create opportunities.

    This task runs on a schedule to transform raw spider data
    into scored, actionable opportunities.

    Args:
        hours: Look back period in hours (default: 24)
        limit: Maximum items to process (default: 100)

    Returns:
        Dict with scoring statistics
    """
    logger.info(f"🎯 [OPPORTUNITY ENGINE] Starting opportunity scoring - last {hours}h, limit: {limit}")

    try:
        from core.agents.analysis import OpportunityScoringAgent

        agent = OpportunityScoringAgent()
        results = agent.score_spider_data(hours=hours, limit=limit)

        # Count successful scores
        successful = [r for r in results if r.success]
        high_value = [r for r in successful if r.overall_score >= 70]

        stats = {
            'status': 'completed',
            'total_processed': len(results),
            'successful': len(successful),
            'high_value_opportunities': len(high_value),
            'average_score': sum(r.overall_score for r in successful) / len(successful) if successful else 0,
        }

        logger.info(f"🎯 [OPPORTUNITY ENGINE] Completed - {len(successful)} opportunities scored, {len(high_value)} high-value")
        return stats

    except Exception as e:
        logger.error(f"❌ [OPPORTUNITY ENGINE] Task failed: {e}")
        return {
            'status': 'failed',
            'error': str(e)
        }


@shared_task
def execute_pending_opportunity_tasks(limit: int = 20):
    """
    Session 672: Execute pending OpportunityTasks by triggering assigned agents.

    This task completes the ML Opportunity Pipeline by automatically executing
    agents assigned to high-scoring opportunities.

    Pipeline flow:
    Spiders → SpiderData → ML Score → Opportunity → Task → [THIS] → Agent → Outcome

    Args:
        limit: Maximum tasks to execute per run (default: 20)

    Returns:
        Dict with execution statistics
    """
    logger.info(f"🤖 [AGENT EXECUTOR] Starting execution of pending opportunity tasks (limit: {limit})")

    try:
        from core.models_unified_system import OpportunityTask, Agent
        from core.agent_router import AgentRouter
        from django.utils import timezone

        router = AgentRouter()

        # Find pending/accepted tasks with assigned agents
        pending_tasks = OpportunityTask.objects.filter(
            status__in=['pending', 'accepted'],
            primary_agent__isnull=False
        ).select_related(
            'primary_agent', 'opportunity', 'user'
        ).order_by(
            '-priority', '-opportunity_score', 'created_at'
        )[:limit]

        stats = {
            'status': 'completed',
            'tasks_found': pending_tasks.count(),
            'tasks_executed': 0,
            'tasks_succeeded': 0,
            'tasks_failed': 0,
            'errors': []
        }

        for task in pending_tasks:
            try:
                # Get agent class name (stored in Agent.name field)
                agent_name = task.primary_agent.name
                if not agent_name:
                    logger.warning(f"⚠️ [AGENT EXECUTOR] Task {task.id} has agent without name")
                    continue

                # Check if agent exists in router
                if not router.is_valid_agent(agent_name):
                    logger.warning(f"⚠️ [AGENT EXECUTOR] Unknown agent: {agent_name} for task {task.id}")
                    stats['errors'].append(f"Unknown agent: {agent_name}")
                    continue

                # Build execution context from opportunity
                opportunity = task.opportunity
                task_metadata = task.metadata or {}

                context = {
                    'task_id': str(task.id),
                    'task_title': task.title,
                    'task_description': task.description,
                    'opportunity_id': str(opportunity.id) if opportunity else None,
                    'opportunity_title': opportunity.title if opportunity else None,
                    'opportunity_source': opportunity.source if opportunity else None,
                    'opportunity_url': opportunity.url if opportunity else None,
                    'opportunity_score': task.opportunity_score,
                    'score_breakdown': task.score_breakdown,
                    'priority': task.priority,
                    'user_id': task.user_id,
                    'auto_execution': True,
                    # Include research context from metadata
                    'research_query': task_metadata.get('research_query'),
                    'research_topic': task_metadata.get('research_topic'),
                    'keywords': task_metadata.get('keywords', []),
                    'category': task_metadata.get('category'),
                }

                # Mark task as in_progress
                task.status = 'in_progress'
                task.save(update_fields=['status', 'updated_at'])

                logger.info(f"🤖 [AGENT EXECUTOR] Executing {agent_name} for task: {task.title[:50]}...")

                # Build agent-specific task prompts for better results
                if agent_name == 'ResearchAgent':
                    # Use research-optimized query from metadata
                    research_query = task_metadata.get('research_query') or task_metadata.get('clean_title') or task.title
                    research_topic = task_metadata.get('research_topic') or task.title
                    task_prompt = f"Research topic: {research_topic}\n\nSearch query: {research_query}"
                    if task.description:
                        task_prompt += f"\n\nContext: {task.description[:300]}"
                elif agent_name in ['ContentStrategyAgent', 'SEOOptimizerAgent', 'SocialMediaAgent']:
                    # Content agents need topic and category
                    category = task_metadata.get('category', 'general')
                    clean_title = task_metadata.get('clean_title') or task.title
                    task_prompt = f"Create content strategy for: {clean_title}\n\nCategory: {category}\n\nDescription: {task.description[:300] if task.description else 'N/A'}"
                else:
                    # Default prompt for other agents
                    task_prompt = f"Execute opportunity task: {task.title}\n\nDescription: {task.description}"

                # Execute agent via router (router gathers scifi_context and spider_context internally)
                result = router.route(
                    agent_name=agent_name,
                    task=task_prompt,
                    context=context
                )

                stats['tasks_executed'] += 1

                # Update task status based on result
                if result.success:
                    task.status = 'applied'  # Mark as applied/submitted
                    task.applied_at = timezone.now()
                    stats['tasks_succeeded'] += 1
                    logger.info(f"✅ [AGENT EXECUTOR] Task {task.id} completed successfully by {agent_name}")
                else:
                    task.status = 'pending'  # Reset to pending for retry
                    stats['tasks_failed'] += 1
                    stats['errors'].append(f"Task {task.id}: {result.error or 'Unknown error'}")
                    logger.warning(f"⚠️ [AGENT EXECUTOR] Task {task.id} failed: {result.error}")

                # Save result metadata
                if not task.score_breakdown:
                    task.score_breakdown = {}
                task.score_breakdown['execution_result'] = {
                    'agent': agent_name,
                    'success': result.success,
                    'executed_at': timezone.now().isoformat(),
                    'message_preview': str(result.message)[:500] if result.message else None,
                }
                task.save()

            except Exception as task_error:
                logger.error(f"❌ [AGENT EXECUTOR] Error executing task {task.id}: {task_error}")
                stats['tasks_failed'] += 1
                stats['errors'].append(f"Task {task.id}: {str(task_error)}")
                # Reset task to pending on error
                task.status = 'pending'
                task.save(update_fields=['status', 'updated_at'])

        logger.info(
            f"🤖 [AGENT EXECUTOR] Completed - "
            f"Executed: {stats['tasks_executed']}, "
            f"Succeeded: {stats['tasks_succeeded']}, "
            f"Failed: {stats['tasks_failed']}"
        )

        return stats

    except Exception as e:
        logger.error(f"❌ [AGENT EXECUTOR] Task failed: {e}")
        return {
            'status': 'failed',
            'error': str(e)
        }


@shared_task
def expire_old_opportunities():
    """
    Mark old opportunities as expired.

    Opportunities that haven't been acted upon within their
    time sensitivity window should be marked as expired.
    """
    logger.info("🎯 [OPPORTUNITY ENGINE] Checking for expired opportunities...")

    try:
        from core.models_unified_system import Opportunity
        from django.utils import timezone
        from datetime import timedelta

        now = timezone.now()

        # Find opportunities that have explicit expiration dates
        expired_by_date = Opportunity.objects.filter(
            expires_at__lt=now,
            status__in=['new', 'active', 'reviewing', 'approved']
        )

        # Find opportunities older than 7 days with high time sensitivity
        week_ago = now - timedelta(days=7)
        expired_by_timing = Opportunity.objects.filter(
            created_at__lt=week_ago,
            time_sensitivity__gte=80,
            status__in=['new', 'active', 'reviewing', 'approved']
        )

        # Find opportunities older than 30 days that haven't been acted upon
        month_ago = now - timedelta(days=30)
        expired_by_age = Opportunity.objects.filter(
            created_at__lt=month_ago,
            acted_on_at__isnull=True,
            status__in=['new', 'active', 'reviewing', 'approved']
        )

        # Combine and update
        expired_count = 0

        for queryset in [expired_by_date, expired_by_timing, expired_by_age]:
            count = queryset.update(status='expired')
            expired_count += count

        logger.info(f"🎯 [OPPORTUNITY ENGINE] Marked {expired_count} opportunities as expired")

        return {
            'status': 'completed',
            'expired_count': expired_count
        }

    except Exception as e:
        logger.error(f"❌ [OPPORTUNITY ENGINE] Expire task failed: {e}")
        return {
            'status': 'failed',
            'error': str(e)
        }


@shared_task
def generate_opportunity_report():
    """
    Generate a daily opportunity report.

    This creates a summary of:
    - New opportunities discovered
    - Top-scoring opportunities
    - Opportunities acted upon
    - Revenue from completed opportunities
    """
    logger.info("🎯 [OPPORTUNITY ENGINE] Generating daily opportunity report...")

    try:
        from core.models_unified_system import Opportunity
        from django.utils import timezone
        from django.db.models import Count, Avg
        from datetime import timedelta

        now = timezone.now()
        yesterday = now - timedelta(days=1)

        # Get statistics
        new_today = Opportunity.objects.filter(created_at__gte=yesterday).count()
        total_active = Opportunity.objects.filter(status__in=['new', 'active', 'reviewing', 'approved']).count()
        acted_today = Opportunity.objects.filter(acted_on_at__gte=yesterday).count()

        # Get top opportunities
        top_opportunities = list(
            Opportunity.objects.filter(
                status__in=['new', 'active'],
                overall_score__gte=70
            ).order_by('-overall_score')[:5].values('id', 'title', 'overall_score', 'category')
        )

        # Get category breakdown
        by_category = dict(
            Opportunity.objects.filter(
                status__in=['new', 'active', 'reviewing', 'approved'],
                category__isnull=False
            ).values('category').annotate(count=Count('id')).values_list('category', 'count')
        )

        # Get average scores
        avg_scores = Opportunity.objects.filter(
            overall_score__isnull=False
        ).aggregate(
            avg_overall=Avg('overall_score'),
            avg_profit=Avg('profit_potential'),
        )

        report = {
            'status': 'completed',
            'generated_at': now.isoformat(),
            'period': 'daily',
            'summary': {
                'new_opportunities': new_today,
                'total_active': total_active,
                'acted_upon_today': acted_today,
            },
            'top_opportunities': top_opportunities,
            'by_category': by_category,
            'average_scores': {
                'overall': round(avg_scores['avg_overall'] or 0, 1),
                'profit_potential': round(avg_scores['avg_profit'] or 0, 1),
            }
        }

        logger.info(f"🎯 [OPPORTUNITY ENGINE] Report generated - {new_today} new, {total_active} active")
        return report

    except Exception as e:
        logger.error(f"❌ [OPPORTUNITY ENGINE] Report generation failed: {e}")
        return {
            'status': 'failed',
            'error': str(e)
        }


