@shared_task(bind=True, soft_time_limit=240, time_limit=300)
def draft_legal_document_task(self, task_description, context=None, user_id=None):
    """
    Session 1062: Async legal document drafting via LegalDocDrafterAgent.
    Dispatched by PA legal_doc_drafter_agent handler to avoid PA tool timeout.
    """
    from core.agent_router import AgentRouter
    from django.contrib.auth import get_user_model

    user = None
    if user_id:
        User = get_user_model()
        user = User.objects.filter(id=user_id).first()

    router = AgentRouter(user=user)
    result = router.route(
        agent_name='LegalDocDrafterAgent',
        task=task_description,
        context=context or {},
    )

    output_text = ''
    if result:
        output_text = result.message or result.content or str(result)

    return {
        'agent': 'LegalDocDrafterAgent',
        'output': output_text,
        'success': bool(result and result.success),
        'data': result.data if result else {},
    }


@shared_task(bind=True)
def generate_blog_with_topic_task(self, topic, tone='enthusiastic'):
    """
    Session 1057: Generate a blog for a specific topic via the deliberation pipeline.
    Dispatched by PA generate_blog_tool when user provides a specific topic.
    """
    from core.services.content_deliberation_runner import ContentDeliberationRunner

    logger.info(f"[Phase 4] Starting topic-specific deliberation blog: topic={topic}, tone={tone}")

    runner = ContentDeliberationRunner()
    result = runner.run_blog(topic, voice=tone)

    status = result.get('status', 'unknown')
    decision = result.get('decision', 'unknown')
    selfblog_id = str(result['selfblog_id']) if result.get('selfblog_id') else None

    logger.info(f"[Phase 4] Topic blog complete: topic={topic}, status={status}, decision={decision}, id={selfblog_id}")

    return {
        'status': status,
        'decision': decision,
        'selfblog_id': selfblog_id,
        'topic': topic,
    }


@shared_task(bind=True, soft_time_limit=240, time_limit=300)
def generate_self_blog_deliberation_task(self, tone='enthusiastic', word_count=1500, topic_category=None):
    """
    Phase 4: Generate a blog through the multi-agent deliberation pipeline.

    Same signature as generate_self_blog_task but uses ContentDeliberationRunner
    for ClaimsPack -> Draft -> 3-reviewer panel -> DecisionEnforcer -> PublishGate.

    Session 1062: Added Redis lock (max_concurrency=1) to prevent OOM from
    concurrent deliberation tasks crashing celery-content every hour.

    Args:
        tone: Blog tone
        word_count: Target word count
        topic_category: Topic source ('trending', 'dreams', 'conversations', 'system', 'random')
    """
    import random
    from datetime import timedelta
    from django.utils import timezone

    # Session 1062: Only one deliberation at a time — prevents OOM on celery-content
    from django.core.cache import cache
    lock_key = 'deliberation_blog_running'
    if not cache.add(lock_key, self.request.id, timeout=300):
        logger.info(f"[Phase 4] Skipping deliberation — another is already running (lock={lock_key})")
        return {'success': False, 'skipped': True, 'reason': 'concurrent deliberation already running'}

    # Session 969: Weight away from 'system' for diversity
    if topic_category is None or topic_category == 'random':
        topic_category = random.choice(['trending', 'trending', 'dreams', 'conversations'])

    logger.info(f"[Phase 4] Starting deliberation blog: tone={tone}, category={topic_category}")

    try:
        blog_topic = None  # Session 969: No hardcoded default — use fallback pool

        if topic_category == 'trending':
            try:
                from core.models_unified_system import SpiderData
                now = timezone.now()
                recent = SpiderData.objects.filter(
                    created_at__gte=now - timedelta(hours=48)
                ).order_by('-created_at')[:20]
                for entry in recent:
                    raw = entry.raw_data
                    if isinstance(raw, str):
                        import json
                        try:
                            raw = json.loads(raw)
                        except Exception:
                            continue
                    if isinstance(raw, dict):
                        items = raw.get('items', [])
                        for item in items:
                            title = item.get('title', '')
                            if title and len(title) > 15:
                                blog_topic = title[:100]
                                break
                    if blog_topic:
                        break
            except Exception as e:
                logger.warning(f"[Phase 4] Trending topic fetch failed: {e}")

        elif topic_category == 'system':
            pass  # Session 969: Fall through to diversified fallback below

        elif topic_category == 'dreams':
            try:
                from core.models_unified_system import AgentDream
                dream = AgentDream.objects.order_by('-dreamed_at').first()
                if dream and dream.title:
                    blog_topic = dream.title[:100]
            except Exception as e:
                logger.warning(f"📝 [BLOG] Dream topic extraction failed: {e}")

        elif topic_category == 'conversations':
            try:
                from core.models_unified_system import AgentConversation
                convo = AgentConversation.objects.order_by('-started_at').first()
                if convo and convo.topic:
                    blog_topic = convo.topic[:100]
            except Exception as e:
                logger.warning(f"📝 [BLOG] Conversation topic extraction failed: {e}")

        # Session 969: Diversified fallback when no topic was found
        if not blog_topic:
            _v2_fallback_topics = [
                'How Smart Contract Auditing Is Evolving in 2026',
                'The Rise of Prediction Markets and What They Tell Us',
                'Why Sports Analytics Is the New Edge in Betting',
                'Building AI-Assisted Software: Lessons from the Trenches',
                'The Legal Tech Revolution Nobody Is Talking About',
                'Career Pivots in the Age of AI: What Actually Works',
                'What On-Chain Data Reveals About Whale Behavior',
                'The Next Wave of Open Source AI Models',
                'How Autonomous Systems Learn From Their Mistakes',
                'Market Signals: Reading Between the Headlines',
            ]
            blog_topic = random.choice(_v2_fallback_topics)
            logger.info(f"[Phase 4] Using diversified fallback topic: {blog_topic}")

        from core.services.content_deliberation_runner import ContentDeliberationRunner
        runner = ContentDeliberationRunner()
        result = runner.run_blog(topic=blog_topic, voice=tone)

        logger.info(
            f"[Phase 4] Deliberation complete: status={result['status']}, "
            f"decision={result['decision']}, blog={result['selfblog_id']}"
        )
        return {
            'success': result['selfblog_id'] is not None,
            'blog_id': result['selfblog_id'],
            'status': result['status'],
            'decision': result['decision'],
            'deliberation_session_id': result['deliberation_session_id'],
            'summary': result['summary'],
        }

    except Exception as e:
        logger.error(f"[Phase 4] Deliberation task failed: {e}", exc_info=True)
        return {'success': False, 'error': str(e)}

    finally:
        cache.delete(lock_key)


# =============================================================================
# SESSION 544: AUTONOMOUS REASONING ENGINE - THE THINKING LOOP
# =============================================================================

@shared_task(bind=True, soft_time_limit=1800, time_limit=1860, ignore_result=True)
def run_autonomous_thinking_cycle(self, cycle_type='scheduled', lookback_hours=24):
    """
    The Autonomous Reasoning Engine's thinking loop.

    This task runs periodically (or on-demand) to:
    1. Gather context from recent system activity
    2. Reflect on patterns and generate insights
    3. Decide what actions to take
    4. Execute those actions
    5. Record everything for learning

    This is the system becoming self-aware and proactive.

    Args:
        cycle_type: 'scheduled', 'triggered', 'manual', or 'continuous'
        lookback_hours: How far back to analyze (default 24h)

    Returns:
        dict with thinking results and actions taken
    """
    import time
    from django.utils import timezone

    logger.info(f"🧠 [THINKING] Starting autonomous thinking cycle (type={cycle_type})")
    start_time = time.time()

    def format_action_result(result: dict) -> str:
        """
        Session 572: Format action result as human-readable summary instead of raw dict.
        Extracts key information and presents it nicely.
        """
        if not result or not isinstance(result, dict):
            return str(result) if result else ''

        # Priority 1: Use the 'message' field if present (most common)
        if 'message' in result:
            return result['message']

        # Priority 2: Build a summary from key fields
        parts = []

        # For conversations
        if 'conversation_id' in result:
            initiator = result.get('initiator', 'Agent')
            other = result.get('other_agent', 'another agent')
            topic = result.get('topic', 'topic')
            parts.append(f"Conversation between {initiator} and {other} about '{topic}'")

        # For research
        elif 'research_complete' in result:
            topic = result.get('topic', 'topic')
            preview = result.get('findings_preview', '')
            parts.append(f"Research on '{topic}': {preview}" if preview else f"Research initiated on '{topic}'")

        # For reports
        elif 'report_id' in result:
            topic = result.get('topic', 'Report')
            insights = result.get('insights_count', 0)
            patterns = result.get('patterns_count', 0)
            parts.append(f"Created report on '{topic}' with {insights} insights, {patterns} patterns")

        # For spiders
        elif 'spider_type' in result:
            spider = result.get('spider_type', 'spider')
            topic = result.get('topic', 'data')
            parts.append(f"Spawned {spider} spider to gather '{topic}' data")

        # For debates
        elif 'debate_id' in result:
            topic = result.get('topic', 'topic')[:80]
            participants = result.get('participants', [])
            parts.append(f"Debate on '{topic}' with {len(participants)} participants")

        # For triage
        elif 'total_processed' in result:
            processed = result.get('total_processed', 0)
            promoted = result.get('promoted_to_boardroom', 0)
            archived = result.get('archived', 0)
            parts.append(f"Processed {processed} items: {promoted} promoted, {archived} archived")

        # For alerts
        elif 'sent_via' in result:
            severity = result.get('severity', 'info')
            via = result.get('sent_via', 'notification')
            parts.append(f"Alert sent via {via} (severity: {severity})")

        # Fallback: check for success/error indicators
        if not parts:
            if result.get('success') is False:
                error = result.get('error', 'Unknown error')
                return f"Failed: {error}"
            elif result.get('success') is True:
                return "Completed successfully"
            else:
                # Last resort: show first few key-value pairs
                items = list(result.items())[:3]
                return ', '.join(f"{k}: {v}" for k, v in items if not k.startswith('_'))[:200]

        return '; '.join(parts)[:500]

    try:
        from core.models_unified_system import (
            ThoughtRecord, AutonomousAction, ReasoningConfiguration
        )
        from core.agents.thinking_agent import ThinkingAgent
        from core.services.autonomous_action_executor import AutonomousActionExecutor

        # Get configuration
        config = ReasoningConfiguration.get_active_config()
        if not config.is_active:
            logger.info("🧠 [THINKING] Reasoning engine is disabled")
            return {'success': False, 'reason': 'Reasoning engine is disabled'}

        # Get the next cycle number
        last_thought = ThoughtRecord.objects.order_by('-cycle_number').first()
        cycle_number = (last_thought.cycle_number + 1) if last_thought else 1

        # Create the thought record (status: thinking)
        thought = ThoughtRecord.objects.create(
            cycle_number=cycle_number,
            cycle_type=cycle_type,
            context_summary="Gathering context...",
            context_data={},
            reflection="",
            execution_status='thinking'
        )

        logger.info(f"🧠 [THINKING] Cycle #{cycle_number} - Gathering context...")

        # Initialize the ThinkingAgent
        agent = ThinkingAgent()

        # Gather context
        context = agent.gather_context(lookback_hours=lookback_hours)
        thought.context_data = context
        thought.context_summary = f"Analyzed {context.get('lookback_hours', 24)}h of activity: " \
                                  f"{context.get('learning_stats', {}).get('transfers_24h', 0)} knowledge transfers, " \
                                  f"{context.get('conversation_stats', {}).get('count_24h', 0)} conversations, " \
                                  f"{context.get('dream_stats', {}).get('count_24h', 0)} dreams"
        thought.save()

        logger.info(f"🧠 [THINKING] Cycle #{cycle_number} - Thinking...")
        thought.execution_status = 'thinking'
        thought.save()

        # Run the thinking process
        thinking_result = agent.execute(lookback_hours=lookback_hours)

        # Session 782: Fix - AgentResult is a dataclass, not a dict
        # Access attributes directly instead of using .get()
        if not thinking_result.success:
            thought.execution_status = 'failed'
            thought.reflection = f"Thinking failed: {thinking_result.error or 'Unknown error'}"
            thought.save()
            return {'success': False, 'error': thinking_result.error}

        # Extract thinking results from data dict
        result = thinking_result.data.get('thinking_result', {})

        thought.reflection = result.get('reflection', '')
        thought.insights = result.get('insights', [])
        thought.patterns = result.get('patterns', [])
        thought.opportunities = result.get('opportunities', [])
        thought.concerns = result.get('concerns', [])
        thought.decisions = result.get('decisions', [])
        thought.actions_planned = result.get('decisions', [])
        # Session 957: Handle "not available" or other non-numeric priority_score values
        # The LLM prompt instructs to say "not available" for missing metrics, but the model
        # field is a FloatField, so we need to safely convert or default to 0.0
        priority_val = result.get('priority_score', 0.0)
        try:
            thought.priority_score = float(priority_val) if priority_val not in ['not available', 'N/A', None, ''] else 0.0
        except (ValueError, TypeError):
            thought.priority_score = 0.0
        thought.execution_status = 'deciding'
        thought.save()

        logger.info(f"🧠 [THINKING] Cycle #{cycle_number} - Generated {len(thought.insights)} insights, "
                   f"{len(thought.decisions)} decisions")

        # Session 547: Initialize concern tracker for feedback loop
        from core.services.concern_tracker import get_concern_tracker
        tracker = get_concern_tracker()

        # Auto-register concerns for tracking
        concerns_registered = {'total_concerns': 0, 'new_concerns': 0}
        if thought.concerns:
            try:
                registered = tracker.register_concerns_from_cycle(thought)
                concerns_registered = {
                    'total_concerns': len(registered),
                    'new_concerns': sum(1 for r in registered if r.get('is_new')),
                    'recurring': sum(1 for r in registered if not r.get('is_new'))
                }
                logger.info(f"🔍 [CONCERNS] Registered {concerns_registered['total_concerns']} concerns "
                           f"({concerns_registered['new_concerns']} new)")
            except Exception as e:
                logger.warning(f"Error registering concerns: {e}")

        # Execute actions if priority is high enough
        actions_executed = []
        if thought.priority_score >= config.min_priority_to_act and thought.decisions:
            logger.info(f"🧠 [THINKING] Cycle #{cycle_number} - Executing actions...")
            thought.execution_status = 'executing'
            thought.save()

            # Filter to allowed actions
            allowed_decisions = [
                d for d in thought.decisions
                if d.get('action_type') in config.allowed_actions
            ]

            # Execute up to max_actions
            executor = AutonomousActionExecutor()
            execution_results = executor.execute_actions(
                allowed_decisions,
                max_actions=config.max_actions_per_cycle
            )

            # Create AutonomousAction records
            for i, (decision, exec_result) in enumerate(zip(allowed_decisions, execution_results)):
                action = AutonomousAction.objects.create(
                    thought_record=thought,
                    action_type=decision.get('action_type', 'unknown'),
                    action_name=decision.get('action_name', f'Action {i+1}'),
                    action_params=decision.get('params', {}),
                    reasoning=decision.get('reasoning', ''),
                    expected_outcome=decision.get('expected_outcome', ''),
                    priority=decision.get('priority', 'medium'),
                    status='completed' if exec_result.get('success') else 'failed',
                    result=exec_result.get('result', {}),
                    result_summary=format_action_result(exec_result.get('result', {})),
                    error_message=exec_result.get('error', '') if not exec_result.get('success') else '',
                    started_at=timezone.now(),
                    completed_at=timezone.now()
                )
                actions_executed.append({
                    'action_id': str(action.id),
                    'type': action.action_type,
                    'name': action.action_name,
                    'success': exec_result.get('success', False)
                })

                # Session 547: Link action to relevant concerns
                try:
                    linked = tracker.link_action_to_concerns(action, thought)
                    if linked:
                        logger.info(f"🔗 [CONCERNS] Action '{action.action_type}' linked to {len(linked)} concern(s)")
                except Exception as e:
                    logger.warning(f"Error linking action to concerns: {e}")

            thought.actions_executed = actions_executed
        else:
            logger.info(f"🧠 [THINKING] Cycle #{cycle_number} - Priority {thought.priority_score} below threshold "
                       f"{config.min_priority_to_act}, no actions taken")

        # Finalize
        end_time = time.time()
        thought.thinking_duration_seconds = end_time - start_time
        thought.execution_status = 'completed'
        thought.completed_at = timezone.now()
        thought.save()

        logger.info(f"🧠 [THINKING] Cycle #{cycle_number} COMPLETE in {thought.thinking_duration_seconds:.1f}s - "
                   f"{len(thought.insights)} insights, {len(actions_executed)} actions executed")

        # Session 547: Verify concerns after actions are taken
        verification_result = {'total_checked': 0, 'resolved': 0}
        if actions_executed:
            try:
                verification_result = tracker.verify_all_active_concerns()
                if verification_result.get('resolved', 0) > 0:
                    logger.info(f"✅ [CONCERNS] Verified: {verification_result['resolved']} concerns resolved!")
            except Exception as e:
                logger.warning(f"Error verifying concerns: {e}")

        # Session 647: Send Discord summary notification when actions are executed
        if actions_executed:
            try:
                from core.services.discord_notifications import DiscordNotificationService
                discord = DiscordNotificationService()

                # Build action summary
                successful = sum(1 for a in actions_executed if a.get('success'))
                failed = len(actions_executed) - successful
                action_types = [a.get('type', 'unknown') for a in actions_executed[:5]]

                message = f"""**🧠 Thinking Cycle #{cycle_number} Complete**

**Duration:** {thought.thinking_duration_seconds:.1f}s
**Insights:** {len(thought.insights)} | **Patterns:** {len(thought.patterns)}
**Decisions Made:** {len(thought.decisions)}

**Actions Executed:** {len(actions_executed)} ({successful} ✅, {failed} ❌)
{chr(10).join(f'• {t}' for t in action_types)}

**Concerns:** {concerns_registered} registered, {verification_result.get('resolved', 0)} resolved
"""
                discord.send_to_channel('system-status', message)
            except Exception as e:
                logger.debug(f"Discord notification failed: {e}")

        return {
            'success': True,
            'cycle_number': cycle_number,
            'thought_id': str(thought.id),
            'insights_count': len(thought.insights),
            'patterns_count': len(thought.patterns),
            'decisions_count': len(thought.decisions),
            'actions_executed': len(actions_executed),
            'priority_score': thought.priority_score,
            'duration_seconds': thought.thinking_duration_seconds,
            'concerns_registered': concerns_registered,
            'concerns_verified': verification_result
        }

    except SoftTimeLimitExceeded:
        logger.error("[THINKING] run_autonomous_thinking_cycle timed out (soft_time_limit=1800s)")
        try:
            if 'thought' in locals() and thought:
                thought.execution_status = 'failed'
                thought.reflection = "Celery soft_time_limit exceeded"
                thought.completed_at = timezone.now()
                thought.save()
        except Exception:
            pass
        return {'success': False, 'error': 'Celery soft_time_limit exceeded', 'timed_out': True}
    except Exception as e:
        logger.error(f"🧠 [THINKING] Cycle failed: {e}", exc_info=True)
        # Session 782: Mark thought as failed if it was created
        try:
            if 'thought' in locals() and thought:
                thought.execution_status = 'failed'
                thought.reflection = f"Error during thinking cycle: {str(e)}"
                thought.completed_at = timezone.now()
                thought.save()
                logger.info(f"🧠 [THINKING] Cycle #{thought.cycle_number} marked as FAILED")
        except Exception as cleanup_error:
            logger.warning(f"Error cleaning up thought record: {cleanup_error}")
        return {
            'success': False,
            'error': str(e)
        }



@shared_task
def scan_concerns_for_human_action():
    """
    Session 549/550: Periodic task to scan for concerns requiring human action.

    Scans active concerns that cannot be auto-verified and creates
    action-required notifications for them. Also cleans up stale notifications
    for concerns that have been resolved.

    Returns:
        Summary of notifications created and cleaned
    """
    from core.services.human_action_service import get_human_action_service
    from core.models_unified_system import ProactiveNotification, TrackedConcern
    from django.utils import timezone

    logger.info("🔔 [HUMAN ACTION] Scanning for concerns requiring human action...")

    try:
        # Session 550: First, clean up stale notifications for resolved concerns
        stale_dismissed = 0
        pending_notifications = ProactiveNotification.objects.filter(
            notification_type='action_required',
            is_dismissed=False
        )

        for n in pending_notifications:
            concern_id = n.rich_content.get('concern_id') if n.rich_content else None
            if concern_id:
                try:
                    concern = TrackedConcern.objects.get(id=concern_id)
                    if concern.status == 'resolved':
                        n.is_dismissed = True
                        n.dismissed_at = timezone.now()
                        n.save()
                        stale_dismissed += 1
                except TrackedConcern.DoesNotExist:
                    n.is_dismissed = True
                    n.dismissed_at = timezone.now()
                    n.save()
                    stale_dismissed += 1

        if stale_dismissed > 0:
            logger.info(f"🔔 [HUMAN ACTION] Dismissed {stale_dismissed} stale notifications")

        # Now create new notifications for active concerns
        service = get_human_action_service()
        result = service.create_notifications_for_active_concerns()

        if result['notifications_created'] > 0:
            logger.info(f"🔔 [HUMAN ACTION] Created {result['notifications_created']} action notifications")

            # Optionally notify via Discord for urgent concerns
            try:
                from core.services.discord_notifications import get_discord_service
                discord = get_discord_service()

                for concern in result.get('concerns', []):
                    if concern.get('severity') in ['critical', 'high']:
                        discord.send_notification(
                            channel='system-status',
                            title='⚠️ Human Action Required',
                            message=f"**{concern['severity'].upper()}**: {concern['text'][:100]}...\n\n"
                                   f"[Review in AI Studio](http://localhost:8000/ai-studio/#research-concerns)",
                            color='#dc2626'  # Red
                        )
            except Exception as e:
                logger.warning(f"Discord notification failed: {e}")
        else:
            logger.info(f"🔔 [HUMAN ACTION] No new action notifications needed "
                       f"({result['already_notified']} already exist)")

        return {
            'success': True,
            'notifications_created': result['notifications_created'],
            'already_notified': result['already_notified'],
            'stale_dismissed': stale_dismissed,
            'total_concerns': result['total_concerns']
        }

    except Exception as e:
        logger.error(f"🔔 [HUMAN ACTION] Scan failed: {e}", exc_info=True)
        return {
            'success': False,
            'error': str(e)
        }


