# Session 705: IMMUNE SYSTEM - Security & Threat Detection
# =============================================================================

@shared_task(name='core.tasks.immune_scan')
def immune_scan():
    """
    Session 705: IMMUNE SYSTEM - Run security scan for threats

    The IMMUNE SYSTEM is the defense layer of the AI body - detecting and
    responding to threats, suspicious patterns, and malicious activity.

    Monitors:
    - Rate limit abuse and burst patterns
    - Authentication attacks (brute force, credential stuffing)
    - Injection attempts (SQL, XSS, path traversal)
    - Scraping and bot activity
    - Behavioral anomalies

    Human body metaphor:
    - Pathogens = Malicious requests, suspicious patterns
    - Antibodies = Detection rules and patterns
    - White Blood Cells = Active monitoring and response
    - Fever = Elevated alert state
    - Quarantine = Blocked/restricted entities

    Schedule: Every 45 seconds (via Celery Beat)
    """
    from core.services.immune import get_immune_system
    import redis
    import json

    logger.info("🛡️ [IMMUNE] Running security scan...")

    try:
        immune = get_immune_system()
        status = immune.scan()

        # Log the result
        logger.info(
            f"🛡️ [IMMUNE] Scan complete: {status['overall_status'].upper()} "
            f"(Health: {status['health_score']:.1f}%) - "
            f"Threat Level: {status.get('threat_level', 'none').upper()}"
        )

        # Log threat counts
        if status.get('threats_detected_24h', 0) > 0:
            logger.info(
                f"🛡️ [IMMUNE] 24h threats: {status['threats_detected_24h']} detected, "
                f"{status.get('threats_blocked_24h', 0)} blocked"
            )

        # Log quarantine status
        if status.get('total_quarantined', 0) > 0:
            logger.info(
                f"🛡️ [IMMUNE] Quarantine: {status['total_quarantined']} entities "
                f"({status.get('quarantined_ips', 0)} IPs, "
                f"{status.get('quarantined_users', 0)} users)"
            )

        # Alert on critical status
        if status['overall_status'] in ('overwhelmed', 'compromised'):
            logger.error(
                f"🛡️ [IMMUNE] CRITICAL: System status is {status['overall_status'].upper()}! "
                f"Active threats: {status.get('active_threats', 0)}"
            )

        # Publish to Redis for WebSocket consumers
        try:
            r = redis.Redis.from_url(os.environ.get('REDIS_URL', 'redis://localhost:6379'), decode_responses=True)
            r.publish('immune:status', json.dumps({
                'health_score': status['health_score'],
                'overall_status': status['overall_status'],
                'is_healthy': status.get('is_healthy', True),
                'threat_level': status.get('threat_level', 'none'),
                'active_threats': status.get('active_threats', 0),
                'threats_detected_24h': status.get('threats_detected_24h', 0),
                'total_quarantined': status.get('total_quarantined', 0),
                'timestamp': status['timestamp'],
            }))
            logger.debug("🛡️ [IMMUNE] Status published to Redis")
        except Exception as redis_error:
            logger.warning(f"🛡️ [IMMUNE] Redis publish failed: {redis_error}")

        return status

    except Exception as e:
        logger.error(f"🛡️ [IMMUNE] Security scan failed: {e}")
        return {
            'status': 'compromised',
            'error': str(e),
            'is_healthy': False,
        }


# =============================================================================
# Session 706: DIGESTIVE SYSTEM - Data Ingestion & Processing
# =============================================================================

@shared_task(name='core.tasks.check_digestion')
def check_digestion():
    """
    Session 706: DIGESTIVE SYSTEM - Check data ingestion health

    The DIGESTIVE SYSTEM monitors how raw spider data is transformed into
    actionable intelligence through the 4-stage pipeline.

    Monitors:
    - INTAKE: Spider data collection (SpiderData, SpiderExecutionLog)
    - PROCESSING: Normalization, deduplication
    - ENRICHMENT: Embedding generation, relevance scoring
    - ROUTING: Data delivery to agents and services

    Human body metaphor:
    - Food = Raw spider data (RSS, API responses, scraped content)
    - Mouth/Intake = Spider execution -> SpiderData creation
    - Stomach = Processing queue
    - Enzymes = Transformation functions (embedding, scoring)
    - Intestines = Routing pipeline
    - Nutrients = Actionable intelligence
    - Metabolism Rate = Processing throughput

    Schedule: Every 60 seconds (via Celery Beat)
    """
    from core.services.digestive import get_digestive_system
    import redis
    import json

    logger.info("🍽️ [DIGESTIVE] Running digestion check...")

    try:
        digestive = get_digestive_system()
        status = digestive.digest()

        # Log the result
        logger.info(
            f"🍽️ [DIGESTIVE] Check complete: {status['overall_status'].upper()} "
            f"(Score: {status['digestion_score']:.1f}%)"
        )

        # Log stage statuses
        stages = status.get('stages', {})
        for stage_name, stage_data in stages.items():
            stage_status = stage_data.get('status', 'unknown')
            if stage_status not in ('healthy',):
                logger.warning(
                    f"🍽️ [DIGESTIVE] Stage {stage_name}: {stage_status.upper()}"
                )

        # Log bottlenecks
        bottlenecks = status.get('bottlenecks', [])
        if bottlenecks:
            for bn in bottlenecks:
                severity = bn.get('severity', 'info')
                if severity == 'critical':
                    logger.error(
                        f"🍽️ [DIGESTIVE] BOTTLENECK ({bn['stage']}): {bn['issue']}"
                    )
                elif severity == 'warning':
                    logger.warning(
                        f"🍽️ [DIGESTIVE] Bottleneck ({bn['stage']}): {bn['issue']}"
                    )

        # Log metabolism
        metabolism = status.get('metabolism', {})
        logger.info(
            f"🍽️ [DIGESTIVE] Metabolism: "
            f"intake={metabolism.get('intake_rate', 0):.2f}/min, "
            f"processing={metabolism.get('processing_rate', 0):.2f}/min, "
            f"output={metabolism.get('output_rate', 0):.2f}/min"
        )

        # Alert on critical status
        if status['overall_status'] in ('blocked', 'starving'):
            logger.error(
                f"🍽️ [DIGESTIVE] CRITICAL: System status is {status['overall_status'].upper()}!"
            )

        # Publish to Redis for WebSocket consumers
        try:
            r = redis.Redis.from_url(os.environ.get('REDIS_URL', 'redis://localhost:6379'), decode_responses=True)
            r.publish('digestive:status', json.dumps({
                'digestion_score': status['digestion_score'],
                'overall_status': status['overall_status'],
                'is_digesting': status.get('is_digesting', True),
                'stages': {
                    stage: data.get('status', 'unknown')
                    for stage, data in stages.items()
                },
                'metabolism': metabolism,
                'bottlenecks_count': len(bottlenecks),
                'timestamp': status['timestamp'],
            }))
            logger.debug("🍽️ [DIGESTIVE] Status published to Redis")
        except Exception as redis_error:
            logger.warning(f"🍽️ [DIGESTIVE] Redis publish failed: {redis_error}")

        return status

    except Exception as e:
        logger.error(f"🍽️ [DIGESTIVE] Digestion check failed: {e}")
        return {
            'status': 'blocked',
            'error': str(e),
            'is_digesting': False,
        }


