def _preflight_check_agent_data(agent_name: str, topic: str = '') -> dict:
    """
    Session 987: Check if the required data exists before running an agent.
    Returns {'proceed': True/False, 'reason': str, 'counts': dict}.
    """
    import importlib

    # Direct match or topic references an agent with requirements
    reqs = AGENT_DATA_REQUIREMENTS.get(agent_name)
    if not reqs and topic:
        for req_agent, req_data in AGENT_DATA_REQUIREMENTS.items():
            if req_agent in topic:
                reqs = req_data
                agent_name = req_agent  # for logging
                break

    if not reqs:
        return {'proceed': True, 'reason': 'no requirements defined'}

    counts = {}
    missing = []
    for model_path, filters, min_count, label in reqs['models']:
        try:
            module_path, class_name = model_path.rsplit('.', 1)
            module = importlib.import_module(module_path)
            Model = getattr(module, class_name)
            count = Model.objects.filter(**filters).count()
            counts[label] = count
            if count < min_count:
                missing.append(f"{label}: {count}/{min_count}")
        except Exception as e:
            logger.warning(f"[Session 987] Preflight model check failed for {model_path}: {e}")
            # Don't block on import errors — let the agent try
            counts[label] = -1

    if missing:
        reason = f"Insufficient data for {reqs['description']}: {', '.join(missing)}"
        return {'proceed': False, 'reason': reason, 'counts': counts}

    return {'proceed': True, 'reason': 'all data requirements met', 'counts': counts}


@shared_task(name='core.tasks.universal_agent_workspace_output', soft_time_limit=2700, time_limit=3000)
def universal_agent_workspace_output(
    agent_name: str,
    topic: str = None,
    initiative_id: str = None,
    trigger_source: str = None,
    force_production: bool = False
):
    """
    Session 777: Universal task to execute any agent and write output to workspace.
    Session 864: Added run_mode detection and intent-based quality gates.

    This task can run any registered agent and write its output to the SKIN Layer.
    Now distinguishes between PRODUCTION (purposeful) and WARMUP (exercise) runs.

    Args:
        agent_name: Name of the agent to execute
        topic: Optional topic override (if None, may trigger warmup mode)
        initiative_id: Optional initiative this is associated with
        trigger_source: What triggered this run (initiative, user, schedule, warmup)
        force_production: Force production mode even without topic

    Returns:
        Operation result with run_mode metadata
    """
    from django.contrib.auth import get_user_model
    from core.models_skin_layer import ProjectWorkspace, WorkspaceOperation
    from core.services.workspace_manager import WorkspaceManager
    from datetime import datetime
    import importlib

    # ==========================================================================
    # SESSION 864 PHASE 0: DETERMINE RUN MODE
    # ==========================================================================
    # If no topic provided and not forced, this is a warmup run
    is_warmup = (topic is None) and (not force_production) and (not initiative_id)

    if is_warmup:
        run_mode = 'warmup'
        trigger = trigger_source or 'warmup'
    else:
        run_mode = 'production'
        trigger = trigger_source or ('initiative' if initiative_id else 'schedule')

    logger.info(
        f"🤖 [SKIN LAYER] Agent execution: {agent_name} "
        f"(run_mode={run_mode}, trigger={trigger})"
    )

    # ==========================================================================
    # SESSION 864 PHASE 2: CHECK FOR REAL TASK (Initiative Queue)
    # If this is a scheduled run without topic, try to get a real task first
    # ==========================================================================
    real_task = None
    if topic is None and not is_warmup:
        real_task = _get_next_task_for_agent(agent_name)
        if real_task:
            topic = real_task.get('topic')
            initiative_id = real_task.get('initiative_id')
            trigger = 'initiative'
            run_mode = 'production'
            logger.info(f"🤖 [SKIN LAYER] Found real task for {agent_name}: {topic[:50]}...")

    # ==========================================================================
    # SESSION 864 PHASE 1: WARMUP MODE - Just verify agent works, no content
    # ==========================================================================
    if is_warmup and not real_task:
        logger.info(f"🔄 [WARMUP] {agent_name} - Infra check only, no content generation")
        return _run_agent_warmup(agent_name)

    # Get agent config
    config = AGENT_WORKSPACE_REGISTRY.get(agent_name)
    if not config:
        logger.warning(f"Agent {agent_name} not in registry, using defaults")
        config = {
            'category': 'uncategorized',
            'output_dir': f'agents/{agent_name.lower()}',
            'output_type': 'output',
            'task_template': 'Generate output for {topic}',
            'default_topic': 'general task',
        }

    try:
        # Session 885: Use helper to find workspace (handles codebase workspace)
        user, workspace = _get_workspace_for_skin_layer()
        if not workspace:
            return {'success': False, 'error': 'No active workspace found (run setup_codebase_workspace)', 'run_mode': run_mode}

        # Determine topic - use provided or fall back to default
        actual_topic = topic or config['default_topic']
        task_description = config['task_template'].format(topic=actual_topic)

        # Dynamically import and instantiate agent
        agent_class = _get_agent_class(agent_name)

        if not agent_class:
            return {
                'success': False,
                'error': f'Could not find agent class: {agent_name}',
                'run_mode': run_mode
            }

        # Session 987: Pre-flight data check — skip if required data doesn't exist
        if run_mode == 'production' and trigger == 'schedule':
            preflight = _preflight_check_agent_data(agent_name, actual_topic)
            if not preflight['proceed']:
                logger.warning(
                    f"[Session 987] Pre-flight SKIP: {agent_name} — {preflight['reason']}"
                )
                return {
                    'success': False,
                    'agent': agent_name,
                    'error': f"Pre-flight check: {preflight['reason']}",
                    'run_mode': run_mode,
                    'preflight_skip': True,
                    'preflight_counts': preflight.get('counts', {}),
                }

        # Execute agent
        agent = agent_class()
        result = agent.execute(
            task=task_description,
            context={
                'topic': actual_topic,
                'output_format': 'markdown',
                'initiative_id': initiative_id,
                'run_mode': run_mode,
                'trigger_source': trigger,
            },
            scifi_context={},
            spider_context={}
        )

        # Session 813: Improved output extraction from AgentResult
        output_content = _extract_agent_output_content(result, task_description)

        # ==========================================================================
        # SESSION 864 PHASE 3: QUALITY GATE - Only write meaningful content
        # ==========================================================================
        # For production runs, always write
        # For warmup runs that slipped through, quarantine to .warmups/
        timestamp = datetime.now().strftime("%Y-%m-%d_%H-%M")
        safe_topic = actual_topic[:30].replace(' ', '_').replace('/', '-').replace(':', '')

        if run_mode == 'production':
            filename = f"{config['output_dir']}/{config['output_type']}_{safe_topic}_{timestamp}.md"
        else:
            # Quarantine warmup output to .warmups/ directory
            filename = f".warmups/{agent_name}/{config['output_type']}_{safe_topic}_{timestamp}.md"

        content = f"""# {agent_name}: {actual_topic}
Type: {config['output_type'].replace('_', ' ').title()}
Category: {config['category'].title()}
Generated: {datetime.now().strftime("%Y-%m-%d %H:%M:%S")}
Run Mode: {run_mode.upper()}
Trigger: {trigger}
{f'Initiative: {initiative_id}' if initiative_id else ''}

---

{output_content}

---
*Generated via SKIN Layer - Universal Agent Workspace Integration*
"""

        # Write to workspace with run_mode metadata
        manager = WorkspaceManager(user)
        operation = manager.write_file(
            workspace=workspace,
            file_path=filename,
            content=content,
            agent_name=agent_name,
            agent_task=task_description
        )

        # Session 864: Update operation with run_mode metadata
        if operation and operation.id:
            WorkspaceOperation.objects.filter(pk=operation.id).update(
                run_mode=run_mode,
                trigger_source=trigger,
                initiative_id=initiative_id,
                is_warmup=(run_mode == 'warmup')
            )

        logger.info(
            f"🤖 [SKIN LAYER] {agent_name} output written: {filename} "
            f"(success: {operation.success}, run_mode: {run_mode})"
        )

        return {
            'success': operation.success,
            'agent': agent_name,
            'category': config['category'],
            'file': filename,
            'topic': actual_topic,
            'operation_id': str(operation.id),
            'run_mode': run_mode,
            'trigger_source': trigger,
            'initiative_id': initiative_id,
        }

    except SoftTimeLimitExceeded:
        logger.error(f"🤖 [SKIN LAYER] {agent_name} KILLED by soft_time_limit (45 min)")
        # Mark any in-progress execution records for this agent as failed
        try:
            from core.models_unified_system import AgentExecution
            from django.utils import timezone as tz
            stuck = AgentExecution.objects.filter(
                agent__name=agent_name,
                status__in=['running', 'in_progress'],
            ).update(
                status='failed',
                error_message=f'Celery soft_time_limit exceeded (60 min)',
                completed_at=tz.now(),
            )
            if stuck:
                logger.info(f"🤖 [SKIN LAYER] Marked {stuck} execution(s) as failed for {agent_name}")
        except Exception:
            pass
        return {'success': False, 'agent': agent_name, 'error': 'Celery soft_time_limit exceeded (60 min)', 'run_mode': run_mode}

    except Exception as e:
        logger.error(f"🤖 [SKIN LAYER] {agent_name} execution failed: {e}", exc_info=True)
        return {'success': False, 'agent': agent_name, 'error': str(e), 'run_mode': run_mode}


def _get_agent_class(agent_name: str):
    """Get agent class by name, trying multiple module patterns."""
    import importlib
    import re

    # Try common module patterns
    module_patterns = [
        f"core.agents.{agent_name.lower().replace('agent', '_agent')}",
        f"core.agents.{agent_name.lower()}",
        f"core.agents.{agent_name[0].lower() + agent_name[1:]}",
    ]

    # Convert CamelCase to snake_case for module name
    snake_name = re.sub('(.)([A-Z][a-z]+)', r'\1_\2', agent_name)
    snake_name = re.sub('([a-z0-9])([A-Z])', r'\1_\2', snake_name).lower()
    module_patterns.insert(0, f"core.agents.{snake_name}")

    for module_path in module_patterns:
        try:
            module = importlib.import_module(module_path)
            if hasattr(module, agent_name):
                return getattr(module, agent_name)
        except (ImportError, ModuleNotFoundError):
            continue

    # Try agent router as fallback
    try:
        from core.agent_router import AgentRouter
        router = AgentRouter()
        return router.get_agent_class(agent_name)
    except Exception:
        return None


def _run_agent_warmup(agent_name: str) -> dict:
    """
    Session 864: Infra warmup for an agent - verify it works without content generation.

    This replaces content-generating warmups with lightweight health checks:
    - Verify agent class can be loaded
    - Verify agent can be instantiated
    - Optionally do a minimal LLM ping (5-20 tokens)
    - NO file creation, NO default_topic content

    Returns:
        Health check result dict
    """
    import time
    start_time = time.time()

    try:
        # 1. Verify agent class exists
        agent_class = _get_agent_class(agent_name)
        if not agent_class:
            return {
                'success': False,
                'agent': agent_name,
                'run_mode': 'warmup',
                'check': 'class_load',
                'error': 'Agent class not found'
            }

        # 2. Verify agent can be instantiated
        try:
            agent = agent_class()
        except Exception as e:
            return {
                'success': False,
                'agent': agent_name,
                'run_mode': 'warmup',
                'check': 'instantiation',
                'error': str(e)
            }

        # 3. Check if agent has required methods
        has_execute = hasattr(agent, 'execute')
        has_tools = hasattr(agent, 'tools')

        execution_time_ms = int((time.time() - start_time) * 1000)

        logger.info(
            f"✅ [WARMUP] {agent_name} healthy: "
            f"class=✓, instance=✓, execute={has_execute}, tools={has_tools} "
            f"({execution_time_ms}ms)"
        )

        return {
            'success': True,
            'agent': agent_name,
            'run_mode': 'warmup',
            'checks': {
                'class_load': True,
                'instantiation': True,
                'has_execute': has_execute,
                'has_tools': has_tools,
            },
            'execution_time_ms': execution_time_ms,
            'file_created': False,  # Key: no file output
        }

    except Exception as e:
        logger.warning(f"❌ [WARMUP] {agent_name} failed: {e}")
        return {
            'success': False,
            'agent': agent_name,
            'run_mode': 'warmup',
            'error': str(e)
        }


def _get_next_task_for_agent(agent_name: str) -> dict | None:
    """
    Session 864: Get next real task from the initiative queue for an agent.
    Session 1033: Fixed broken field references (assigned_agent, description, title).

    Checks for:
    1. Initiative stages that need documents (PENDING status, no document)
    2. PublishGate backlog (needs enhancement blogs)

    Returns:
        Task dict with topic, initiative_id, etc. or None if no real work.
    """
    try:
        from core.models_document_registry import InitiativeStage

        # Check for initiative stages needing documents
        # Session 1033: InitiativeStage has no assigned_agent field.
        # Instead, find any PENDING stage without a document.
        pending_stage = InitiativeStage.objects.filter(
            status='PENDING',
            document__isnull=True,
        ).select_related('initiative').first()

        if pending_stage:
            return {
                'topic': pending_stage.initiative.name,
                'initiative_id': str(pending_stage.initiative.id),
                'stage_id': str(pending_stage.id),
                'stage_num': pending_stage.stage,
                'source': 'initiative_stage',
            }

        # Check PublishGate backlog — needs_enhancement blogs
        from core.models_unified_system import SelfBlog
        backlog = SelfBlog.objects.filter(
            status='needs_enhancement'
        ).order_by('created_at').first()

        if backlog:
            return {
                'topic': f"Enhance blog: {backlog.title[:80]}",
                'blog_id': str(backlog.id),
                'source': 'publish_gate_backlog',
            }

        return None

    except Exception as e:
        logger.warning(f"Error getting next task for {agent_name}: {e}")
        return None


@shared_task(name='core.tasks.agent_category_rotation')
def agent_category_rotation(category: str):
    """
    Session 777: Execute all agents in a category and write outputs to workspace.

    This task runs all agents in a given category sequentially.

    Args:
        category: The agent category to execute (research, financial, etc.)

    Returns:
        Summary of all agent executions
    """
    logger.info(f"🔄 [SKIN LAYER] Starting category rotation: {category}")

    agents_in_category = [
        name for name, config in AGENT_WORKSPACE_REGISTRY.items()
        if config['category'] == category
    ]

    if not agents_in_category:
        return {'success': False, 'error': f'No agents found in category: {category}'}

    results = []
    for agent_name in agents_in_category:
        try:
            result = universal_agent_workspace_output(agent_name)
            results.append({
                'agent': agent_name,
                'success': result.get('success', False),
                'file': result.get('file'),
                'error': result.get('error')
            })
        except Exception as e:
            results.append({
                'agent': agent_name,
                'success': False,
                'error': str(e)
            })

    successful = sum(1 for r in results if r['success'])
    logger.info(
        f"🔄 [SKIN LAYER] Category {category} complete: "
        f"{successful}/{len(results)} agents succeeded"
    )

    return {
        'success': successful > 0,
        'category': category,
        'total_agents': len(results),
        'successful': successful,
        'failed': len(results) - successful,
        'results': results
    }


@shared_task(name='core.tasks.full_agent_rotation')
def full_agent_rotation():
    """
    Session 777: Execute ALL agents in the registry and write outputs to workspace.

    This is the master task that ensures every agent produces workspace output.
    Should be run periodically (e.g., weekly) to ensure all agents are active.

    Returns:
        Summary of all agent executions by category
    """
    logger.info("🌟 [SKIN LAYER] Starting FULL agent rotation - all 74 agents")

    category_results = {}

    for category in AGENT_CATEGORIES:
        try:
            result = agent_category_rotation(category)
            category_results[category] = {
                'success': result.get('success', False),
                'total': result.get('total_agents', 0),
                'successful': result.get('successful', 0),
                'failed': result.get('failed', 0)
            }
        except Exception as e:
            category_results[category] = {
                'success': False,
                'error': str(e)
            }

    total_agents = sum(r.get('total', 0) for r in category_results.values())
    total_successful = sum(r.get('successful', 0) for r in category_results.values())

    logger.info(
        f"🌟 [SKIN LAYER] Full rotation complete: "
        f"{total_successful}/{total_agents} agents succeeded"
    )

    return {
        'success': total_successful > 0,
        'total_agents': total_agents,
        'successful': total_successful,
        'failed': total_agents - total_successful,
        'categories': category_results
    }


# =============================================================================
# SESSION 784: VOICE CRITIQUE SYSTEM
# =============================================================================

@shared_task(name='content_studio.score_episode_voice')
def score_episode_voice(episode_id: str) -> dict:
    """
    Session 784: Score an episode's voice quality using VoiceCriticAgent.

    This is a post-generation step that scores content WITHOUT editing it.
    Scores are stored as metadata for learning - the system learns taste over time.

    Args:
        episode_id: UUID of the ChannelEpisode to score

    Returns:
        dict: Voice scores (distinctiveness, specificity, opinion_strength, generic_flag)
    """
    from core.models_autonomous_studio import ChannelEpisode
    from core.agents.content.voice_critic_agent import get_voice_critic_agent

    logger.info(f"🎭 [VOICE CRITIC] Scoring episode: {episode_id}")

    try:
        episode = ChannelEpisode.objects.get(id=episode_id)

        # Skip if already scored
        if episode.voice_critique_completed:
            logger.info(f"🎭 [VOICE CRITIC] Episode {episode_id} already scored, skipping")
            return {
                'success': True,
                'already_scored': True,
                'episode_id': episode_id
            }

        # Get content to score
        content = episode.script or episode.description
        if not content:
            logger.warning(f"🎭 [VOICE CRITIC] Episode {episode_id} has no content to score")
            return {
                'success': False,
                'error': 'No content to score',
                'episode_id': episode_id
            }

        # Score with VoiceCriticAgent
        agent = get_voice_critic_agent()
        result = agent.execute(
            task=f"Score voice quality for: {episode.title}",
            context={
                'content': content,
                'title': episode.title,
                'content_type': 'blog_post',
            },
            scifi_context={},
            spider_context={}
        )

        if result.success:
            scores = result.data.get('voice_scores', {})

            # Update episode with scores
            episode.distinctiveness_score = scores.get('distinctiveness_score', 0)
            episode.specificity_score = scores.get('specificity_score', 0)
            episode.opinion_strength_score = scores.get('opinion_strength_score', 0)
            episode.generic_flag = scores.get('generic_flag', False)
            episode.intent_type = scores.get('intent_type', '')
            episode.voice_critique_completed = True
            episode.save(update_fields=[
                'distinctiveness_score', 'specificity_score',
                'opinion_strength_score', 'generic_flag',
                'intent_type', 'voice_critique_completed'
            ])

            logger.info(
                f"🎭 [VOICE CRITIC] Scored episode {episode_id}: "
                f"D={scores.get('distinctiveness_score')}, "
                f"S={scores.get('specificity_score')}, "
                f"O={scores.get('opinion_strength_score')}, "
                f"Generic={scores.get('generic_flag')}, "
                f"Intent={scores.get('intent_type')}"
            )

            return {
                'success': True,
                'episode_id': episode_id,
                'title': episode.title,
                'scores': scores
            }
        else:
            logger.error(f"🎭 [VOICE CRITIC] Failed to score episode {episode_id}: {result.error}")
            return {
                'success': False,
                'episode_id': episode_id,
                'error': result.error
            }

    except ChannelEpisode.DoesNotExist:
        logger.error(f"🎭 [VOICE CRITIC] Episode {episode_id} not found")
        return {
            'success': False,
            'episode_id': episode_id,
            'error': 'Episode not found'
        }
    except Exception as e:
        logger.error(f"🎭 [VOICE CRITIC] Error scoring episode {episode_id}: {e}")
        return {
            'success': False,
            'episode_id': episode_id,
            'error': str(e)
        }


@shared_task(name='content_studio.backfill_voice_scores')
def backfill_voice_scores(limit: int = 50, min_content_length: int = 100) -> dict:
    """
    Session 784: Backfill voice scores for existing episodes that haven't been scored.

    Processes episodes in batches to avoid overwhelming the system.

    Args:
        limit: Maximum number of episodes to process in this batch
        min_content_length: Minimum script length to consider for scoring

    Returns:
        dict: Summary of backfill results
    """
    from core.models_autonomous_studio import ChannelEpisode
    from django.db.models import Q
    from django.db.models.functions import Length

    logger.info(f"🎭 [VOICE CRITIC BACKFILL] Starting backfill of up to {limit} episodes")

    # Find unscored episodes with content
    unscored_episodes = ChannelEpisode.objects.filter(
        voice_critique_completed=False
    ).exclude(
        Q(script__isnull=True) | Q(script='')
    ).annotate(
        script_length=Length('script')
    ).filter(
        script_length__gte=min_content_length
    ).order_by('-created_at')[:limit]

    total = len(unscored_episodes)
    logger.info(f"🎭 [VOICE CRITIC BACKFILL] Found {total} unscored episodes to process")

    results = {
        'total': total,
        'scored': 0,
        'failed': 0,
        'errors': []
    }

    for episode in unscored_episodes:
        try:
            # Call the scoring task synchronously for backfill
            score_result = score_episode_voice(str(episode.id))
            if score_result.get('success'):
                results['scored'] += 1
            else:
                results['failed'] += 1
                results['errors'].append({
                    'episode_id': str(episode.id),
                    'error': score_result.get('error')
                })
        except Exception as e:
            results['failed'] += 1
            results['errors'].append({
                'episode_id': str(episode.id),
                'error': str(e)
            })

    logger.info(
        f"🎭 [VOICE CRITIC BACKFILL] Complete: "
        f"{results['scored']}/{total} scored, {results['failed']} failed"
    )

    return results


# =============================================================================
# Session 785: Workspace Autopilot Conductor Task
# =============================================================================

@shared_task(name='workspace.autopilot_tick')
def workspace_autopilot_tick(
    budget_per_tick: int = 5,
    min_priority: int = None,
    category: str = None,
    dry_run: bool = False
) -> dict:
    """
    Session 785: Hybrid Workspace Autopilot Conductor

    This is the single conductor task that drains the WorkspaceTrigger queue.
    Instead of 14+ individual scheduled tasks, this one task:

    1. Gets pending workspace triggers (respecting TTL, priority)
    2. Routes each trigger to the appropriate agent
    3. Executes within budget constraints
    4. Reports results

    The event-driven triggers (from spider data) populate the queue,
    and this conductor drains it on a schedule.

    Args:
        budget_per_tick: Maximum triggers to process per tick (default: 5)
        min_priority: Minimum priority to process (None = all)
        category: Only process triggers for this category (None = all)
        dry_run: If True, log what would happen without executing

    Returns:
        dict: Summary of processing results
    """
    from core.models_skin_layer import WorkspaceTrigger, WorkspaceTriggerType
    from core.agent_router import AgentRouter
    from core.models_unified_system import AgentExecution
    from django.utils import timezone
    from django.contrib.auth import get_user_model
    import time

    User = get_user_model()

    logger.info(
        f"🤖 [WORKSPACE AUTOPILOT] Tick starting | "
        f"Budget: {budget_per_tick} | "
        f"Category: {category or 'all'} | "
        f"Min Priority: {min_priority or 'any'}"
    )

    results = {
        'triggers_processed': 0,
        'triggers_succeeded': 0,
        'triggers_failed': 0,
        'triggers_skipped': 0,
        'expired_count': 0,
        'executions': [],
        'errors': [],
        'dry_run': dry_run
    }

    try:
        # Mark expired triggers
        expired_count = WorkspaceTrigger.objects.filter(
            status='pending',
            expires_at__lt=timezone.now()
        ).update(status='expired')
        results['expired_count'] = expired_count

        if expired_count > 0:
            logger.info(f"🤖 [WORKSPACE AUTOPILOT] Expired {expired_count} stale triggers")

        # Get pending triggers
        pending_triggers = WorkspaceTrigger.get_pending_triggers(
            limit=budget_per_tick,
            category=category,
            min_priority=min_priority
        )

        total_pending = len(pending_triggers)
        logger.info(f"🤖 [WORKSPACE AUTOPILOT] Found {total_pending} pending triggers to process")

        if total_pending == 0:
            logger.info("🤖 [WORKSPACE AUTOPILOT] No triggers to process, tick complete")
            return results

        # Initialize router
        router = AgentRouter()

        # Category to agent mapping
        # Session 1029: CodeGeneratorAgent replaced — no codebase access on Railway
        CATEGORY_AGENTS = {
            'development': 'FullStackDeveloperAgent',
            'security': 'CodeReviewAgent',
            'research': 'ResearchAgent',
            'content': 'ContentWriterAgent',
            'analysis': 'TrendAnalysisAgent',
        }

        # Trigger type to agent mapping
        TYPE_AGENTS = {
            WorkspaceTriggerType.SPIDER_SECURITY_ALERT: 'CodeReviewAgent',
            WorkspaceTriggerType.SPIDER_DEPENDENCY_UPDATE: 'ResearchAgent',
            WorkspaceTriggerType.SPIDER_BUG_PATTERN: 'CodeReviewAgent',
            WorkspaceTriggerType.SPIDER_BEST_PRACTICE: 'CodeReviewAgent',
            WorkspaceTriggerType.SPIDER_CODE_INSIGHT: 'FullStackDeveloperAgent',
            WorkspaceTriggerType.AGENT_REFACTOR_SUGGESTION: 'CodeReviewAgent',
            # Session 1029: CodeGeneratorAgent replaced — no codebase access on Railway
            WorkspaceTriggerType.AGENT_TEST_NEEDED: 'FullStackDeveloperAgent',
            WorkspaceTriggerType.AGENT_DOC_NEEDED: 'TechnicalDocumentAgent',
            WorkspaceTriggerType.AGENT_OPTIMIZATION: 'CodeReviewAgent',
        }

        for trigger in pending_triggers:
            results['triggers_processed'] += 1
            trigger_start_time = time.time()

            try:
                if dry_run:
                    logger.info(
                        f"🤖 [WORKSPACE AUTOPILOT] [DRY RUN] Would process: "
                        f"{trigger.title} → {trigger.target_agent or trigger.target_category or 'auto-route'}"
                    )
                    results['triggers_skipped'] += 1
                    continue

                # Mark as queued
                trigger.status = 'queued'
                trigger.queued_at = timezone.now()
                trigger.save(update_fields=['status', 'queued_at'])

                # Determine which agent to use
                agent_name = trigger.target_agent
                if not agent_name:
                    # Try category mapping
                    if trigger.target_category and trigger.target_category in CATEGORY_AGENTS:
                        agent_name = CATEGORY_AGENTS[trigger.target_category]
                    # Try trigger type mapping
                    elif trigger.trigger_type in TYPE_AGENTS:
                        agent_name = TYPE_AGENTS[trigger.trigger_type]
                    # Default fallback
                    else:
                        agent_name = 'ResearchAgent'

                if not agent_name:
                    logger.warning(
                        f"🤖 [WORKSPACE AUTOPILOT] Could not route trigger: {trigger.title}"
                    )
                    trigger.status = 'skipped'
                    trigger.error_message = 'Could not determine agent for routing'
                    trigger.save(update_fields=['status', 'error_message'])
                    results['triggers_skipped'] += 1
                    continue

                # Mark as in progress
                trigger.status = 'in_progress'
                trigger.started_at = timezone.now()
                trigger.save(update_fields=['status', 'started_at'])

                # Execute via agent router
                logger.info(
                    f"🤖 [WORKSPACE AUTOPILOT] Executing: {trigger.title} → {agent_name}"
                )

                # Build task prompt
                context = trigger.context_data or {}
                prompt_parts = [
                    f"## Task: {trigger.title}",
                    "",
                    trigger.description or "No additional description provided.",
                    "",
                    "## Context",
                ]
                if context.get('spider_name'):
                    prompt_parts.append(f"- Source: Spider data from `{context['spider_name']}`")
                if context.get('matched_value'):
                    prompt_parts.append(f"- Matched content: {context['matched_value']}")

                prompt_parts.extend([
                    "",
                    "## Instructions",
                    "Analyze this information and take appropriate action based on the trigger type.",
                    f"Trigger type: {trigger.get_trigger_type_display()}",
                ])
                task_prompt = "\n".join(prompt_parts)

                # Execute the agent
                try:
                    agent_class = router.get_agent_class(agent_name)
                    if not agent_class:
                        raise ValueError(f'Agent class not found: {agent_name}')

                    # Session 908: Use system_autonomous for workspace operations
                    system_user = User.objects.filter(username='system_autonomous').first()
                    if not system_user:
                        system_user = User.objects.filter(username='system').first()
                    if not system_user:
                        system_user = User.objects.first()

                    agent = agent_class(user=system_user)
                    result = agent.execute(
                        task=task_prompt,
                        context={
                            'trigger_id': str(trigger.id),
                            'trigger_type': trigger.trigger_type,
                            'spider_name': context.get('spider_name'),
                            'matched_value': context.get('matched_value'),
                            'output_format': 'markdown',
                            'source': 'workspace_autopilot'
                        },
                        scifi_context={},
                        spider_context=context.get('raw_item', {})
                    )

                    # Agent's execute() creates its own AgentExecution record
                    # Extract success and summary from result
                    success = result.success if hasattr(result, 'success') else True
                    summary = ''
                    if hasattr(result, 'data') and isinstance(result.data, dict):
                        summary = str(result.data.get('summary', result.data.get('content', '')))[:500]
                    elif hasattr(result, 'data'):
                        summary = str(result.data)[:500]

                    execution_result = {
                        'success': success,
                        'summary': summary
                    }

                except Exception as agent_error:
                    logger.error(f"🤖 [WORKSPACE AUTOPILOT] Agent execution failed: {agent_error}")
                    execution_result = {
                        'success': False,
                        'error': str(agent_error)
                    }

                # Calculate execution time
                execution_time_ms = int((time.time() - trigger_start_time) * 1000)

                # Update trigger with results
                trigger.status = 'completed' if execution_result.get('success') else 'failed'
                trigger.completed_at = timezone.now()
                trigger.execution_time_ms = execution_time_ms
                trigger.result_summary = str(execution_result.get('summary', ''))[:1000]
                trigger.execution_id = execution_result.get('execution_id')

                if not execution_result.get('success'):
                    trigger.error_message = str(execution_result.get('error', 'Unknown error'))[:1000]
                    results['triggers_failed'] += 1
                else:
                    results['triggers_succeeded'] += 1

                trigger.save(update_fields=[
                    'status', 'completed_at', 'execution_time_ms',
                    'result_summary', 'execution_id', 'error_message'
                ])

                results['executions'].append({
                    'trigger_id': str(trigger.id),
                    'title': trigger.title,
                    'agent': agent_name,
                    'success': execution_result.get('success'),
                    'execution_time_ms': execution_time_ms
                })

            except Exception as e:
                logger.error(f"🤖 [WORKSPACE AUTOPILOT] Error processing trigger {trigger.id}: {e}")
                trigger.status = 'failed'
                trigger.error_message = str(e)[:1000]
                trigger.completed_at = timezone.now()
                trigger.save(update_fields=['status', 'error_message', 'completed_at'])

                results['triggers_failed'] += 1
                results['errors'].append({
                    'trigger_id': str(trigger.id),
                    'error': str(e)
                })

        logger.info(
            f"🤖 [WORKSPACE AUTOPILOT] Tick complete | "
            f"Processed: {results['triggers_processed']} | "
            f"Succeeded: {results['triggers_succeeded']} | "
            f"Failed: {results['triggers_failed']} | "
            f"Skipped: {results['triggers_skipped']}"
        )

        return results

    except Exception as e:
        logger.error(f"🤖 [WORKSPACE AUTOPILOT] Fatal error in tick: {e}")
        results['errors'].append({'fatal': str(e)})
        return results


# =============================================================================
# Session 787: Comprehensive Agent Scheduling
# =============================================================================
# All 73 agents should run autonomously. These tasks organize agents into
# logical groups with appropriate frequencies.
# =============================================================================

def _run_agent_group(group_name: str, agent_names: list, task_generator, emoji: str = "🤖"):
    """
    Helper function to run a group of agents with a task.

    Session 787: Creates shared project ID for agent group to enable collaboration tracking.
    Session 944: Updated to use universal_agent_workspace_output for SKIN layer integration.

    Args:
        group_name: Name of the agent group for logging
        agent_names: List of agent names to execute
        task_generator: Function that takes agent_name and returns a task string
        emoji: Emoji for logging
    """
    from django.utils import timezone

    logger.info(f"{emoji} [{group_name}] Starting scheduled agent group...")

    results = []

    # Session 787: Create a shared project ID for this agent group run
    shared_project_id = f"{group_name.lower().replace(' ', '_')}_{timezone.now().strftime('%Y%m%d_%H%M')}"

    for agent_name in agent_names:
        try:
            task = task_generator(agent_name)

            # Session 944: Use universal_agent_workspace_output to create WorkspaceOperations
            # This ensures agent outputs appear in the Operations Tab
            result = universal_agent_workspace_output(
                agent_name=agent_name,
                topic=task,
                trigger_source='schedule',
                force_production=True  # These are real scheduled runs, not warmups
            )

            success = result.get('success', False) if isinstance(result, dict) else False

            # Session 787: Track contribution with shared project ID for collaboration
            _track_group_contribution(agent_name, group_name, shared_project_id, success)

            results.append({
                'agent': agent_name,
                'success': success,
                'project_id': shared_project_id,
                'file': result.get('file') if isinstance(result, dict) else None,
            })

            status = '✅' if success else '❌'
            logger.info(f"{emoji} [{group_name}] {agent_name}: {status}")

        except Exception as e:
            logger.warning(f"{emoji} [{group_name}] {agent_name} failed: {e}")
            results.append({'agent': agent_name, 'success': False, 'error': str(e)})

    succeeded = len([r for r in results if r.get('success')])
    logger.info(f"{emoji} [{group_name}] Complete: {succeeded}/{len(results)} succeeded (project: {shared_project_id})")
    return results


def _track_group_contribution(agent_name: str, group_name: str, project_id: str, success: bool):
    """
    Session 787: Track agent contribution with shared project ID.
    This creates proper collaboration records when multiple agents work together.

    Session 800 fix: project field requires PartnershipProject instance, not string.
    Since scheduled runs don't have real projects, we create contributions without project.
    """
    try:
        from core.models.agents_registry import AgentContribution, UnifiedAgentTemplate

        # Get or create the agent template
        agent_template, _ = UnifiedAgentTemplate.objects.get_or_create(
            name=agent_name,
            defaults={
                'display_name': agent_name.replace('Agent', ' Agent'),
                'description': f'{agent_name} scheduled execution',
                'specialization': 'general',
            }
        )

        # Session 800: Create contribution without project (project is nullable since Session 752)
        # Scheduled agent runs don't have real PartnershipProject instances
        AgentContribution.objects.create(
            agent=agent_template,
            project=None,  # Session 800: Was passing string, but field requires PartnershipProject instance
            contribution_type='orchestration',
            contribution_role='Collaborator',
            task_description=f'{agent_name} participating in {group_name} scheduled run (project: {project_id})',
            contribution_percentage=100 if success else 0,
        )

        logger.debug(f"✓ Tracked collaboration: {agent_name} -> group {group_name}")

    except Exception as e:
        logger.warning(f"Could not track contribution for {agent_name}: {e}")


