# ============================================================
# Session 863: ConceptForge Pipeline Tasks
# ============================================================

@shared_task(bind=True, max_retries=2, default_retry_delay=120)
def run_conceptforge_pipeline(
    self,
    source_type: str,
    source_id: str,
    source_title: str,
    domain: str,
    quality_score: float = 0.0,
    triggered_by: str = 'celery',
    user_id: int = None
):
    """
    Session 863: Execute a ConceptForge pipeline run.

    This is the main entry point for async ConceptForge execution.
    Creates a run, executes all stages, and produces a dossier.

    Args:
        source_type: Type of source content (blog, decision_summary, etc.)
        source_id: UUID of source content
        source_title: Title for display
        domain: Domain lab to use (legal, market, tech, etc.)
        quality_score: Quality score of source content
        triggered_by: What triggered this run (signal, manual, celery_beat)
        user_id: Optional user ID for permission context
    """
    from core.conceptforge import ConceptForgeOrchestrator

    logger.info(f"🔮 [CONCEPTFORGE] Starting pipeline for '{source_title}' in {domain}Lab")

    try:
        # Get user if specified
        user = None
        if user_id:
            from django.contrib.auth import get_user_model
            User = get_user_model()
            try:
                user = User.objects.get(id=user_id)
            except User.DoesNotExist:
                pass

        # Create orchestrator
        orchestrator = ConceptForgeOrchestrator(user=user)

        # Start the pipeline
        run = orchestrator.start_pipeline(
            source_type=source_type,
            source_id=source_id,
            source_title=source_title,
            domain=domain,
            quality_score=quality_score,
            triggered_by=triggered_by,
            celery_task_id=self.request.id,
        )

        # Execute the pipeline
        success = orchestrator.execute_run(run)

        if success:
            logger.info(
                f"🔮 [CONCEPTFORGE] Pipeline completed for '{source_title}' "
                f"(run_id={run.id}, duration={run.duration_ms}ms)"
            )
            return {
                'status': 'completed',
                'run_id': str(run.id),
                'domain': domain,
                'duration_ms': run.duration_ms,
                'stage_count': run.stages.count(),
            }
        else:
            logger.error(
                f"🔮 [CONCEPTFORGE] Pipeline failed for '{source_title}': {run.error}"
            )
            return {
                'status': 'failed',
                'run_id': str(run.id),
                'error': run.error,
            }

    except Exception as e:
        logger.exception(f"🔮 [CONCEPTFORGE] Pipeline error for '{source_title}': {e}")

        # Retry on transient errors
        if self.request.retries < self.max_retries:
            raise self.retry(exc=e, countdown=120)

        return {
            'status': 'failed',
            'error': str(e),
        }


    """
    Session 863: Manually promote content to ConceptForge.

    Use this to trigger ConceptForge on content that didn't meet
    the automatic gate criteria, or to run with a specific domain.

    Args:
        source_type: Type of source content
        source_id: UUID of source content
        domain: Optional domain override (auto-detects if not specified)
        user_id: User triggering the promotion
    """
    logger.info(f"🔮 [CONCEPTFORGE] Manual promotion: {source_type} {source_id}")

    try:
        # Get source content
        if source_type == 'blog':
            from core.models_unified_system import SelfBlog
            source = SelfBlog.objects.get(id=source_id)
            source_title = source.title
            tags = source.tags if isinstance(source.tags, list) else []
            quality_score = 0.90  # Manual promotion assumes quality
        else:
            source_title = f"{source_type}:{source_id}"
            tags = []
            quality_score = 0.85

        # Determine domain if not specified
        if not domain:
            from core.conceptforge import ConceptForgeOrchestrator
            orchestrator = ConceptForgeOrchestrator()
            _, _, domain = orchestrator.should_trigger(
                quality_score=quality_score,
                tags=tags,
                force=True,
            )
            domain = domain or 'tech'

        # Trigger the pipeline
        run_conceptforge_pipeline.delay(
            source_type=source_type,
            source_id=str(source_id),
            source_title=source_title,
            domain=domain,
            quality_score=quality_score,
            triggered_by='manual_promotion',
            user_id=user_id,
        )

        return {
            'status': 'queued',
            'domain': domain,
            'source_title': source_title,
        }

    except Exception as e:
        logger.exception(f"🔮 [CONCEPTFORGE] Promotion failed: {e}")
        return {
            'status': 'failed',
            'error': str(e),
        }


    """
    Session 863: Execute a single ConceptForge stage.

    Used for individual stage retries or parallel stage execution.

    Args:
        run_id: UUID of the ConceptForge run
        stage_name: Name of stage to execute
    """
    from core.models_conceptforge import ConceptForgeRun, ConceptForgeStageRun
    from core.conceptforge import ConceptForgeOrchestrator, get_lab_config

    logger.info(f"🔮 [CONCEPTFORGE] Running stage '{stage_name}' for run {run_id}")

    try:
        run = ConceptForgeRun.objects.get(id=run_id)
        stage = run.stages.get(stage_name=stage_name)
        lab_config = get_lab_config(run.domain)

        if not lab_config:
            stage.fail(f"No lab config for domain: {run.domain}")
            return {'status': 'failed', 'error': 'no lab config'}

        # Get previous outputs
        previous_outputs = {}
        for prev_stage in run.stages.filter(status='completed').order_by('stage_order'):
            if prev_stage.stage_order < stage.stage_order:
                previous_outputs[prev_stage.stage_name] = prev_stage.output_text

        # Execute stage
        orchestrator = ConceptForgeOrchestrator(user=run.user)
        success = orchestrator._execute_stage(
            run=run,
            stage=stage,
            lab_config=lab_config,
            previous_outputs=previous_outputs,
        )

        return {
            'status': 'completed' if success else 'failed',
            'stage': stage_name,
            'output_length': len(stage.output_text) if stage.output_text else 0,
        }

    except Exception as e:
        logger.exception(f"🔮 [CONCEPTFORGE] Stage {stage_name} failed: {e}")
        return {
            'status': 'failed',
            'stage': stage_name,
            'error': str(e),
        }


# =============================================================================
# Session 865: Video Status Polling Task
# =============================================================================

@shared_task
def poll_processing_videos():
    """
    Session 865: Poll processing videos and update their status.

    Videos are created with status='processing' when generation is submitted,
    but for autonomous/system-generated videos, no one polls to update them.
    This task runs periodically to check and update video statuses.
    """
    from content.models import VideoHistory
    from content.video_provider import runway_provider
    from django.utils import timezone

    logger.info("🎬 [VIDEO POLL] Checking processing videos...")

    # Get videos stuck in processing (older than 1 minute to avoid race conditions)
    cutoff_time = timezone.now() - timezone.timedelta(minutes=1)
    stuck_videos = VideoHistory.objects.filter(
        status='processing',
        created_at__lt=cutoff_time
    )

    total = stuck_videos.count()
    if total == 0:
        logger.info("🎬 [VIDEO POLL] No processing videos to check")
        return {'checked': 0, 'updated': 0, 'failed': 0}

    logger.info(f"🎬 [VIDEO POLL] Found {total} processing videos")

    completed = 0
    failed = 0
    still_processing = 0
    errors = 0

    for vid in stuck_videos[:50]:  # Limit to 50 per run to avoid timeout
        task_id = str(vid.video_id) if vid.video_id else None
        if not task_id:
            continue

        try:
            result = runway_provider.check_status(task_id)

            if result.status == 'completed' and result.video_url:
                vid.video_url = result.video_url
                vid.thumbnail_url = getattr(result, 'thumbnail_url', '') or ''
                vid.status = 'completed'
                vid.generation_completed = timezone.now()
                vid.save()
                completed += 1
                logger.info(f"✅ [VIDEO POLL] Updated: {vid.id}")
            elif result.status == 'failed':
                vid.status = 'failed'
                vid.error_message = result.error_message or 'Unknown error'
                vid.save()
                failed += 1
                logger.warning(f"❌ [VIDEO POLL] Failed: {vid.id} - {result.error_message}")
            else:
                still_processing += 1
        except Exception as e:
            errors += 1
            logger.warning(f"⚠️ [VIDEO POLL] Error checking {vid.id}: {e}")

    logger.info(f"🎬 [VIDEO POLL] Complete: {completed} updated, {failed} failed, {still_processing} still processing, {errors} errors")

    return {
        'checked': total,
        'updated': completed,
        'failed': failed,
        'still_processing': still_processing,
        'errors': errors
    }


# =============================================================================
# Session 866: Initiative Pipeline Advancement Task
# =============================================================================

@shared_task
def advance_initiative_pipeline(limit: int = 10, auto_approve: bool = True):
    """
    Session 866: Advance initiatives through their 5-stage pipeline.
    Session 880: Increased frequency (hourly), limit (10), and added auto-approval.

    Problem: Initiatives are created with empty PENDING stages, but no mechanism
    generates the actual stage documents to make the pipeline flow.

    This task:
    1. Finds initiatives with PENDING stages (no documents)
    2. For the current stage, generates appropriate content using TechnicalDocumentAgent
    3. Links the document to the stage
    4. Session 880: Auto-approves the stage and advances to next stage

    Stage document types:
    - Stage 1: Research Brief (market analysis, feasibility)
    - Stage 2: Prototype Plan (architecture, technical design)
    - Stage 3: Evaluation (testing criteria, acceptance tests)
    - Stage 4: Tech Design (implementation details, code structure)
    - Stage 5: Pilot Execution (deployment plan, monitoring)

    Args:
        limit: Maximum initiatives to process per run (default 10, was 5)
        auto_approve: Auto-approve generated documents and advance stages (default True)

    Returns:
        Summary of advancement results
    """
    from core.models_document_registry import Initiative, InitiativeStage, STAGE_NAMES
    from core.models_unified_system import SelfBlog
    from core.agents.technical_document_agent import TechnicalDocumentAgent
    import uuid

    logger.info(f"📋 [INITIATIVE PIPELINE] Starting advancement for up to {limit} initiatives...")

    # Find initiatives with pending stages that need documents or approval
    # Session 1021: Only process the CURRENT stage — never skip ahead.
    # Prior stages must be APPROVED before generating docs for the next one.
    initiatives_to_advance = []
    for init in Initiative.objects.filter(status='ACTIVE').order_by('-updated_at')[:limit * 2]:
        stage_num = init.current_stage
        if stage_num < 1 or stage_num > 5:
            continue

        # Verify prior stage is APPROVED (skip Stage 1 — no prior stage)
        if stage_num > 1:
            prior = InitiativeStage.objects.filter(
                initiative=init, stage=stage_num - 1
            ).first()
            if not prior or prior.status != 'APPROVED':
                continue  # Prior stage not approved yet — don't skip ahead

        stage = InitiativeStage.objects.filter(
            initiative=init, stage=stage_num
        ).first()

        # Stage needs a document generated
        # Session 1033: Also include IN_REVIEW stages with no document (dead state fix)
        if not stage or (stage.status in ('PENDING', 'DRAFT', 'IN_REVIEW') and not stage.document_id):
            initiatives_to_advance.append({
                'initiative': init,
                'stage_num': stage_num,
                'stage': stage,
                'needs_document': True,
            })

        # Session 1021: Stage has document but is still DRAFT — needs approval only
        elif stage.status == 'DRAFT' and stage.document_id:
            initiatives_to_advance.append({
                'initiative': init,
                'stage_num': stage_num,
                'stage': stage,
                'needs_document': False,
            })

    if not initiatives_to_advance:
        logger.info("📋 [INITIATIVE PIPELINE] No initiatives need advancement")
        return {'processed': 0, 'documents_created': 0, 'errors': []}

    logger.info(f"📋 [INITIATIVE PIPELINE] Found {len(initiatives_to_advance)} initiatives to advance")

    results = {
        'processed': 0,
        'documents_created': 0,
        'stages_approved': 0,
        'stages_updated': [],
        'errors': []
    }

    # Process each initiative
    for item in initiatives_to_advance[:limit]:
        init = item['initiative']
        stage_num = item['stage_num']
        stage = item['stage']
        needs_document = item.get('needs_document', True)

        logger.info(f"📋 [INITIATIVE PIPELINE] Processing: {init.name[:50]}... Stage {stage_num} (needs_doc={needs_document})")

        try:
            stage_name = STAGE_NAMES.get(stage_num, f'Stage {stage_num}')

            # Session 1021: If stage already has a document (created by handle_stage_task_completion),
            # skip document generation and go straight to auto-approval
            if not needs_document and stage and stage.document_id:
                logger.info(f"📋 [INITIATIVE PIPELINE] Stage {stage_num} already has document — skipping generation, approving")
                results['processed'] += 1
            else:
                # Build the document generation task
                doc_type = _get_stage_document_type(stage_num)

                # Session 1021: Gather REAL system data before asking agent to write
                research_context = _gather_initiative_research(init, stage_num)
                previous_context = _get_previous_stage_context(init, stage_num)

                task_prompt = f"""Create a formal {stage_name} document for the initiative: {init.name}

Initiative Description: {init.description or 'No description provided'}

Parent Topic: {init.parent_topic or init.name}

This is Stage {stage_num} of 5 in the initiative pipeline.

Document type: {doc_type}

REAL DATA (use this as the basis for your document — do NOT invent data):
{research_context}

Previous stage context:
{previous_context}

Requirements:
1. Use formal, professional language
2. Reference SPECIFIC data points from the REAL DATA section above
3. Be structured for executive review and decision-making
4. If no real data was found, clearly state "No data available" — do NOT hallucinate
5. Include specific, measurable criteria where applicable
6. Do NOT produce blog-style content — this is a technical document
"""

                # Generate the document using TechnicalDocumentAgent
                agent = TechnicalDocumentAgent()
                result = agent.execute(
                    task=task_prompt,
                    context={
                        'initiative_id': str(init.id),
                        'initiative_name': init.name,
                        'topic': init.name,
                        'stage': stage_num,
                        'doc_type': doc_type,
                        'research_context': research_context,
                        'autonomous': True,
                    },
                    scifi_context={},
                    spider_context={}
                )

                # Extract content from result
                content = ""
                if hasattr(result, 'data') and result.data:
                    if isinstance(result.data, dict):
                        content_data = result.data.get('content', {})
                        if isinstance(content_data, dict):
                            content = content_data.get('full_text', '')
                        elif content_data:
                            content = str(content_data)
                    else:
                        content = str(result.data)
                elif hasattr(result, 'message') and result.message:
                    content = result.message

                if not content or len(content) < 100:
                    results['errors'].append(f"{init.name}: Stage {stage_num} - Generated content too short")
                    continue

                # Create the SelfBlog document
                doc_title = f"[Stage {stage_num} - {stage_name}] {init.name[:80]}"
                blog = SelfBlog.objects.create(
                    id=uuid.uuid4(),
                    title=doc_title,
                    author='InitiativePipeline',  # Session 998: Author tracking
                    category='internal',  # Stage documents are internal
                    intro=f"Stage {stage_num} ({stage_name}) document for initiative: {init.name}",
                    full_text=content,
                    tone='formal',
                    stats_snapshot={
                        'auto_generated': True,
                        'parent_topic': init.parent_topic or init.name,
                        'stage': stage_num,
                        'stage_name': stage_name,
                        'initiative_id': str(init.id),
                        'doc_type': doc_type,
                    }
                )

                logger.info(f"📋 [INITIATIVE PIPELINE] Created document: {blog.id}")

                # Create or update the stage record
                if not stage:
                    stage = InitiativeStage.objects.create(
                        initiative=init,
                        stage=stage_num,
                        status='DRAFT',
                        document_id=blog.id,
                    )
                else:
                    stage.document_id = blog.id
                    stage.status = 'DRAFT'
                    stage.save()

                # Update initiative current_stage if needed
                if init.current_stage < stage_num:
                    init.current_stage = stage_num
                    init.save()

                results['documents_created'] += 1
                results['stages_updated'].append(f"{init.name[:30]}... Stage {stage_num}")
                results['processed'] += 1

                logger.info(f"✅ [INITIATIVE PIPELINE] Created document for: {init.name[:30]}... Stage {stage_num}")

            # Session 880: Auto-approve the stage and advance to next
            # Session 916: Use approve() method which enforces invariants + logs
            if auto_approve:
                try:
                    # Refresh stage to get the linked document
                    stage.refresh_from_db()

                    # Use approve() method - enforces document requirement + logs transition
                    stage.approve(
                        approved_by='auto_pipeline',
                        notes='Auto-approved via generate_initiative_stage_document task',
                        checks_passed={
                            'has_document': stage.document is not None,
                            'auto_approve_enabled': True,
                            'celery_task': 'generate_initiative_stage_document',
                        }
                    )

                    results['stages_approved'] += 1
                    logger.info(f"✅ [INITIATIVE PIPELINE] Auto-approved: {init.name[:30]}... Stage {stage_num}")

                    # Advance to next stage if not at stage 5
                    if stage_num < 5:
                        next_stage, created = InitiativeStage.objects.get_or_create(
                            initiative=init,
                            stage=stage_num + 1,
                            defaults={'status': 'PENDING'}
                        )
                        init.current_stage = stage_num + 1
                        init.save()
                        logger.info(f"📋 [INITIATIVE PIPELINE] Advanced to Stage {stage_num + 1}")
                    elif stage_num == 5:
                        # All stages complete - mark initiative as completed
                        init.status = 'COMPLETED'
                        init.save()
                        logger.info(f"🎉 [INITIATIVE PIPELINE] Initiative COMPLETED: {init.name[:30]}...")

                        # Create final deliverable if method exists
                        if hasattr(init, 'create_final_deliverable'):
                            try:
                                deliverable = init.create_final_deliverable()
                                if deliverable:
                                    logger.info(f"📦 [INITIATIVE PIPELINE] Created deliverable: {deliverable.id}")
                            except Exception as del_err:
                                logger.warning(f"Could not create deliverable: {del_err}")

                except Exception as approve_err:
                    logger.warning(f"Auto-approve failed for Stage {stage_num}: {approve_err}")

        except Exception as e:
            error_msg = f"{init.name[:30]}...: Stage {stage_num} - {str(e)}"
            results['errors'].append(error_msg)
            logger.error(f"❌ [INITIATIVE PIPELINE] Error: {error_msg}")

    logger.info(f"📋 [INITIATIVE PIPELINE] Complete: {results['processed']} processed, {results['documents_created']} docs, {results['stages_approved']} approved")

    return results


def _get_stage_document_type(stage_num: int) -> str:
    """Get the document type for a given stage number."""
    doc_types = {
        1: 'Research Brief - Market analysis, feasibility study, opportunity assessment',
        2: 'Prototype Plan - Architecture overview, technical approach, MVP scope',
        3: 'Evaluation Criteria - Testing requirements, acceptance criteria, success metrics',
        4: 'Technical Design - Implementation details, code structure, integration points',
        5: 'Pilot Execution Plan - Deployment strategy, monitoring, rollback procedures',
    }
    return doc_types.get(stage_num, f'Stage {stage_num} Document')


def _gather_initiative_research(initiative, stage_num: int) -> str:
    """
    Session 1021: Gather REAL system data relevant to an initiative topic.

    Queries SpiderData, SignalClusters, AgentConversations, and Deliverables
    to build actual research context — not hallucinated content.

    Returns a formatted string with real data for the TechnicalDocumentAgent.
    """
    from core.models_unified_system import SpiderData, AgentConversation
    from core.models import SignalCluster
    from django.utils import timezone
    from datetime import timedelta

    parts = []
    topic = initiative.name
    description = initiative.description or ''

    # Extract search keywords from initiative name (words > 3 chars, skip common words)
    stop_words = {'that', 'this', 'with', 'from', 'into', 'which', 'when', 'what',
                  'have', 'been', 'will', 'would', 'could', 'should', 'does', 'also',
                  'more', 'most', 'some', 'than', 'then', 'them', 'they', 'their',
                  'each', 'about', 'over', 'such', 'after', 'before', 'between',
                  'through', 'using', 'based', 'module', 'pipeline', 'component',
                  'system', 'prototype', 'enhancement', 'create', 'build', 'implement',
                  'deliver', 'initiate', 'focused', 'small', 'lightweight'}
    keywords = [w for w in topic.lower().split() if len(w) > 3 and w not in stop_words][:6]

    since = timezone.now() - timedelta(days=14)

    # 1. Spider Data — real external intelligence
    try:
        spider_hits = []
        for kw in keywords[:3]:
            hits = SpiderData.objects.filter(
                embedding_text__icontains=kw,
                created_at__gte=since
            ).order_by('-created_at')[:3]
            for h in hits:
                if h.id not in [x.id for x in spider_hits]:
                    spider_hits.append(h)
            if len(spider_hits) >= 5:
                break

        if spider_hits:
            parts.append("## Recent Spider Intelligence")
            for sd in spider_hits[:5]:
                source = sd.source_url or 'internal'
                text = (sd.embedding_text or sd.processed_data or '')[:300]
                parts.append(f"- [{sd.spider_name}] ({sd.data_type}, {sd.created_at.strftime('%m/%d')}): {text}")
    except Exception as e:
        logger.warning(f"[Initiative research] Spider query failed: {e}")

    # 2. Signal Clusters — detected patterns
    try:
        clusters = []
        for kw in keywords[:3]:
            hits = SignalCluster.objects.filter(
                name__icontains=kw,
                detected_at__gte=since
            ).order_by('-detected_at')[:3]
            for h in hits:
                if h.id not in [x.id for x in clusters]:
                    clusters.append(h)
            if len(clusters) >= 3:
                break

        if clusters:
            parts.append("## Related Signal Clusters")
            for sc in clusters[:3]:
                parts.append(f"- {sc.name} (type={sc.pattern_type}, detected={sc.detected_at.strftime('%m/%d')})")
    except Exception as e:
        logger.warning(f"[Initiative research] SignalCluster query failed: {e}")

    # 3. Agent Conversations — what agents discussed about this topic
    try:
        convos = []
        for kw in keywords[:2]:
            hits = AgentConversation.objects.filter(
                topic__icontains=kw,
                started_at__gte=since
            ).order_by('-started_at')[:3]
            for h in hits:
                if h.id not in [x.id for x in convos]:
                    convos.append(h)
            if len(convos) >= 3:
                break

        if convos:
            parts.append("## Related Agent Conversations")
            for ac in convos[:3]:
                conclusion = (ac.conclusion or '')[:200]
                conclusion_text = f" — conclusion: {conclusion}" if conclusion else ''
                parts.append(f"- \"{ac.topic[:80]}\" ({ac.started_at.strftime('%m/%d')}){conclusion_text}")
    except Exception as e:
        logger.warning(f"[Initiative research] Conversation query failed: {e}")

    # 4. Existing Deliverables — what's already been produced
    try:
        from core.models_deliverables import Deliverable
        deliverables = Deliverable.objects.filter(initiative=initiative).order_by('-created_at')[:3]
        if deliverables:
            parts.append("## Existing Deliverables")
            for d in deliverables:
                meta = d.metadata or {}
                parts.append(f"- {d.title[:80]} (type={meta.get('content_type', 'unknown')}, created={d.created_at.strftime('%m/%d')})")
    except Exception as e:
        logger.warning(f"[Initiative research] Deliverable query failed: {e}")

    if not parts:
        return f"No system data found for topic '{topic}'. The document should outline a plan based on the initiative description: {description[:500]}"

    header = f"## Real System Data for: {topic}\nKeywords searched: {', '.join(keywords)}\nData window: last 14 days\n"
    return header + "\n\n".join(parts)


def _get_previous_stage_context(initiative, current_stage: int) -> str:
    """Get context from previous completed stages."""
    from core.models_document_registry import InitiativeStage
    from core.models_unified_system import SelfBlog

    context_parts = []

    for stage_num in range(1, current_stage):
        stage = InitiativeStage.objects.filter(
            initiative=initiative,
            stage=stage_num
        ).first()

        if stage and stage.document_id:
            try:
                doc = SelfBlog.objects.get(id=stage.document_id)
                # Include a summary of the previous stage document
                summary = doc.intro or doc.full_text[:500] if doc.full_text else ''
                context_parts.append(f"**Stage {stage_num} Summary:** {summary}")
            except SelfBlog.DoesNotExist:
                pass

    if not context_parts:
        return "No previous stage documents available - this is a new initiative."

    return "\n\n".join(context_parts)


# =============================================================================
# Session 885: Auto-Kickstart Stuck Initiatives
# =============================================================================

@shared_task
def auto_kickstart_stuck_initiatives(limit: int = 10):
    """
    Session 885: Automatically kickstart initiatives stuck at Stage 1.

    Problem: Initiatives are created but Stage 1 tasks are never dispatched,
    leaving them stuck with 0% completion.

    This task runs every 10 minutes and:
    1. Finds ACTIVE initiatives at Stage 1 with no work done (stages_with_work=0)
    2. Dispatches Stage 1 tasks (ResearchAgent + MarketIntelligenceAgent)
    3. Updates Stage 1 status to DRAFT

    Args:
        limit: Maximum initiatives to kickstart per run (default: 10)

    Returns:
        Summary of kickstart results
    """
    from core.models_document_registry import Initiative, InitiativeStage
    from core.services.conversation_initiative_pipeline import CONTENT_TYPE_STAGES

    logger.info(f"🚀 [AUTO-KICKSTART] Starting auto-kickstart for up to {limit} stuck initiatives...")

    results = {
        'found': 0,
        'kickstarted': 0,
        'tasks_dispatched': 0,
        'errors': [],
    }

    # Find stuck initiatives: ACTIVE, Stage 1, no work done
    stuck_initiatives = []
    for initiative in Initiative.objects.filter(status='ACTIVE', current_stage=1).order_by('-created_at')[:limit * 2]:
        if initiative.stages_with_work == 0:
            stuck_initiatives.append(initiative)

    stuck_initiatives = stuck_initiatives[:limit]
    results['found'] = len(stuck_initiatives)

    if not stuck_initiatives:
        logger.info("🚀 [AUTO-KICKSTART] No stuck initiatives found")
        return results

    logger.info(f"🚀 [AUTO-KICKSTART] Found {len(stuck_initiatives)} stuck initiatives to kickstart")

    for initiative in stuck_initiatives:
        topic = initiative.parent_topic or initiative.name
        content_type = _detect_initiative_content_type(topic)

        try:
            # Ensure Stage 1 exists and is in DRAFT
            stage_1, created = InitiativeStage.objects.get_or_create(
                initiative=initiative,
                stage=1,
                defaults={
                    'status': 'DRAFT',
                    'notes': f'Auto-kickstarted at {timezone.now().isoformat()}',
                }
            )

            if stage_1.status == 'PENDING':
                stage_1.status = 'DRAFT'
                stage_1.notes = f'Auto-kickstarted at {timezone.now().isoformat()}'
                stage_1.save()

            # Get stage 1 tasks for this content type
            stage_config = CONTENT_TYPE_STAGES.get(content_type, CONTENT_TYPE_STAGES.get('document', {}))
            stage_1_info = stage_config.get(1, {'tasks': []})
            tasks = stage_1_info.get('tasks', []) if isinstance(stage_1_info, dict) else []

            # Dispatch each task
            for task_config in tasks:
                agent_name = task_config['agent']
                task_template = task_config['task_template']
                task_description = task_template.format(topic=topic)

                try:
                    execute_initiative_stage_task.delay(
                        initiative_id=str(initiative.id),
                        stage_num=1,
                        agent_name=agent_name,
                        task=task_description,
                        context={
                            'source': 'auto_kickstart',
                            'topic': topic,
                        }
                    )
                    results['tasks_dispatched'] += 1
                except Exception as e:
                    results['errors'].append(f"{initiative.name[:30]}: {agent_name} - {e}")

            results['kickstarted'] += 1
            logger.info(f"🚀 [AUTO-KICKSTART] Kickstarted: {initiative.name[:50]}...")

        except Exception as e:
            results['errors'].append(f"{initiative.name[:30]}: {e}")
            logger.error(f"🚀 [AUTO-KICKSTART] Error: {initiative.name[:30]} - {e}")

    logger.info(
        f"🚀 [AUTO-KICKSTART] Complete: {results['kickstarted']} kickstarted, "
        f"{results['tasks_dispatched']} tasks dispatched, {len(results['errors'])} errors"
    )

    return results


def _detect_initiative_content_type(topic: str) -> str:
    """Detect content type from initiative topic text."""
    topic_lower = topic.lower()

    if any(kw in topic_lower for kw in ['persona', 'customer', 'user', 'buyer']):
        return 'strategy'
    elif any(kw in topic_lower for kw in ['plan', 'roadmap', 'timeline', 'milestone']):
        return 'plan'
    elif any(kw in topic_lower for kw in ['research', 'study', 'analysis', 'audit']):
        return 'research'
    elif any(kw in topic_lower for kw in ['content', 'blog', 'article', 'post']):
        return 'document'
    else:
        return 'strategy'  # Default


# =============================================================================
# SESSION 900: SIGNAL INTELLIGENCE - Signal Aggregation Tasks
# =============================================================================

@shared_task(bind=True, name='aggregate_spider_signals')
def aggregate_spider_signals(self, lookback_hours: int = 6):
    """
    Session 900: Aggregate recent spider data into SignalClusters.

    This task runs periodically to:
    1. Fetch recent SpiderData
    2. Cluster signals by topic/keyword similarity
    3. Create/update SignalCluster records
    4. Generate AutoTopic suggestions from actionable clusters

    Args:
        lookback_hours: How far back to look for signals (default 6 hours)

    Returns:
        Dict with aggregation results
    """
    from core.services.signal_aggregation_service import SignalAggregationService

    logger.info(f"🔮 [SIGNAL-AGGREGATION] Starting (lookback: {lookback_hours}h)")

    try:
        service = SignalAggregationService(lookback_hours=lookback_hours)

        # Aggregate signals into clusters
        clusters = service.aggregate_signals()

        # Generate auto topics from actionable clusters
        auto_topics = service.generate_auto_topics(min_confidence=0.5)

        results = {
            'status': 'success',
            'clusters_created': len(clusters),
            'auto_topics_created': len(auto_topics),
            'cluster_names': [c.name for c in clusters],
            'topic_names': [t.name for t in auto_topics],
        }

        logger.info(
            f"🔮 [SIGNAL-AGGREGATION] Complete: "
            f"{len(clusters)} clusters, {len(auto_topics)} auto-topics"
        )

        return results

    except Exception as e:
        logger.error(f"🔮 [SIGNAL-AGGREGATION] Error: {e}")
        return {
            'status': 'error',
            'error': str(e),
        }


@shared_task(bind=True, name='trigger_signal_driven_conversation')
def trigger_signal_driven_conversation(self, auto_topic_id: str):
    """
    Session 900: Trigger a conversation from an AutoTopic.

    This creates a HiveMindSession linked to the AutoTopic and its
    SignalCluster, providing full provenance for the Origin & Trigger UI.

    Args:
        auto_topic_id: UUID of the AutoTopic to trigger

    Returns:
        Dict with conversation details
    """
    from core.models_signal_intelligence import AutoTopic, SignalCluster
    from core.models import HiveMindSession, Agent

    logger.info(f"🎯 [SIGNAL-CONVERSATION] Triggering from AutoTopic: {auto_topic_id}")

    try:
        auto_topic = AutoTopic.objects.get(id=auto_topic_id)

        if auto_topic.status != 'pending':
            return {
                'status': 'skipped',
                'reason': f'AutoTopic status is {auto_topic.status}, not pending',
            }

        # Get suggested agents
        agent_ids = []
        for agent_name in auto_topic.suggested_agent_names:
            agent = Agent.objects.filter(name=agent_name).first()
            if agent:
                agent_ids.append(str(agent.id))

        # Fallback to default agents if none found
        if len(agent_ids) < 2:
            default_agents = Agent.objects.filter(
                name__in=['ContentStrategyAgent', 'ResearchAgent', 'TrendAnalysisAgent']
            )[:3]
            agent_ids = [str(a.id) for a in default_agents]

        # Create HiveMindSession with signal provenance
        session = HiveMindSession.objects.create(
            session_mode='conversation',
            question=auto_topic.name,
            context=auto_topic.description,
            conversation_type=auto_topic.suggested_conversation_type,
            objective=f"Discuss and provide actionable insights on: {auto_topic.name}",
            success_criteria=[
                "Identify key opportunities or risks",
                "Propose concrete next steps",
                "Reach consensus on recommendations",
            ],
            auto_selected_agents=True,
            participant_ids=agent_ids,
            status='initializing',
            # Session 900: Signal provenance
            signal_cluster=auto_topic.signal_cluster,
            auto_topic=auto_topic,
            trigger_confidence=auto_topic.confidence,
        )

        # Mark AutoTopic as triggered
        auto_topic.mark_triggered(session.id)

        logger.info(
            f"🎯 [SIGNAL-CONVERSATION] Created session {session.id} "
            f"from AutoTopic '{auto_topic.name}'"
        )

        # Trigger the actual conversation execution
        # Session 902: Pass hive_session_id for status updates
        try:
            run_triggered_conversation.delay(
                topic=auto_topic.name,
                conversation_type=auto_topic.suggested_conversation_type,
                objective=session.objective,
                success_criteria=session.success_criteria,
                auto_select_agents=False,  # Already selected
                participant_ids=agent_ids,
                hive_session_id=str(session.id),  # Session 902: Link to session
            )
        except Exception as e:
            logger.warning(f"Could not dispatch conversation task: {e}")

        return {
            'status': 'success',
            'session_id': str(session.id),
            'topic': auto_topic.name,
            'agents': auto_topic.suggested_agent_names,
            'signal_cluster_id': str(auto_topic.signal_cluster.id) if auto_topic.signal_cluster else None,
        }

    except AutoTopic.DoesNotExist:
        return {
            'status': 'error',
            'error': f'AutoTopic {auto_topic_id} not found',
        }
    except Exception as e:
        logger.error(f"🎯 [SIGNAL-CONVERSATION] Error: {e}")
        return {
            'status': 'error',
            'error': str(e),
        }


@shared_task(bind=True, name='process_pending_auto_topics')
def process_pending_auto_topics(self, max_topics: int = 3):
    """
    Session 900: Process pending AutoTopics and trigger conversations.

    This task runs periodically to find actionable AutoTopics and
    trigger conversations from them.

    Args:
        max_topics: Maximum topics to process per run (default 3)

    Returns:
        Dict with processing results
    """
    from core.models_signal_intelligence import AutoTopic
    from django.db import models
    from django.utils import timezone

    logger.info(f"📋 [PROCESS-TOPICS] Processing up to {max_topics} pending topics")

    try:
        # Get pending topics ordered by confidence and urgency
        # Session 902: Fixed missing models import for Q object
        pending_topics = AutoTopic.objects.filter(
            status='pending',
            confidence__gte=0.5,
        ).filter(
            models.Q(expires_at__isnull=True) | models.Q(expires_at__gt=timezone.now())
        ).order_by('-urgency', '-confidence')[:max_topics]

        results = {
            'status': 'success',
            'topics_found': pending_topics.count(),
            'topics_triggered': 0,
            'triggered_sessions': [],
        }

        for topic in pending_topics:
            try:
                # Trigger conversation synchronously to track results
                result = trigger_signal_driven_conversation(str(topic.id))

                if result.get('status') == 'success':
                    results['topics_triggered'] += 1
                    results['triggered_sessions'].append({
                        'topic': topic.name,
                        'session_id': result.get('session_id'),
                    })

            except Exception as e:
                logger.error(f"📋 [PROCESS-TOPICS] Error triggering {topic.name}: {e}")

        logger.info(
            f"📋 [PROCESS-TOPICS] Complete: "
            f"{results['topics_triggered']}/{results['topics_found']} topics triggered"
        )

        return results

    except Exception as e:
        logger.error(f"📋 [PROCESS-TOPICS] Error: {e}")
        return {
            'status': 'error',
            'error': str(e),
        }


@shared_task(bind=True, name='cleanup_expired_signals')
def cleanup_expired_signals(self):
    """
    Session 900: Clean up expired SignalClusters and AutoTopics.

    Marks expired clusters as 'archived' and expired topics as 'expired'.
    """
    from core.models_signal_intelligence import SignalCluster, AutoTopic
    from django.utils import timezone

    logger.info("🧹 [SIGNAL-CLEANUP] Cleaning up expired signals")

    now = timezone.now()

    # Archive expired clusters
    expired_clusters = SignalCluster.objects.filter(
        expires_at__lt=now,
        status__in=['detecting', 'active']
    )
    cluster_count = expired_clusters.update(status='archived')

    # Expire old topics
    expired_topics = AutoTopic.objects.filter(
        expires_at__lt=now,
        status='pending'
    )
    topic_count = expired_topics.update(status='expired')

    # Also decay old 'detecting' clusters that never became active
    stale_clusters = SignalCluster.objects.filter(
        status='detecting',
        detected_at__lt=now - timezone.timedelta(days=2)
    )
    stale_count = stale_clusters.update(status='decayed')

    logger.info(
        f"🧹 [SIGNAL-CLEANUP] Complete: "
        f"{cluster_count} clusters archived, {topic_count} topics expired, "
        f"{stale_count} stale clusters decayed"
    )

    return {
        'clusters_archived': cluster_count,
        'topics_expired': topic_count,
        'clusters_decayed': stale_count,
    }


