# =============================================================================
# Session 1058 Level 3: Auto-Dispatch Pending Action Items
# =============================================================================

@shared_task(bind=True, soft_time_limit=300, time_limit=360)
def dispatch_pending_action_items(self):
    """
    Session 1058 Level 3: Dispatch pending action items to assigned agents.
    Runs on beat cycle. Only dispatches items from STAGES_WITH_AUTO_DISPATCH
    on ACTIVE initiatives.
    """
    from core.models_document_registry import (
        Initiative, InitiativeActionItem, STAGES_WITH_AUTO_DISPATCH,
    )
    from core.models import Agent
    from core.models_unified_system import AgentExecution
    from core.agent_router import AgentRouter
    from django.utils import timezone
    from datetime import timedelta

    logger.info("[ACTION-DISPATCH] Starting dispatch cycle")

    # Blocked agents (same as execute_agent_task)
    # Session 1088: Removed AudioAgent — unblocked in Session 1068 but this list was missed
    _BLOCKED_AGENTS = frozenset({'CodeGeneratorAgent'})

    # Query pending items on ACTIVE initiatives, auto-dispatch stages only
    items = (
        InitiativeActionItem.objects
        .filter(
            status='pending',
            initiative__status='ACTIVE',
            source_stage__isnull=False,
            source_stage__stage__in=STAGES_WITH_AUTO_DISPATCH,
        )
        .exclude(assigned_agent='')
        .exclude(assigned_agent__isnull=True)
        .select_related('initiative', 'source_stage')
        [:20]  # Fetch up to 20, dispatch up to 10
    )

    dispatched = []
    skipped = []
    blocked = []
    now = timezone.now()

    for item in items:
        if len(dispatched) >= 10:
            break

        agent_name = item.assigned_agent

        # Safety: skip blocked agents
        if agent_name in _BLOCKED_AGENTS:
            item.block(reason=f'{agent_name} is blocked (Session 1031)')
            blocked.append({'id': str(item.id), 'agent': agent_name, 'reason': 'blocked_agent'})
            continue

        # Safety: validate agent exists in AGENT_MAP or DB
        agent_exists = (
            agent_name in AgentRouter.AGENT_MAP
            or Agent.objects.filter(name=agent_name).exists()
        )
        if not agent_exists:
            item.block(reason=f'{agent_name} not found in AGENT_MAP or DB')
            blocked.append({'id': str(item.id), 'agent': agent_name, 'reason': 'unknown_agent'})
            continue

        # Safety: per-agent daily cap (8 dispatches/day from initiative pipeline)
        today_start = now.replace(hour=0, minute=0, second=0, microsecond=0)
        daily_count = AgentExecution.objects.filter(
            agent__name=agent_name,
            created_at__gte=today_start,
            input_data__source='initiative_action_dispatch',
        ).count()
        if daily_count >= 8:
            skipped.append({'id': str(item.id), 'agent': agent_name, 'reason': 'daily_cap'})
            continue

        # Safety: dedup — skip if same agent ran similar task in last 6 hours
        title_prefix = item.title[:80]
        recent_dup = AgentExecution.objects.filter(
            agent__name=agent_name,
            created_at__gte=now - timedelta(hours=6),
            input_data__task__startswith=title_prefix,
        ).exists()
        if recent_dup:
            skipped.append({'id': str(item.id), 'agent': agent_name, 'reason': 'dedup'})
            continue

        # Dispatch
        item.start(by='auto_dispatcher')

        execute_agent_task.delay(
            agent_name=agent_name,
            task=item.title,
            context={
                'source': 'initiative_action_dispatch',
                'action_item_id': str(item.id),
                'initiative_id': str(item.initiative_id),
                'stage': item.source_stage.stage if item.source_stage else None,
            },
        )
        dispatched.append({
            'id': str(item.id),
            'agent': agent_name,
            'title': item.title[:60],
        })

    result = {
        'dispatched': len(dispatched),
        'skipped': len(skipped),
        'blocked': len(blocked),
        'details': {
            'dispatched': dispatched,
            'skipped': skipped,
            'blocked': blocked,
        },
    }
    logger.info(
        f"[ACTION-DISPATCH] Done: {len(dispatched)} dispatched, "
        f"{len(skipped)} skipped, {len(blocked)} blocked"
    )
    return result


# =============================================================================
# Session 905: Research Self-Unblock Loop
# =============================================================================

@shared_task(bind=True, max_retries=3, default_retry_delay=300)
def retry_blocked_research(self, research_result_id: str):
    """
    Session 905: Retry blocked research after spider data collection.

    This task closes the self-unblock loop:
    1. When research is blocked due to insufficient data, a spider is spawned
    2. This task is scheduled to retry after the spider collects data
    3. If data is now sufficient, research continues; otherwise retry or escalate

    Args:
        research_result_id: UUID of the blocked ResearchResult

    Returns:
        dict with retry status and next steps
    """
    from core.models_research import ResearchResult
    from core.models_document_registry import InitiativeStage
    from core.agents.research_agent import ResearchAgent
    from django.utils import timezone

    logger.info(f"🔄 [RESEARCH-RETRY] Attempting retry for ResearchResult {research_result_id}")

    try:
        research = ResearchResult.objects.get(id=research_result_id)
    except ResearchResult.DoesNotExist:
        logger.error(f"🔄 [RESEARCH-RETRY] ResearchResult {research_result_id} not found")
        return {'status': 'failed', 'error': 'ResearchResult not found'}

    # Check if already complete or failed
    if research.status in ['complete', 'failed']:
        logger.info(f"🔄 [RESEARCH-RETRY] Research already {research.status}, skipping")
        return {'status': 'skipped', 'reason': f'Research already {research.status}'}

    # Check retry limits
    if research.retry_count >= research.max_retries:
        logger.warning(f"🔄 [RESEARCH-RETRY] Max retries ({research.max_retries}) exceeded for {research_result_id}")
        research.status = 'failed'
        research.blocked_reason = f"Max retries exceeded. Last reason: {research.blocked_reason}"
        research.save(update_fields=['status', 'blocked_reason', 'updated_at'])

        # Update stage status
        if research.initiative_stage:
            research.initiative_stage.status = 'REJECTED'
            research.initiative_stage.rejection_reason = 'Research failed after max retries'
            research.initiative_stage.save(update_fields=['status', 'rejection_reason', 'updated_at'])

        return {
            'status': 'failed',
            'error': 'Max retries exceeded',
            'retry_count': research.retry_count
        }

    # Increment retry count
    research.retry_count += 1
    research.save(update_fields=['retry_count', 'updated_at'])

    # Check for new spider data
    from core.models_unified_system import SpiderData
    recent_spider_data = SpiderData.objects.filter(
        created_at__gte=research.created_at,
        data_type__in=['tech', 'news', 'content', 'research']
    ).count()

    logger.info(f"🔄 [RESEARCH-RETRY] Found {recent_spider_data} spider data records since research started")

    # Re-run research with updated data
    try:
        agent = ResearchAgent()
        result = agent.execute(
            task=f"Research topic (retry #{research.retry_count}): {research.topic}",
            context={
                'topic': research.topic,
                'depth': 'comprehensive',
                'autonomous': True,
                'retry_attempt': research.retry_count,
                'initiative_id': str(research.initiative_id),
            },
            scifi_context={},
            spider_context={}
        )

        # Check if research succeeded
        research_successful = result.success if hasattr(result, 'success') else False
        findings = ""
        if hasattr(result, 'data') and result.data:
            if isinstance(result.data, dict):
                results_list = result.data.get('results', [])
                if results_list:
                    findings = str(results_list)[:500]

        data_sufficient = research_successful and len(findings) >= 50

        if data_sufficient:
            # Research succeeded!
            research.status = 'complete'
            research.data_sufficient = True
            research.completed_at = timezone.now()
            research.findings = {'retry_findings': findings[:2000]}
            research.summary = f"Research completed on retry #{research.retry_count}"
            research.save()

            # Update stage to DRAFT (ready for review)
            if research.initiative_stage:
                research.initiative_stage.status = 'DRAFT'
                research.initiative_stage.notes = f"Research completed after {research.retry_count} retry(ies)"
                research.initiative_stage.save(update_fields=['status', 'notes', 'updated_at'])

                # Session 912: Update document content to mark data as available
                # This removes the "Insufficient Data" marker that blocks auto-progression
                if research.initiative_stage.document:
                    doc = research.initiative_stage.document
                    if doc.full_text and '⚠️ Insufficient Data' in doc.full_text:
                        doc.full_text = doc.full_text.replace(
                            '⚠️ Insufficient Data - DataExportAgent may be needed',
                            '✅ Data Available - Research completed on retry'
                        )
                        doc.save(update_fields=['full_text'])
                        logger.info(f"🔄 [RESEARCH-RETRY] Updated document {doc.id} - marked data as available")

            logger.info(f"🔄 [RESEARCH-RETRY] SUCCESS! Research completed on retry #{research.retry_count}")
            return {
                'status': 'success',
                'retry_count': research.retry_count,
                'data_sufficient': True,
                'message': 'Research completed successfully'
            }
        else:
            # Still insufficient, schedule another retry
            from datetime import timedelta
            research.retry_after = timezone.now() + timedelta(minutes=30)
            research.save(update_fields=['retry_after', 'updated_at'])

            # Schedule next retry
            self.apply_async(
                args=[research_result_id],
                eta=research.retry_after
            )

            logger.info(f"🔄 [RESEARCH-RETRY] Still insufficient data, scheduled retry #{research.retry_count + 1}")
            return {
                'status': 'retry_scheduled',
                'retry_count': research.retry_count,
                'next_retry': research.retry_after.isoformat(),
                'message': 'Data still insufficient, scheduled another retry'
            }

    except Exception as e:
        logger.error(f"🔄 [RESEARCH-RETRY] Research execution failed: {e}")
        # Retry the task itself
        raise self.retry(exc=e, countdown=300)


@shared_task(bind=True, queue='default')
def check_blocked_research_for_unblock(self):
    """
    Session 905: Periodic task to check all blocked research and trigger retries.

    Runs every 15 minutes to find research that's ready to retry.
    """
    from core.models_research import ResearchResult
    from django.utils import timezone

    logger.info("🔍 [RESEARCH-UNBLOCK] Checking for blocked research ready to retry")

    from django.db.models import F
    blocked_research = ResearchResult.objects.filter(
        status='blocked',
        retry_after__lte=timezone.now(),
        retry_count__lt=F('max_retries')
    )

    triggered_count = 0
    for research in blocked_research:
        try:
            retry_blocked_research.delay(str(research.id))
            triggered_count += 1
            logger.info(f"🔍 [RESEARCH-UNBLOCK] Triggered retry for {research.id}")
        except Exception as e:
            logger.error(f"🔍 [RESEARCH-UNBLOCK] Failed to trigger retry for {research.id}: {e}")

    logger.info(f"🔍 [RESEARCH-UNBLOCK] Triggered {triggered_count} research retries")
    return {
        'status': 'success',
        'triggered_count': triggered_count
    }


# ==================== SESSION 905: INITIATIVE AUTO-PROGRESSION ====================


@shared_task(bind=True, queue='default')
def process_initiative_auto_progression(self):
    """
    Session 905: Periodic task to auto-progress initiatives through stages.

    Runs every 10 minutes to find DRAFT stages ready for progression and
    automatically approves them, triggering next stage generation.

    Session 1016: Also sweeps ACTIVE initiatives missing owner/next_action
    and demotes them to TRIAGE.
    """
    from core.services.initiative_auto_progression import (
        get_initiatives_ready_for_progression,
        progress_initiative_stage
    )

    logger.info("[AUTO-PROGRESSION] Checking initiatives for auto-progression")

    # Session 1016: Sweep ACTIVE initiatives that don't meet quality gate
    try:
        from core.models_document_registry import Initiative
        from core.services.initiative_circuit_breaker import can_promote_to_active
        demoted = 0
        for init in Initiative.objects.filter(status='ACTIVE'):
            if not can_promote_to_active(init):
                init.status = 'TRIAGE'
                init.save(skip_invariant_check=True)
                demoted += 1
                logger.info(f"[AUTO-PROGRESSION] Demoted '{init.name[:50]}' to TRIAGE (missing owner/evidence)")
        if demoted:
            logger.info(f"[AUTO-PROGRESSION] Demoted {demoted} ACTIVE initiatives to TRIAGE")
    except Exception as e:
        logger.warning(f"[AUTO-PROGRESSION] ACTIVE sweep failed: {e}")

    # Session 1058: Removed TRIAGE→ACTIVE auto-promotion sweep.
    # TRIAGE initiatives now require human promotion via initiative_tool promote action.

    ready_initiatives = get_initiatives_ready_for_progression()
    logger.info(f"📊 [AUTO-PROGRESSION] Found {len(ready_initiatives)} initiatives ready")

    progressed_count = 0
    failed_count = 0
    results = []

    for item in ready_initiatives:
        initiative_id = item['initiative_id']
        try:
            result = progress_initiative_stage(initiative_id, auto_generate_next=True)
            if result.get('success'):
                progressed_count += 1
                # Session 994: Record activity on progression
                try:
                    from core.models_document_registry import Initiative
                    Initiative.objects.get(id=initiative_id).update_activity()
                except Exception:
                    pass
                logger.info(
                    f"📊 [AUTO-PROGRESSION] ✅ Progressed {item['initiative_name']} "
                    f"from Stage {result.get('previous_stage')} to Stage {result.get('new_stage')}"
                )
            else:
                failed_count += 1
                logger.warning(
                    f"📊 [AUTO-PROGRESSION] ⚠️ Failed to progress {item['initiative_name']}: "
                    f"{result.get('error')}"
                )
            results.append(result)
        except Exception as e:
            failed_count += 1
            logger.error(f"📊 [AUTO-PROGRESSION] ❌ Error progressing {initiative_id}: {e}")
            results.append({'initiative_id': initiative_id, 'error': str(e)})

    logger.info(
        f"📊 [AUTO-PROGRESSION] Complete: {progressed_count} progressed, {failed_count} failed"
    )

    # Session 1041: Regenerate missing stage documents for ACTIVE + COMPLETED initiatives.
    # Stages that are PENDING with no document are stuck — trigger doc generation.
    # Also covers COMPLETED initiatives whose docs were cleared for quality reasons.
    regen_count = 0
    try:
        from core.models_document_registry import Initiative, InitiativeStage
        inits = Initiative.objects.filter(status__in=['ACTIVE', 'COMPLETED'])
        for init in inits:
            for sn in range(1, init.current_stage + 1):
                stage = InitiativeStage.objects.filter(
                    initiative=init, stage=sn, document__isnull=True
                ).first()
                if stage and stage.status in ('PENDING', 'DRAFT'):
                    generate_initiative_stage_document.delay(str(init.id), sn)
                    regen_count += 1
                    logger.info(
                        f"[AUTO-PROGRESSION] Queued doc regen for '{init.name[:50]}' Stage {sn}"
                    )
        if regen_count:
            logger.info(f"[AUTO-PROGRESSION] Queued {regen_count} missing stage doc regenerations")
    except Exception as e:
        logger.warning(f"[AUTO-PROGRESSION] Doc regen sweep failed: {e}")

    return {
        'status': 'success',
        'progressed_count': progressed_count,
        'failed_count': failed_count,
        'regen_queued': regen_count,
        'results': results
    }


@shared_task(bind=True, queue='default')
def detect_duplicate_initiatives(self):
    """
    Session 906: Periodic task to detect duplicate initiatives and trigger investigation.

    Runs daily to find initiatives with similar names and either:
    1. Auto-consolidate if confidence is high
    2. Create an investigation task if manual review needed
    """
    from core.management.commands.consolidate_duplicate_initiatives import (
        find_duplicate_clusters,
        calculate_similarity
    )
    from core.models_document_registry import Initiative

    logger.info("🔍 [DUPLICATE-DETECT] Scanning for duplicate initiatives")

    initiatives = Initiative.objects.order_by('-created_at')[:500]
    clusters = find_duplicate_clusters(initiatives, threshold=0.7)

    if not clusters:
        logger.info("🔍 [DUPLICATE-DETECT] No duplicate clusters found")
        return {'status': 'success', 'clusters_found': 0}

    logger.warning(f"🔍 [DUPLICATE-DETECT] Found {len(clusters)} duplicate clusters!")

    # Log details for investigation
    for i, cluster in enumerate(clusters, 1):
        primary = cluster[0]
        duplicates = cluster[1:]
        logger.warning(
            f"🔍 [DUPLICATE-DETECT] Cluster {i}: '{primary.name[:50]}' "
            f"has {len(duplicates)} duplicates"
        )

    # Create an investigation initiative for this issue
    try:
        investigation_name = f"Investigate {len(clusters)} Duplicate Initiative Clusters"
        investigation, created = Initiative.objects.get_or_create(
            name=investigation_name,
            defaults={
                'description': (
                    f"Auto-detected {len(clusters)} clusters of duplicate initiatives. "
                    f"Run: python manage.py consolidate_duplicate_initiatives --fix"
                ),
                'current_stage': 1,
            }
        )
        if created:
            logger.info(f"🔍 [DUPLICATE-DETECT] Created investigation: {investigation.id}")
    except Exception as e:
        logger.error(f"🔍 [DUPLICATE-DETECT] Failed to create investigation: {e}")

    return {
        'status': 'success',
        'clusters_found': len(clusters),
        'total_duplicates': sum(len(c) - 1 for c in clusters),
    }


def _extract_agent_content(result) -> str:
    """
    Session 1041: Extract real content from an AgentResult.

    Many agents put a SHORT summary in result.message while storing the
    actual content in result.data under various keys. This helper checks
    all known patterns:
    - ContentWriterAgent: data['content']['full_text']
    - ResearchAgent (tool path): data['all_results'] + data['key_insights']
    - ResearchAgent (no-tool path): data['response']
    - FullStackDeveloperAgent: data['results'] (code/configs)
    - Generic: any data['full_text'] or data['output'] string
    Falls back to result.message if nothing longer is found.
    """
    message = result.message or ''
    data = result.data or {}

    best = message

    # Pattern 1: ContentWriterAgent — data['content'] is dict with 'full_text'
    content_data = data.get('content')
    if isinstance(content_data, dict):
        ft = content_data.get('full_text', '')
        if ft and len(ft) > len(best):
            best = ft
    elif isinstance(content_data, str) and len(content_data) > len(best):
        best = content_data

    # Pattern 2: Direct full_text or output keys
    for key in ('full_text', 'output', 'response', 'document'):
        val = data.get(key)
        if isinstance(val, str) and len(val) > len(best):
            best = val

    # Pattern 3: ResearchAgent — build prose from key_insights + all_results
    if len(best) < 200:  # Still short — try research data
        parts = []
        insights = data.get('key_insights', [])
        if isinstance(insights, list) and insights:
            parts.append("## Key Insights")
            for i, insight in enumerate(insights[:10], 1):
                if isinstance(insight, str):
                    parts.append(f"{i}. {insight}")

        all_results = data.get('all_results', [])
        if isinstance(all_results, list):
            for r in all_results[:5]:
                if isinstance(r, dict):
                    source = r.get('source', 'Unknown')
                    r_data = r.get('data')
                    if isinstance(r_data, list):
                        items = [str(item.get('title', item) if isinstance(item, dict) else item)[:200] for item in r_data[:5]]
                        if items:
                            parts.append(f"\n## From {source}")
                            parts.extend(f"- {item}" for item in items)
                    elif isinstance(r_data, str) and len(r_data) > 20:
                        parts.append(f"\n## From {source}\n{r_data[:2000]}")

        if parts:
            assembled = "\n".join(parts)
            if len(assembled) > len(best):
                best = assembled

    return best


@shared_task(bind=True, queue='default', max_retries=1, ignore_result=True,
             soft_time_limit=600, time_limit=660)
def generate_initiative_stage_document(self, initiative_id: str, stage_num: int):
    """
    Session 905: Generate a document for a specific initiative stage.

    Uses the appropriate agent based on the stage:
    - Stage 1: ResearchAgent (Research Brief)
    - Stage 2: ThinkingAgent (Prototype Plan)
    - Stage 3: ThinkingAgent (Evaluation Protocol)
    - Stage 4: FullStackDeveloperAgent (Technical Design)
    - Stage 5: ThinkingAgent (Pilot Execution Plan)
    """
    from core.models_document_registry import Initiative, InitiativeStage
    from core.models_unified_system import SelfBlog, Agent

    logger.info(f"📝 [STAGE-GEN] Generating Stage {stage_num} document for initiative {initiative_id}")

    try:
        initiative = Initiative.objects.get(id=initiative_id)
    except Initiative.DoesNotExist:
        logger.error(f"📝 [STAGE-GEN] Initiative {initiative_id} not found")
        return {'success': False, 'error': 'Initiative not found'}

    # Get or create stage record
    stage, created = InitiativeStage.objects.get_or_create(
        initiative=initiative,
        stage=stage_num,
        defaults={'status': 'PENDING'}
    )

    if stage.document:
        logger.info(f"📝 [STAGE-GEN] Stage {stage_num} already has document {stage.document.id}")
        return {'success': False, 'error': 'Stage already has document', 'document_id': str(stage.document.id)}

    # Stage-specific configuration
    # Session 912: Use ContentWriterAgent instead of ThinkingAgent for document generation
    # ThinkingAgent ignores the task and returns system diagnostics instead of documents
    stage_config = {
        1: {'agent': 'ResearchAgent', 'template': 'Research Brief'},
        2: {'agent': 'ContentWriterAgent', 'template': 'Prototype Plan'},
        3: {'agent': 'ContentWriterAgent', 'template': 'Evaluation Protocol'},
        4: {'agent': 'FullStackDeveloperAgent', 'template': 'Technical Design'},
        5: {'agent': 'ContentWriterAgent', 'template': 'Pilot Execution Plan'},
    }

    config = stage_config.get(stage_num, {'agent': 'ContentWriterAgent', 'template': 'Stage Document'})

    # Build context from previous stages
    previous_context = []
    for prev_stage_num in range(1, stage_num):
        try:
            prev_stage = InitiativeStage.objects.get(initiative=initiative, stage=prev_stage_num)
            if prev_stage.document:
                doc_content = prev_stage.document.full_text or prev_stage.document.content or ''
                previous_context.append(f"## Stage {prev_stage_num}: {prev_stage.get_stage_display()}\n{doc_content[:2000]}")
        except InitiativeStage.DoesNotExist:
            pass

    context_text = "\n\n".join(previous_context) if previous_context else "No previous stage documents."

    # Session 922: Detect incomplete/malformed initiative names and enhance prompt
    def is_name_incomplete(name: str) -> bool:
        """Check if initiative name appears truncated or incomplete."""
        if not name or len(name) < 15:
            return True
        # Ends with punctuation suggesting truncation
        if name.rstrip().endswith(('—', ':', '–', '→', ',')):
            return True
        # Starts with lowercase (likely mid-sentence fragment)
        if name[0].islower():
            return True
        # Contains "..." suggesting truncation
        if '...' in name:
            return True
        return False

    name_incomplete = is_name_incomplete(initiative.name)
    description = initiative.description or ''

    # Extract useful context from description if name is incomplete
    enhanced_context = ""
    if name_incomplete and description:
        # Try to extract the "Suggested Feature:" section which often has the full idea
        if 'Suggested Feature:' in description:
            feature_text = description.split('Suggested Feature:')[1][:500].strip()
            enhanced_context = f"\n\n**Additional Context (from conversation):**\n{feature_text}"
        elif len(description) > 50:
            enhanced_context = f"\n\n**Additional Context:**\n{description[:500]}"

        logger.info(f"📝 [STAGE-GEN] Name appears incomplete, using enhanced context")

    # Session 923: Build stage-appropriate prompts
    # Stage 1 uses ResearchAgent - must ask it to RESEARCH, not write documents
    if stage_num == 1:
        # Extract research topic from name and description
        # Prefer description if name appears incomplete
        research_topic = initiative.name
        if name_incomplete and description:
            # Try to extract the "Suggested Feature:" section
            if 'Suggested Feature:' in description:
                research_topic = description.split('Suggested Feature:')[1][:300].strip()
            elif len(description) > 30:
                research_topic = description[:300]

        # Clean up the topic for search
        research_topic = research_topic.replace('—', '').replace('...', '').strip()
        if not research_topic or len(research_topic) < 10:
            research_topic = f"{initiative.name} {description[:200] if description else ''}"

        logger.info(f"📝 [STAGE-GEN] Stage 1 research topic: {research_topic[:100]}...")

        # Session 923: Be explicit about using EXTERNAL research, not internal data queries
        # Session 1016: Binding directive to prevent stage doc drift
        prompt = f"""Research this topic using EXTERNAL sources (web_search, spider_query).
DO NOT use query_internal_data - this is NOT about internal system analysis.

BINDING DIRECTIVE: Your output must directly advance THIS initiative: "{initiative.name}".
If you cannot find relevant data for this specific topic, return "BLOCKED: [reason]" instead of writing about something else.

## Research Topic
{research_topic}

## Background Context
{initiative.description or 'Research this topic thoroughly.'}{enhanced_context}

## Instructions
1. Use web_search to find current information about this topic from the internet
2. Use spider_query to check recent news and trends from our spider network
3. Synthesize the findings into actionable insights

## Required Output
Provide a research brief with:
1. **Research Findings** - Specific facts, statistics, and data points you discovered
2. **Data Sources** - Which web sources and spider data you used
3. **Key Insights** - 3-5 most important takeaways
4. **Recommendation** - Should this project proceed? Why or why not?
5. **Action Items** - Next steps with format "- AgentName: Task description (Timeline)"

IMPORTANT: Use web_search as your PRIMARY tool. This is external market/topic research, NOT internal system analysis."""
    else:
        # Stages 2-5 use content-generating agents
        # Session 1016: Binding directive to prevent stage doc drift
        prompt = f"""Generate a {config['template']} document for this initiative.

BINDING DIRECTIVE: Stay narrowly focused on this initiative. Do not write about tangential topics.
Your output must directly advance THIS initiative: "{initiative.name}".

## Initiative
**Name:** {initiative.name}
**Description:** {initiative.description or 'No description provided'}{enhanced_context}

## Previous Stage Context
{context_text}

## Your Task
Create a comprehensive {config['template']} document that builds on the previous stages.
{"Note: The initiative name may be incomplete - use the description and additional context to understand the full scope." if name_incomplete else ""}
Include relevant sections based on the stage type:

Stage {stage_num} ({config['template']}) should include:
"""

        # Add stage-specific instructions for stages 2-5
        stage_instructions = {
            2: "- Architecture Overview\n- Implementation Approach\n- Key Components\n- Risk Assessment\n- Action Items (use format: \"- AgentName: Task description (Timeline)\")",
            3: "- Success Criteria\n- Metrics to Track\n- Evaluation Timeline\n- Go/No-Go Decision Criteria\n- Action Items (use format: \"- AgentName: Task description (Timeline)\")",
            4: "- Technical Specification\n- Dependencies\n- Integration Points\n- Testing Strategy\n- Action Items (use format: \"- AgentName: Task description (Timeline)\")",
            5: "- Pilot Results\n- Learnings\n- Recommendations\n- Scale Plan\n- Action Items (use format: \"- AgentName: Task description (Timeline)\")",
        }
        prompt += stage_instructions.get(stage_num, "- Relevant sections for this stage")

    try:
        # Get the agent
        agent_model = Agent.objects.filter(name=config['agent']).first()
        if not agent_model:
            logger.warning(f"📝 [STAGE-GEN] Agent {config['agent']} not found, using ThinkingAgent")
            agent_model = Agent.objects.filter(name='ThinkingAgent').first()

        if not agent_model:
            raise ValueError("No suitable agent found")

        # Execute the agent
        # Session 922: Fix - use router.route() not execute_agent() (which doesn't exist)
        from core.agent_router import AgentRouter
        router = AgentRouter()

        result = router.route(
            agent_name=agent_model.name,
            task=prompt,
            context={
                'initiative_id': str(initiative_id),
                'stage': stage_num,
                'content_type': 'internal_document',
            },
            pre_gathered_context={
                'gathered': True,
                'spider_context': {},
                'scifi_context': {},
                'learning_context': {},
                'advisor_context': {},
                'feedback_context': {},
                'knowledge_context': {},
                'workspace_context': {},
                'docs_context': {},
                'user_context': {},
                'risk_context': {},
                'user_docs_context': {},
            },
        )

        # AgentResult has .success, .message, .data - not .get('response')
        if not result or not result.success or not result.message:
            raise ValueError(f"Agent returned empty response: {result.error if result else 'No result'}")

        # Session 1041: Use helper to extract real content from AgentResult.
        # Many agents put summaries in .message and actual content in .data.
        document_content = _extract_agent_content(result)

        # Create the document (Session 906: Use SelfBlog, not Document)
        # Map stage to category
        stage_category = {
            1: 'research_brief',
            2: 'prototype_plan',
            3: 'technical_document',  # Evaluation Protocol
            4: 'technical_document',  # Technical Design
            5: 'technical_document',  # Pilot Execution
        }
        document = SelfBlog.objects.create(
            title=f"{initiative.name} - Stage {stage_num}: {config['template']}",
            author='InitiativePipeline',  # Session 998: Author tracking
            intro=document_content[:500],  # First 500 chars as intro
            full_text=document_content,
            category=stage_category.get(stage_num, 'technical_document'),
            content_type='internal',  # Initiative stage docs are internal
            status='draft',
            initiative=initiative,
            initiative_stage=stage,
        )

        # Link document to stage
        stage.document = document
        stage.status = 'DRAFT'
        stage.save()

        # Session 1016: Post-generation semantic drift check
        try:
            from core.services.semantic_drift_detector import check_semantic_drift
            drift_result = check_semantic_drift(stage)
            if drift_result.get('has_drift'):
                drift_score = drift_result.get('drift_score', 0)
                drift_reason = drift_result.get('drift_reason', 'unknown')
                logger.warning(
                    f"[STAGE-GEN] Drift detected for Stage {stage_num} of "
                    f"'{initiative.name[:50]}': score={drift_score:.2f}, reason={drift_reason}"
                )
                stage.status = 'BLOCKED'
                stage.notes = (stage.notes or '') + f"\n[Drift detected] score={drift_score:.2f}: {drift_reason}"
                stage.save()
        except Exception as e:
            logger.debug(f"[STAGE-GEN] Drift check skipped: {e}")

        # Session 1058: Extract action items from stage document
        try:
            from core.services.action_item_parser import extract_action_items_from_stage
            extracted = extract_action_items_from_stage(str(stage.id))
            if extracted:
                logger.info(
                    f"[STAGE-GEN] Extracted {len(extracted)} action items "
                    f"from Stage {stage_num} of '{initiative.name[:50]}'"
                )
        except Exception as e:
            logger.warning(f"[STAGE-GEN] Action item extraction failed: {e}")

        # Session 994: Record activity when stage document is created
        initiative.update_activity()

        logger.info(f"[STAGE-GEN] Created document {document.id} for Stage {stage_num}")

        return {
            'success': True,
            'document_id': str(document.id),
            'stage': stage_num,
            'initiative_id': str(initiative_id),
            'initiative_name': initiative.name,
            'drift_checked': True,
        }

    except SoftTimeLimitExceeded:
        logger.error(
            f"📝 [STAGE-GEN] ⏰ Stage {stage_num} for '{initiative.name[:50]}' "
            f"timed out (10min soft limit)"
        )
        try:
            stage.status = 'PENDING'
            stage.notes = (stage.notes or '') + f"\n[Timeout] Generation exceeded 10 minute limit"
            stage.save()
        except Exception:
            pass
        return {'success': False, 'error': f'Stage {stage_num} generation timed out (600s)'}

    except Exception as e:
        logger.error(f"📝 [STAGE-GEN] ❌ Error generating Stage {stage_num}: {e}")
        stage.status = 'PENDING'  # Reset to pending for retry
        stage.save()
        raise self.retry(exc=e, countdown=300)


# =============================================================================
# Session 915: Backfill Stage Documents Task
# =============================================================================

@shared_task(bind=True, queue='default')
def backfill_stage_documents(self, stage_num: int = 1, limit: int = 50):
    """
    Session 915: Backfill missing stage documents for existing initiatives.

    This task runs within the Celery worker context and triggers document
    generation for initiatives that have stages without documents.

    Args:
        stage_num: Which stage to backfill (default: 1)
        limit: Maximum number of initiatives to process (default: 50)

    Returns:
        Dict with triggered count and any errors
    """
    from core.models_document_registry import Initiative, InitiativeStage

    logger.info(f"[Session 915] 📚 Starting Stage {stage_num} document backfill (limit: {limit})")

    try:
        # Find initiatives where the stage exists but has no document
        all_initiatives = Initiative.objects.filter(
            current_stage__gte=stage_num
        ).order_by('-created_at')[:limit * 2]

        initiatives_to_backfill = []
        for initiative in all_initiatives:
            stage = InitiativeStage.objects.filter(
                initiative=initiative,
                stage=stage_num
            ).first()

            if stage and not stage.document:
                initiatives_to_backfill.append(initiative)

            if len(initiatives_to_backfill) >= limit:
                break

        logger.info(f"[Session 915] Found {len(initiatives_to_backfill)} initiatives missing Stage {stage_num} documents")

        triggered = 0
        errors = 0

        for initiative in initiatives_to_backfill:
            try:
                # Trigger document generation for this initiative
                generate_initiative_stage_document.delay(str(initiative.id), stage_num)
                triggered += 1
                logger.info(f"[Session 915] 🚀 Triggered: {initiative.name[:50]}...")
            except Exception as e:
                errors += 1
                logger.error(f"[Session 915] ❌ Error triggering for {initiative.name[:50]}: {e}")

        result = {
            'success': True,
            'stage': stage_num,
            'found': len(initiatives_to_backfill),
            'triggered': triggered,
            'errors': errors
        }

        logger.info(f"[Session 915] ✅ Backfill complete: {triggered} triggered, {errors} errors")

        return result

    except Exception as e:
        logger.error(f"[Session 915] ❌ Backfill failed: {e}")
        return {'success': False, 'error': str(e)}


