# =============================================================================
# Session 926: Audio Cache Cleanup for Universal Agent Voice System
# =============================================================================

@shared_task
def cleanup_audio_cache():
    """
    Session 926: Clean up old audio cache entries to manage storage.

    Eviction policy:
    - Entries older than 30 days with access_count < 5 are deleted
    - Tracks cache hit rate for monitoring

    Scheduled: Daily at 3:00 AM
    """
    from django.utils import timezone
    from datetime import timedelta
    from django.db.models import Sum

    logger.info("[Session 926] 🧹 Starting audio cache cleanup...")

    try:
        from core.models_audio_cache import AudioCache

        # Calculate cutoff date
        cutoff_date = timezone.now() - timedelta(days=30)

        # Get stats before cleanup
        total_entries = AudioCache.objects.count()
        total_size = AudioCache.objects.aggregate(
            total=Sum('file_size_bytes')
        )['total'] or 0
        total_accesses = AudioCache.objects.aggregate(
            total=Sum('access_count')
        )['total'] or 0

        # Find entries to evict: older than 30 days AND accessed fewer than 5 times
        entries_to_delete = AudioCache.objects.filter(
            created_at__lt=cutoff_date,
            access_count__lt=5
        )

        delete_count = entries_to_delete.count()
        delete_size = entries_to_delete.aggregate(
            total=Sum('file_size_bytes')
        )['total'] or 0

        # Delete the files and entries
        for entry in entries_to_delete:
            try:
                if entry.audio_file:
                    entry.audio_file.delete(save=False)
            except Exception as e:
                logger.warning(f"[Session 926] Could not delete file for {entry.id}: {e}")

        entries_to_delete.delete()

        # Calculate cache hit rate (accesses / entries is a rough proxy)
        hit_rate = (total_accesses / total_entries * 100) if total_entries > 0 else 0

        logger.info(
            f"[Session 926] ✅ Audio cache cleanup complete: "
            f"Deleted={delete_count} entries ({delete_size / (1024*1024):.2f} MB), "
            f"Remaining={total_entries - delete_count} entries, "
            f"Hit rate proxy={hit_rate:.1f}%"
        )

        return {
            'success': True,
            'deleted_count': delete_count,
            'deleted_size_bytes': delete_size,
            'remaining_count': total_entries - delete_count,
            'remaining_size_bytes': total_size - delete_size,
            'hit_rate_proxy': round(hit_rate, 2),
        }

    except Exception as e:
        logger.error(f"[Session 926] ❌ Audio cache cleanup failed: {e}")
        return {'success': False, 'error': str(e)}


# =============================================================================
# SESSION 974b: ASYNC PA CHAT PROCESSING
# =============================================================================

@shared_task(bind=True, time_limit=300, soft_time_limit=280)
def process_pa_chat_task(self, user_id, message, context=None, generate_audio=False, conversation_id=None, source='web', platform='web'):
    """
    Session 974b: Async PA chat processing to avoid Railway proxy timeouts.
    Runs UnifiedPAEntrypoint in Celery worker, stores result in Redis via Celery result backend.
    """
    import asyncio
    from django.contrib.auth import get_user_model

    User = get_user_model()
    user = User.objects.get(id=user_id)

    # Session 1085: Resolve conversation_id BEFORE PA init so history is scoped
    from core.models import ChatConversation
    if not conversation_id:
        conversation_id, _ = ChatConversation.get_or_create_session(user=user, platform=platform)

    # Session 1068: Create fresh PA instance per task instead of caching.
    from core.services.unified_pa_entrypoint import UnifiedPAEntrypoint
    pa = UnifiedPAEntrypoint(user, conversation_id=conversation_id)

    start_ms = time.time()
    # Session 976: Run async PA in a fresh event loop to avoid deadlock
    # in Celery's --pool=threads worker. async_to_sync and asyncio.run()
    # can both fail if an event loop already exists in the thread.
    loop = asyncio.new_event_loop()
    try:
        response = loop.run_until_complete(pa.process_message(
            message=message,
            context=context or {},
            generate_audio=generate_audio
        ))
    finally:
        loop.close()
    elapsed_ms = int((time.time() - start_ms) * 1000)

    # Persist to ChatConversation (same logic as the former sync view)
    try:
        is_first = not ChatConversation.objects.filter(conversation_id=conversation_id).exists()

        # Session 1063: Sanitize metadata — tool results may contain UUIDs,
        # datetimes, or other non-JSON-serializable objects from agent execution.
        raw_metadata = {
            'trace_id': response.trace_id,
            'intent': response.intent,
            'routed_to': response.routed_to,
            # Session 1036: Persist function calling metadata for multi-turn context
            'tool_calls': response.tool_call_metadata or [],
            'tool_results': response.tool_result_data or [],
            'response_id': response.response_id,
            'source': source,
        }
        metadata = json.loads(json.dumps(raw_metadata, default=str))

        chat_row = ChatConversation.objects.create(
            user=user,
            conversation_id=conversation_id,
            user_message=message,
            assistant_response=response.content or '',
            platform=platform,
            source=source,  # Session 1074: Collaboration protocol actor tracking
            metadata=metadata,
            response_time_ms=response.latency_ms or elapsed_ms,
            agents_used=[r.get('tool', '') for r in (response.tool_runs or [])],
        )

        if is_first:
            chat_row.generate_session_title()
    except Exception as persist_err:
        logger.warning(f"Failed to persist PA conversation: {persist_err}")

    return {
        'success': True,
        'content': response.content,
        'trace_id': response.trace_id,
        'tool_runs': response.tool_runs,
        'audio_url': response.audio_url,
        'intent': response.intent,
        'routed_to': response.routed_to,
        'profile_completeness': response.profile_completeness,
        'latency_ms': response.latency_ms,
        'error': response.error,
        'conversation_id': conversation_id,
    }


# =============================================================================
# Learning Journey Content Generation (Session 988)
# =============================================================================

@shared_task(bind=True, time_limit=120, soft_time_limit=100)
def generate_step_content(self, step_id):
    """Generate AI content for a learning journey step."""
    from core.models_learning_journey import LearningJourneyStep
    from core.llm_enforcer import LLMEnforcer

    try:
        step = LearningJourneyStep.objects.select_related('journey').get(id=step_id)
    except LearningJourneyStep.DoesNotExist:
        logger.error(f"generate_step_content: step {step_id} not found")
        return {'success': False, 'error': 'Step not found'}

    if step.content:
        return {'success': True, 'already_generated': True}

    journey = step.journey
    step_type = step.step_type or 'lesson'
    meta = step.content_meta or {}

    # Build prompt based on step type
    base_context = (
        f"Journey: {journey.title}\n"
        f"Journey description: {journey.description}\n"
        f"Step {step.step_number} of {journey.total_steps}: {step.title}\n"
        f"Step description: {step.description}\n"
    )

    if step_type == 'lesson':
        prompt = (
            f"You are a helpful AI tutor inside an AI platform called AI Studio. "
            f"Write a concise, engaging lesson in markdown.\n\n"
            f"{base_context}\n"
            f"Write 3-5 paragraphs explaining the key concepts. "
            f"Use headers (##), bullet points, and bold text for emphasis. "
            f"Include a 'Key Takeaways' section at the end with 3 bullet points. "
            f"Keep the tone friendly and practical."
        )
    elif step_type == 'exercise':
        suggested = meta.get('suggested_prompts', [])
        prompts_text = '\n'.join(f'- {p}' for p in suggested) if suggested else ''
        prompt = (
            f"You are a helpful AI tutor inside an AI platform called AI Studio. "
            f"Write a brief exercise introduction in markdown.\n\n"
            f"{base_context}\n"
            f"Write 2-3 paragraphs explaining what the user will practice. "
            f"If these prompts are provided, reference them naturally:\n{prompts_text}\n\n"
            f"End with a '## Try It Out' section encouraging the user to click the prompt chips below "
            f"to open the Personal Assistant and try each prompt. "
            f"Keep it brief and action-oriented."
        )
    else:  # explore
        nav_hints = meta.get('navigation_hints', [])
        hints_text = '\n'.join(f'- {h}' for h in nav_hints) if nav_hints else ''
        prompt = (
            f"You are a helpful AI tutor inside an AI platform called AI Studio. "
            f"Write a brief exploration guide in markdown.\n\n"
            f"{base_context}\n"
            f"Write 2-3 paragraphs explaining what the user should explore and what to look for. "
            f"Reference these platform areas if provided:\n{hints_text}\n\n"
            f"End with a '## Explore Now' section encouraging the user to click the navigation buttons below. "
            f"Keep it brief and discovery-oriented."
        )

    try:
        enforcer = LLMEnforcer()
        result = enforcer.enforce_real_ai(
            prompt=prompt,
            agent_name='LearningContentGenerator',
            max_tokens=1500,
        )
        content = result.get('content', '') or result.get('response', '')
        if content:
            step.content = content
            step.save(update_fields=['content'])
            logger.info(f"Generated content for step {step_id} ({step_type})")
            return {'success': True, 'step_id': str(step_id)}
        else:
            logger.warning(f"Empty content for step {step_id}: {result}")
            return {'success': False, 'error': 'Empty content from LLM'}
    except Exception as e:
        logger.error(f"generate_step_content failed for {step_id}: {e}")
        return {'success': False, 'error': str(e)}


