# =============================================================================
# Session 1031: Surface Top Dreams to Boardroom
# =============================================================================

@shared_task
def surface_top_dreams(max_items=5, min_composite=0.85):
    """Surface top-scoring dreams as HumanAttentionItems for user review.

    Queries promoted dreams that haven't been shown to the user yet,
    deduplicates against existing attention items, caps per-agent diversity,
    and creates boardroom items so users can approve/reject via PA or UI.
    """
    from django.utils import timezone
    from django.contrib.auth import get_user_model
    from core.models_unified_system import AgentDream
    from core.models_human_interface import HumanAttentionItem

    User = get_user_model()
    user = User.objects.filter(is_superuser=True).first()
    if not user:
        logger.warning("[DREAM-SURFACE] No superuser found — cannot create attention items")
        return {'surfaced': 0, 'reason': 'no_superuser'}

    dreams = (
        AgentDream.objects
        .filter(
            promoted_to_decision=True,
            decision_outcome='pending',
            shown_to_user=False,
            origin__in=['serious', 'speculative'],
            composite_score__gte=min_composite,
        )
        .select_related('agent')
        .order_by('-composite_score', '-dreamed_at')[:50]
    )

    agent_counts = {}
    created = 0

    for dream in dreams:
        if created >= max_items:
            break

        agent_name = dream.agent.name if dream.agent else 'Unknown'

        # Diversity cap: max 2 per agent
        if agent_counts.get(agent_name, 0) >= 2:
            continue

        # Dedup: skip if already surfaced
        if HumanAttentionItem.objects.filter(
            source_type='dream_pipeline',
            source_id=str(dream.id),
        ).exists():
            continue

        summary = (
            f"{dream.content[:300]}... "
            f"(Agent: {agent_name}, Score: {dream.composite_score:.2f})"
        ) if len(dream.content) > 300 else (
            f"{dream.content} "
            f"(Agent: {agent_name}, Score: {dream.composite_score:.2f})"
        )

        HumanAttentionItem.objects.create(
            user=user,
            source_type='dream_pipeline',
            source_id=str(dream.id),
            source_agent=agent_name,
            item_type='decision',
            urgency='low',
            title=f"Dream: {dream.title[:150]}",
            summary=summary,
            payload={
                'dream_id': str(dream.id),
                'dream_type': dream.dream_type,
                'agent_name': agent_name,
                'composite_score': dream.composite_score,
                'creativity_score': dream.creativity_score,
                'actionability_score': dream.actionability_score,
                'relevance_score': dream.relevance_score,
            },
        )

        dream.shown_to_user = True
        dream.shown_at = timezone.now()
        dream.save(update_fields=['shown_to_user', 'shown_at'])

        agent_counts[agent_name] = agent_counts.get(agent_name, 0) + 1
        created += 1

    logger.info(f"[DREAM-SURFACE] Surfaced {created} dreams as attention items")
    return {'surfaced': created}


@shared_task(name='core.tasks.cleanup_conversation_duplicates_task', bind=True, max_retries=0)
def cleanup_conversation_duplicates_task(self):
    """
    Session 1032: Daily cleanup of fuzzy-duplicate AgentConversation records.
    Uses Jaccard similarity to cluster conversations and delete lower-quality duplicates.
    """
    from core.services.deduplication_service import get_deduplication_service

    dedup_svc = get_deduplication_service()
    result = dedup_svc.cleanup_fuzzy_conversation_duplicates(dry_run=False, hours=168)

    logger.info(
        f"[CONVERSATION-DEDUP] Cleaned {result['records_deleted']} duplicates "
        f"from {result['clusters_found']} clusters"
    )
    return result


@shared_task(name='core.tasks.rescan_active_workspaces')
def rescan_active_workspaces(stale_days: int = 7):
    """
    Session 1055: Periodic rescan of active workspaces with stale or missing context.
    Keeps WorkspaceContext fresh so PA workspace injection stays accurate.
    """
    from core.models_skin_layer import ProjectWorkspace, WorkspaceContext
    from core.services.workspace_manager import WorkspaceScanner

    cutoff = timezone.now() - timedelta(days=stale_days)
    scanner = WorkspaceScanner()
    rescanned = 0
    errors = 0

    active_workspaces = ProjectWorkspace.objects.filter(is_active=True)

    for ws in active_workspaces:
        try:
            ctx = WorkspaceContext.objects.filter(workspace=ws).first()
            if ctx and ctx.updated_at and ctx.updated_at > cutoff:
                continue  # Still fresh
            scanner.scan_workspace(ws)
            rescanned += 1
        except Exception as e:
            errors += 1
            logger.warning(f"[WORKSPACE-RESCAN] Failed to rescan {ws.name}: {e}")

    logger.info(
        f"[WORKSPACE-RESCAN] Rescanned {rescanned} workspaces, "
        f"{errors} errors, {active_workspaces.count()} total active"
    )
    return {'rescanned': rescanned, 'errors': errors}


# --------------------------------------------------------------------------- #
# PA Tool Learning Loop                                                        #
# Mines ToolCallRecord for patterns and creates PAToolInsight candidates.       #
# --------------------------------------------------------------------------- #

@shared_task(ignore_result=True)
def analyze_pa_tool_patterns():
    """
    Mine last 24h of ToolCallRecord for PA tool-call patterns.

    Detects 4 pattern types:
    - param_correction: same tool retried in same conversation with different
      params after a failure → first failed, second succeeded
    - error_pattern: same tool + param combo fails >3 times across conversations
    - success_pattern: specific param combos with >80% success rate and >5 uses
    - follow_up: tool B consistently called within 60s after tool A succeeds
    """
    from core.models_tool_calls import ToolCallRecord, PAToolInsight
    from django.db.models import Count, Q, Avg
    import hashlib as _hl

    cutoff = timezone.now() - timedelta(hours=24)
    records = ToolCallRecord.objects.filter(
        created_at__gte=cutoff,
        agent_name='PersonalAssistant',
    )
    total = records.count()
    if total < 5:
        logger.info("[PA-LEARNING] <5 PA tool calls in last 24h, skipping")
        return {'status': 'skipped', 'reason': 'insufficient_data', 'records': total}

    created = 0
    updated = 0

    # --- 1. param_correction: retry-in-conversation pattern ---
    conv_ids = (
        records.filter(conversation_id__isnull=False)
        .values_list('conversation_id', flat=True)
        .distinct()
    )
    for conv_id in conv_ids:
        conv_calls = list(
            records.filter(conversation_id=conv_id)
            .order_by('created_at')
            .values('tool_name', 'parameters', 'success', 'error_message')
        )
        # Look for fail → success pairs on same tool
        failed = {}
        for call in conv_calls:
            tn = call['tool_name']
            if not call['success']:
                failed[tn] = call
            elif tn in failed and call['success']:
                fail_params = failed.pop(tn)
                if call['parameters'] != fail_params['parameters']:
                    pattern_key = json.dumps(
                        {'tool': tn, 'bad': fail_params['parameters'], 'good': call['parameters']},
                        sort_keys=True, default=str,
                    )
                    pattern_hash = _hl.md5(pattern_key.encode()).hexdigest()
                    pattern = {
                        'hash': pattern_hash,
                        'bad_params': fail_params['parameters'],
                        'good_params': call['parameters'],
                        'error': fail_params.get('error_message', ''),
                    }
                    snippet = (
                        f"When using {tn}, prefer {_summarize_diff(fail_params['parameters'], call['parameters'])}. "
                        f"Previous error: {fail_params.get('error_message', 'unknown')[:120]}"
                    )
                    c, u = _upsert_insight(tn, 'param_correction', pattern, snippet)
                    created += c
                    updated += u

    # --- 2. error_pattern: repeated failures ---
    error_groups = (
        records.filter(success=False)
        .values('tool_name', 'error_message')
        .annotate(cnt=Count('id'))
        .filter(cnt__gt=3)
    )
    for eg in error_groups:
        pattern = {'error': eg['error_message'][:500]}
        snippet = (
            f"Known error: {eg['error_message'][:200]}. "
            f"Occurred {eg['cnt']} times in 24h — double-check parameters."
        )
        c, u = _upsert_insight(eg['tool_name'], 'error_pattern', pattern, snippet)
        created += c
        updated += u

    # --- 3. success_pattern: high-success param combos ---
    tool_param_groups = (
        records.values('tool_name', 'parameters')
        .annotate(
            total=Count('id'),
            successes=Count('id', filter=Q(success=True)),
        )
        .filter(total__gt=5)
    )
    for tpg in tool_param_groups:
        rate = tpg['successes'] / tpg['total']
        if rate >= 0.8:
            params = tpg['parameters']
            if not params:
                continue
            pattern = {'params': params}
            snippet = (
                f"Reliable combo ({rate:.0%} success over {tpg['total']} calls): "
                f"{_summarize_params(params)}"
            )
            c, u = _upsert_insight(tpg['tool_name'], 'success_pattern', pattern, snippet, confidence=rate)
            created += c
            updated += u

    # --- 4. follow_up: tool B after tool A ---
    conv_ids_list = list(conv_ids[:100])  # cap to avoid huge loops
    pair_counts: dict = {}
    for conv_id in conv_ids_list:
        calls = list(
            records.filter(conversation_id=conv_id, success=True)
            .order_by('created_at')
            .values('tool_name', 'created_at')
        )
        for i in range(len(calls) - 1):
            a, b = calls[i], calls[i + 1]
            delta = (b['created_at'] - a['created_at']).total_seconds()
            if delta <= 60 and a['tool_name'] != b['tool_name']:
                key = (a['tool_name'], b['tool_name'])
                pair_counts[key] = pair_counts.get(key, 0) + 1

    for (tool_a, tool_b), count in pair_counts.items():
        if count >= 3:
            pattern = {'after': tool_a, 'then': tool_b}
            snippet = f"Users often call {tool_b} right after {tool_a} — consider suggesting it."
            conf = min(count / 10, 1.0)
            c, u = _upsert_insight(tool_a, 'follow_up', pattern, snippet, confidence=conf)
            created += c
            updated += u

    # --- 5. consistency_check: same tool+params → contradictory outcomes ---
    tool_param_all = (
        records.values('tool_name', 'parameters')
        .annotate(
            total=Count('id'),
            successes=Count('id', filter=Q(success=True)),
            failures=Count('id', filter=Q(success=False)),
        )
        .filter(total__gte=3)
    )
    for tpa in tool_param_all:
        s, f = tpa['successes'], tpa['failures']
        if s > 0 and f > 0:
            rate = s / tpa['total']
            if 0.30 <= rate <= 0.70:
                params = tpa['parameters']
                if not params:
                    continue
                pattern = {'params': params, 'success_rate': round(rate, 2)}
                snippet = (
                    f"Inconsistent results ({rate:.0%} success over {tpa['total']} calls) "
                    f"with params: {_summarize_params(params)}. Needs investigation."
                )
                c, u = _upsert_insight(
                    tpa['tool_name'], 'consistency_check', pattern, snippet, confidence=rate,
                )
                created += c
                updated += u

    logger.info(
        f"[PA-LEARNING] Analyzed {total} records: "
        f"{created} new insights, {updated} updated"
    )
    return {'status': 'ok', 'records': total, 'created': created, 'updated': updated}


def _ttl_days(insight_type):
    """Return TTL in days by insight type."""
    return {
        'error_pattern': 14,
        'param_correction': 30,
        'success_pattern': 60,
        'follow_up': 90,
        'consistency_check': 7,
    }.get(insight_type, 30)


def _upsert_insight(tool_name, insight_type, pattern, snippet, confidence=None):
    """Create or update a PAToolInsight. Returns (created_count, updated_count)."""
    from core.models_tool_calls import PAToolInsight

    pattern_json = json.dumps(pattern, sort_keys=True, default=str)

    existing = PAToolInsight.objects.filter(
        tool_name=tool_name,
        insight_type=insight_type,
        pattern=pattern,
    ).first()

    ttl = timedelta(days=_ttl_days(insight_type))

    if existing:
        existing.evidence_count = F('evidence_count') + 1
        existing.expires_at = timezone.now() + ttl  # refresh TTL on evidence bump
        update_fields = ['evidence_count', 'expires_at', 'updated_at']
        if confidence is not None:
            existing.confidence = confidence
            update_fields.append('confidence')
        # Auto-promote: evidence >= 5 and confidence >= 0.8
        # Block auto-promotion for consistency_check (human review only)
        if confidence and confidence >= 0.8 and insight_type != 'consistency_check':
            existing.refresh_from_db()
            if existing.evidence_count >= 4 and existing.safety_class == 'candidate':
                existing.safety_class = 'approved'
                update_fields.append('safety_class')
                logger.info(f"[PA-LEARNING] Auto-promoted: {tool_name}/{insight_type}")
        existing.save(update_fields=update_fields)
        return (0, 1)
    else:
        PAToolInsight.objects.create(
            tool_name=tool_name,
            insight_type=insight_type,
            pattern=pattern,
            prompt_snippet=snippet,
            evidence_count=1,
            confidence=confidence or 0.0,
            expires_at=timezone.now() + ttl,
        )
        return (1, 0)


def _summarize_params(params: dict) -> str:
    """Compact param summary for prompt snippets."""
    parts = []
    for k, v in list(params.items())[:4]:
        val = str(v)[:40]
        parts.append(f"{k}={val}")
    suffix = f" (+{len(params) - 4} more)" if len(params) > 4 else ""
    return ", ".join(parts) + suffix


def _summarize_diff(bad: dict, good: dict) -> str:
    """Summarize what changed between bad and good params."""
    changes = []
    for k in set(list(bad.keys()) + list(good.keys())):
        bv, gv = bad.get(k), good.get(k)
        if bv != gv:
            changes.append(f"{k}: '{gv}' (not '{bv}')")
    return "; ".join(changes[:3]) if changes else "different parameters"


@shared_task(ignore_result=True)
def cleanup_expired_pa_insights():
    """Demote expired approved insights back to candidate (daily 3 AM)."""
    from core.models_tool_calls import PAToolInsight

    now = timezone.now()
    demoted = PAToolInsight.objects.filter(
        safety_class='approved',
        expires_at__isnull=False,
        expires_at__lte=now,
    ).update(safety_class='candidate')

    if demoted:
        logger.info(f"[PA-LEARNING] Demoted {demoted} expired insights → candidate")
    return {'demoted': demoted}


# =============================================================================
# SESSION G2: DATA RETENTION JOB
# =============================================================================

# Retention rules: days before archive/delete by sensitivity level
_RETENTION_DAYS = {
    'restricted': 7,
    'confidential': 30,
    'internal': 90,
    'public': 365,
}


@shared_task(ignore_result=True)
def enforce_data_retention():
    """Nightly job: archive/delete artifacts by data_sensitivity + age.

    - Pinned items (is_pinned=True) are always skipped.
    - Deliverables: status → 'archived'
    - Documents: status → 'archived'
    """
    from core.models_deliverables import Deliverable
    from content.models import Document

    now = timezone.now()
    stats = {'deliverables_archived': 0, 'documents_archived': 0}

    for sensitivity, max_days in _RETENTION_DAYS.items():
        cutoff = now - timezone.timedelta(days=max_days)

        # Archive old deliverables (skip pinned)
        d_count = Deliverable.objects.filter(
            data_sensitivity=sensitivity,
            is_pinned=False,
            created_at__lt=cutoff,
            status__in=['draft', 'ready', 'published'],
        ).update(status='archived')
        stats['deliverables_archived'] += d_count

        # Archive old documents (skip pinned)
        doc_count = Document.objects.filter(
            data_sensitivity=sensitivity,
            is_pinned=False,
            created_at__lt=cutoff,
        ).exclude(
            status__in=['archived', 'deleted'],
        ).update(status='archived')
        stats['documents_archived'] += doc_count

    total = stats['deliverables_archived'] + stats['documents_archived']
    if total:
        logger.info(
            f"[RETENTION] Archived {stats['deliverables_archived']} deliverables, "
            f"{stats['documents_archived']} documents"
        )
    return stats


# =============================================================================
# SESSION G1: COMPETITOR COMPARISON GENERATION TASK
# =============================================================================

def _run_comparison_generation(comparison, source_document_id=None,
                                competitor_name='', focus_areas=None):
    """
    Core comparison generation logic — called by the Celery task wrapper
    and by the source_pack_workflow.

    Returns dict with comparison result or raises on failure.
    """
    import traceback
    from django.utils import timezone as tz
    from core.services.data_scrubber import scrub
    from content.embeddings import rag_system

    start_time = time.time()

    queries = [
        f"what is {competitor_name} what did they build",
        "workflow steps process pipeline",
        "security architecture protection",
        "cost tokens caching model pricing",
        "logging monitoring observability",
        "scheduling automation cron jobs",
        "integrations tools stack CRM email",
        "knowledge base search memory RAG",
    ]
    if focus_areas:
        queries.extend(focus_areas if isinstance(focus_areas, list) else [focus_areas])

    all_chunks = []
    seen_keys = set()
    source_docs = {}  # document_id -> {title, source_type}
    for q in queries:
        results = rag_system.semantic_search_sync(
            query=q,
            limit=8,
            similarity_threshold=0.25,
        )
        for r in results:
            # Filter to source document if specified
            if source_document_id and r.document_id != str(source_document_id):
                continue
            key = (r.document_id, r.chunk_index)
            if key not in seen_keys:
                seen_keys.add(key)
                # Scrub evidence text before storing
                chunk_text = scrub(r.chunk_text[:1500])
                chunk_id = f"E{len(all_chunks) + 1}"
                all_chunks.append({
                    'chunk_id': chunk_id,
                    'document_id': r.document_id,
                    'document_title': r.document_title,
                    'chunk_index': r.chunk_index,
                    'chunk_text': chunk_text,
                    'similarity_score': round(r.similarity_score, 4),
                })
                # Track unique source documents
                if r.document_id not in source_docs:
                    source_docs[r.document_id] = {
                        'document_id': r.document_id,
                        'title': r.document_title,
                        'source_type': getattr(r, 'document_type', 'unknown'),
                    }

    logger.info(f"[COMPETITOR] Collected {len(all_chunks)} chunks from {len(source_docs)} sources for '{competitor_name}'")

    # --- Insufficient evidence check ---
    if not all_chunks:
        comparison.status = 'needs_sources'
        comparison.error_message = 'No evidence chunks found — ingest a document about this competitor first.'
        comparison.metadata = {
            'recommended_queries': [
                f"{competitor_name} overview features",
                f"{competitor_name} architecture tech stack",
                f"{competitor_name} pricing plans",
            ],
        }
        comparison.save(update_fields=['status', 'error_message', 'metadata', 'updated_at'])
        return {'status': 'needs_sources', 'message': comparison.error_message}

    if len(all_chunks) < 5:
        comparison.status = 'needs_sources'
        comparison.error_message = (
            f'Only {len(all_chunks)} evidence chunks found — need at least 5 for a quality comparison. '
            f'Ingest more documents about {competitor_name}.'
        )
        comparison.metadata = {
            'evidence_found': len(all_chunks),
            'recommended_queries': [
                f"{competitor_name} detailed review",
                f"{competitor_name} vs alternatives",
                f"{competitor_name} security architecture",
            ],
        }
        comparison.save(update_fields=['status', 'error_message', 'metadata', 'updated_at'])
        return {'status': 'needs_sources', 'message': comparison.error_message}

    # --- 2. Build prompt + call LLM ---
    # Build chunk reference table for evidence_refs
    chunk_ref_table = "\n".join(
        f"[{c['chunk_id']}] (sim={c['similarity_score']}) {c['chunk_text'][:120]}..."
        for c in sorted(all_chunks, key=lambda x: -x['similarity_score'])[:40]
    )
    evidence_text = "\n\n".join(
        f"[{c['chunk_id']} | {c['document_title']} | sim={c['similarity_score']}]\n{c['chunk_text']}"
        for c in sorted(all_chunks, key=lambda x: -x['similarity_score'])[:40]
    )

    system_prompt = (
        "You are a competitive intelligence analyst. Given evidence chunks from documents "
        "about a competitor, produce a structured JSON comparison between the competitor's "
        "platform and our platform (Donkey Betz / AI Studio). Be specific, evidence-based, "
        "and cite chunk IDs (e.g. E1, E5) to support every claim."
    )

    user_prompt = f"""Analyze the following evidence about **{competitor_name}** and produce a JSON object with exactly these 7 keys:

1. "review" — object with:
   - "features": list of objects with "name", "description", "evidence_quote", "evidence_refs" (list of chunk IDs like ["E1", "E5"])
   - "architecture_summary": string

2. "comparison_table" — list of objects with:
   - "category", "competitor" (what they have), "donkey_betz" (what we have)
   - "verdict": "ahead" / "behind" / "even" / "gap"
   - "evidence_refs": list of chunk IDs supporting this row

3. "gap_backlog" — list of objects with:
   - "gap" (string), "priority" ("P0"/"P1"/"P2")
   - "acceptance_test" (string — how we'd know the gap is closed)
   - "effort": "S" / "M" / "L"
   - "impact": "high" / "medium" / "low"
   - "evidence_refs": list of chunk IDs

4. "tools_stack" — object with "languages" (list), "frameworks" (list), "services" (list), "apis" (list)

5. "summary" — 2-3 sentence executive summary

6. "verdict" — overall: "ahead" / "behind" / "parity"

7. "quick_wins" — list of 3 gaps that could be closed in 1-2 weeks (subset of gap_backlog, effort="S")

AVAILABLE CHUNK IDs:
{chunk_ref_table}

FULL EVIDENCE CHUNKS:
{evidence_text}

Respond ONLY with valid JSON, no markdown fences."""

    import openai as openai_mod
    from django.conf import settings as django_settings

    client = openai_mod.OpenAI(api_key=django_settings.AI_PROVIDERS.get('OPENAI_API_KEY'))
    llm_response = client.chat.completions.create(
        model='gpt-4.1',
        messages=[
            {'role': 'system', 'content': system_prompt},
            {'role': 'user', 'content': user_prompt},
        ],
        max_tokens=6000,
        temperature=0.3,
    )

    raw_text = llm_response.choices[0].message.content.strip()
    tokens_used = {
        'prompt_tokens': llm_response.usage.prompt_tokens if llm_response.usage else 0,
        'completion_tokens': llm_response.usage.completion_tokens if llm_response.usage else 0,
    }

    # --- 3. Parse JSON ---
    if raw_text.startswith('```'):
        raw_text = raw_text.split('\n', 1)[1] if '\n' in raw_text else raw_text[3:]
        if raw_text.endswith('```'):
            raw_text = raw_text[:-3]

    parsed = json.loads(raw_text)

    # --- 4. Compute quality rubric ---
    comparison_table = parsed.get('comparison_table', [])
    gap_backlog = parsed.get('gap_backlog', [])
    review = parsed.get('review', {})

    # Evidence coverage: % of comparison_table rows with evidence_refs
    rows_with_refs = sum(1 for row in comparison_table if row.get('evidence_refs'))
    total_rows = len(comparison_table) if comparison_table else 1
    evidence_coverage = round(rows_with_refs / total_rows, 3)

    # Source diversity: how many unique source documents contributed
    unique_sources = len(source_docs)
    source_diversity = min(1.0, unique_sources / 5.0)  # 5+ sources = perfect

    # Uncited penalty: features without evidence_refs
    features = review.get('features', [])
    features_with_refs = sum(1 for f in features if f.get('evidence_refs'))
    uncited_penalty = 1.0 - (features_with_refs / max(len(features), 1))

    # Composite quality score
    quality_score = round(min(1.0, (
        evidence_coverage * 0.5 +
        source_diversity * 0.2 +
        (1.0 - uncited_penalty) * 0.3
    )), 3)

    quality_rubric = {
        'evidence_coverage': evidence_coverage,
        'source_diversity': round(source_diversity, 3),
        'uncited_penalty': round(uncited_penalty, 3),
        'unique_sources': unique_sources,
        'total_evidence_chunks': len(all_chunks),
        'rows_with_refs': rows_with_refs,
        'total_rows': total_rows,
        'features_cited': features_with_refs,
        'features_total': len(features),
    }

    # --- 5. Build executive summary ---
    verdict = parsed.get('verdict', 'parity')
    quick_wins = parsed.get('quick_wins', [])

    # Count verdicts
    verdict_counts = {}
    for row in comparison_table:
        v = row.get('verdict', 'even')
        verdict_counts[v] = verdict_counts.get(v, 0) + 1

    top_advantages = [
        row['category'] for row in comparison_table
        if row.get('verdict') == 'ahead'
    ][:3]
    top_gaps = [
        row['category'] for row in comparison_table
        if row.get('verdict') in ('behind', 'gap')
    ][:3]

    executive_summary = {
        'verdict': verdict,
        'verdict_counts': verdict_counts,
        'top_advantages': top_advantages,
        'top_gaps': top_gaps,
        'quick_wins': quick_wins[:3],
        'gap_count': len(gap_backlog),
        'p0_gaps': sum(1 for g in gap_backlog if g.get('priority') == 'P0'),
        'p1_gaps': sum(1 for g in gap_backlog if g.get('priority') == 'P1'),
        'p2_gaps': sum(1 for g in gap_backlog if g.get('priority') == 'P2'),
        'confidence': 'high' if quality_score >= 0.7 else 'medium' if quality_score >= 0.4 else 'low',
    }

    # --- 6. Save enriched artifact ---
    elapsed = round(time.time() - start_time, 2)
    comparison.review_json = review
    comparison.comparison_table_json = comparison_table
    comparison.gap_backlog_json = gap_backlog
    comparison.tools_stack_json = parsed.get('tools_stack', {})
    comparison.evidence_json = all_chunks
    comparison.sources_json = list(source_docs.values())
    comparison.executive_summary_json = executive_summary
    comparison.quality_rubric_json = quality_rubric
    comparison.summary = parsed.get('summary', '')
    comparison.quality_score = quality_score
    comparison.status = 'complete'
    comparison.completed_at = tz.now()
    comparison.metadata = {
        'tokens': tokens_used,
        'evidence_chunks': len(all_chunks),
        'elapsed_seconds': elapsed,
        'queries_run': len(queries),
        'evidence_coverage_pct': round(evidence_coverage * 100, 1),
        'uncited_claims': total_rows - rows_with_refs,
        'source_count': unique_sources,
        'model': 'gpt-4.1',
    }
    comparison.save()

    logger.info(
        f"[COMPETITOR] Comparison '{competitor_name}' complete in {elapsed}s "
        f"| quality={quality_score} | {len(all_chunks)} chunks from {unique_sources} sources"
    )
    return {
        'comparison_id': str(comparison.id),
        'status': 'complete',
        'quality_score': quality_score,
        'verdict': verdict,
        'summary': comparison.summary[:200],
    }


@shared_task(bind=True, soft_time_limit=300, time_limit=360)
def generate_competitor_comparison_task(self, comparison_id, source_document_id=None,
                                        competitor_name='', focus_areas=None):
    """
    Generate a structured competitor comparison from RAG evidence + LLM.
    Thin wrapper around _run_comparison_generation().
    """
    import traceback
    from core.models_competitor_comparison import CompetitorComparison

    try:
        comparison = CompetitorComparison.objects.get(id=comparison_id)
    except CompetitorComparison.DoesNotExist:
        logger.error(f"[COMPETITOR] Comparison {comparison_id} not found")
        return {'error': 'comparison not found'}

    comparison.status = 'in_progress'
    comparison.save(update_fields=['status', 'updated_at'])

    try:
        return _run_comparison_generation(
            comparison,
            source_document_id=source_document_id,
            competitor_name=competitor_name,
            focus_areas=focus_areas,
        )
    except SoftTimeLimitExceeded:
        comparison.status = 'failed'
        comparison.error_message = 'Task exceeded time limit (300s)'
        comparison.save(update_fields=['status', 'error_message', 'updated_at'])
        raise
    except Exception as e:
        logger.error(f"[COMPETITOR] Failed for '{competitor_name}': {e}\n{traceback.format_exc()}")
        comparison.status = 'failed'
        comparison.error_message = str(e)[:2000]
        comparison.save(update_fields=['status', 'error_message', 'updated_at'])
        return {'error': str(e)}


# =============================================================================
# WORKFLOW RUN: SOURCE PACK COMPARISON
# =============================================================================

@shared_task(bind=True, soft_time_limit=900, time_limit=1080, ignore_result=True)
def run_source_pack_workflow(self, run_id):
    """
    Multi-step workflow: collect sources → ingest → embed → compare → export.

    Stages:
        collecting (5-15%)  — WebSearch + SpiderData keyword search
        ingesting  (20-40%) — process_url per new URL
        embedding  (45-60%) — RAG embed per document
        generating (65-85%) — _run_comparison_generation()
        exporting  (90-95%) — export markdown as Deliverable
        complete   (100%)   — final output_json
    """
    import traceback
    import hashlib
    from django.utils import timezone as tz
    from core.models_workflow_run import WorkflowRun

    try:
        run = WorkflowRun.objects.get(id=run_id)
    except WorkflowRun.DoesNotExist:
        logger.error(f"[WORKFLOW] Run {run_id} not found")
        return

    run.mark_started(celery_task_id=self.request.id)
    run.save(update_fields=['status', 'stage', 'started_at', 'celery_task_id', 'events_json', 'updated_at'])

    input_data = run.input_json or {}
    competitor_name = input_data.get('competitor_name', '')
    queries = input_data.get('queries', [])
    target_count = input_data.get('target_count', 8)
    comparison_id = input_data.get('comparison_id')

    if not queries:
        queries = [
            f"{competitor_name} platform features review",
            f"{competitor_name} architecture technology stack",
            f"{competitor_name} pricing plans comparison",
            f"{competitor_name} security integrations API",
        ]

    output = {}

    try:
        # ── Stage 1: COLLECTING ──────────────────────────────────────
        run.advance_stage('collecting', 5, f'Searching for {competitor_name} sources')
        run.save(update_fields=['status', 'stage', 'percent', 'stage_detail', 'events_json', 'updated_at'])

        collected_urls = {}  # url -> {title, source}
        from core.tools.web_search import WebSearchTool
        web = WebSearchTool()

        for i, q in enumerate(queries):
            try:
                result = web.execute(query=q, max_results=5)
                results_list = result.get('results', []) if isinstance(result, dict) else []
                for r in results_list:
                    url = r.get('url', r.get('link', ''))
                    if url and url not in collected_urls:
                        collected_urls[url] = {
                            'title': r.get('title', url[:80]),
                            'source': 'web_search',
                            'query': q,
                        }
            except Exception as e:
                run.log_event(f'Web search failed for query "{q}": {e}')

            pct = 5 + int((i + 1) / len(queries) * 5)
            run.percent = pct
            run.save(update_fields=['percent', 'events_json', 'updated_at'])

        # Spider data search
        run.advance_stage('collecting', 12, 'Searching spider data')
        run.save(update_fields=['stage_detail', 'percent', 'events_json', 'updated_at'])

        try:
            from core.models_unified_system import SpiderData
            spider_hits = SpiderData.objects.filter(
                embedding_text__icontains=competitor_name
            ).order_by('-created_at')[:20]
            for sd in spider_hits:
                url = sd.source_url
                if url and url not in collected_urls:
                    collected_urls[url] = {
                        'title': sd.spider_name or url[:80],
                        'source': 'spider_data',
                    }
        except Exception as e:
            run.log_event(f'Spider search error: {e}')

        run.advance_stage('collecting', 15, f'Found {len(collected_urls)} unique URLs')
        output['urls_found'] = len(collected_urls)
        run.output_json = output
        run.save(update_fields=['status', 'stage', 'percent', 'stage_detail', 'output_json', 'events_json', 'updated_at'])

        # ── Stage 2: INGESTING ────────────────────────────────────────
        run.advance_stage('ingesting', 20, 'Ingesting documents')
        run.save(update_fields=['status', 'stage', 'percent', 'stage_detail', 'events_json', 'updated_at'])

        from content.processors import DocumentProcessingPipeline
        from content.models import Document, ContentStatus, ContentSource
        from core.services.data_scrubber import scrub
        from django.contrib.auth import get_user_model

        pipeline = DocumentProcessingPipeline()
        doc_ids = []
        seen_hashes = set()
        urls_to_process = list(collected_urls.items())[:target_count]

        for i, (url, meta) in enumerate(urls_to_process):
            try:
                # Content hash dedup — check if we already have this URL
                existing = Document.objects.filter(source_url=url).first()
                if existing:
                    doc_ids.append(str(existing.id))
                    run.log_event(f'Skipped (exists): {url[:80]}')
                else:
                    result = pipeline.process_url(url)
                    if result.success:
                        content_hash = hashlib.sha256(
                            (result.processed_content or '')[:5000].encode()
                        ).hexdigest()[:16]
                        if content_hash not in seen_hashes:
                            seen_hashes.add(content_hash)
                            User = get_user_model()
                            owner = run.user or User.objects.first()
                            doc = Document.objects.create(
                                title=meta.get('title', url[:100]),
                                processed_content=result.processed_content,
                                raw_content=result.raw_content,
                                word_count=result.word_count,
                                language=result.language,
                                key_phrases=result.key_phrases or [],
                                entities=result.entities or [],
                                extracted_metadata=result.metadata or {},
                                source_url=url,
                                status=ContentStatus.PROCESSED,
                                source=ContentSource.API,
                                owner=owner,
                            )
                            doc_ids.append(str(doc.id))
                            run.log_event(f'Ingested: {meta.get("title", url)[:60]}')
                        else:
                            run.log_event(f'Skipped (duplicate content): {url[:80]}')
                    else:
                        run.log_event(f'Failed to ingest: {url[:80]}')
            except Exception as e:
                run.log_event(f'Ingest error for {url[:60]}: {e}')

            pct = 20 + int((i + 1) / len(urls_to_process) * 20)
            run.percent = pct
            run.save(update_fields=['percent', 'events_json', 'updated_at'])

        output['document_ids'] = doc_ids
        run.output_json = output
        run.advance_stage('ingesting', 40, f'Ingested {len(doc_ids)} documents')
        run.save(update_fields=['status', 'stage', 'percent', 'stage_detail', 'output_json', 'events_json', 'updated_at'])

        # ── Stage 3: EMBEDDING ────────────────────────────────────────
        run.advance_stage('embedding', 45, 'Generating embeddings')
        run.save(update_fields=['status', 'stage', 'percent', 'stage_detail', 'events_json', 'updated_at'])

        from content.embeddings import rag_system

        embedded_count = 0
        for i, doc_id in enumerate(doc_ids):
            try:
                doc = Document.objects.get(id=doc_id)
                # Skip if already embedded
                if hasattr(rag_system, 'has_embeddings') and rag_system.has_embeddings(doc_id):
                    run.log_event(f'Already embedded: {doc_id[:8]}')
                else:
                    rag_system.process_document_for_rag_sync(doc)
                    embedded_count += 1
                    run.log_event(f'Embedded: {doc_id[:8]}')
            except Exception as e:
                run.log_event(f'Embedding error for {doc_id[:8]}: {e}')

            pct = 45 + int((i + 1) / max(len(doc_ids), 1) * 15)
            run.percent = pct
            run.save(update_fields=['percent', 'events_json', 'updated_at'])

        output['embedded_count'] = embedded_count
        run.output_json = output
        run.advance_stage('embedding', 60, f'Embedded {embedded_count} documents')
        run.save(update_fields=['status', 'stage', 'percent', 'stage_detail', 'output_json', 'events_json', 'updated_at'])

        # ── Stage 4: GENERATING ───────────────────────────────────────
        run.advance_stage('generating', 65, 'Running comparison generation')
        run.save(update_fields=['status', 'stage', 'percent', 'stage_detail', 'events_json', 'updated_at'])

        from core.models_competitor_comparison import CompetitorComparison

        if comparison_id:
            try:
                comparison = CompetitorComparison.objects.get(id=comparison_id)
            except CompetitorComparison.DoesNotExist:
                comparison = CompetitorComparison.objects.create(
                    competitor_name=competitor_name,
                    generated_by='PA',
                    user=run.user,
                )
        else:
            comparison = CompetitorComparison.objects.create(
                competitor_name=competitor_name,
                generated_by='PA',
                user=run.user,
            )

        comparison.status = 'in_progress'
        comparison.save(update_fields=['status', 'updated_at'])

        gen_result = _run_comparison_generation(
            comparison,
            competitor_name=competitor_name,
            focus_areas=input_data.get('focus_areas'),
        )

        output['comparison_id'] = str(comparison.id)
        output['comparison_status'] = gen_result.get('status', comparison.status)
        output['quality_score'] = gen_result.get('quality_score', 0)
        run.output_json = output
        run.advance_stage('generating', 85, f'Comparison generated: quality={gen_result.get("quality_score", 0)}')
        run.save(update_fields=['status', 'stage', 'percent', 'stage_detail', 'output_json', 'events_json', 'updated_at'])

        # ── Stage 5: EXPORTING ────────────────────────────────────────
        run.advance_stage('exporting', 90, 'Creating deliverable')
        run.save(update_fields=['status', 'stage', 'percent', 'stage_detail', 'events_json', 'updated_at'])

        deliverable_id = None
        if comparison.status == 'complete':
            try:
                from core.services.tool_dispatcher import get_tool_dispatcher
                dispatcher = get_tool_dispatcher()
                export_result = dispatcher._handle_competitor_comparison(
                    'competitor_comparison_tool',
                    {'action': 'export_markdown', 'comparison_id': str(comparison.id), 'save': True},
                    run.user_id,
                    f'workflow-{run_id}',
                )
                deliverable_id = export_result.get('deliverable_id')
                if deliverable_id:
                    output['deliverable_id'] = str(deliverable_id)
                    run.log_event(f'Deliverable created: {deliverable_id}')
            except Exception as e:
                run.log_event(f'Export error: {e}')

        run.output_json = output
        run.advance_stage('exporting', 95, 'Export complete')
        run.save(update_fields=['status', 'stage', 'percent', 'stage_detail', 'output_json', 'events_json', 'updated_at'])

        # ── Stage 6: COMPLETE ─────────────────────────────────────────
        run.mark_complete(output)
        run.save()

        logger.info(
            f"[WORKFLOW] Source pack comparison complete: run={run_id} "
            f"docs={len(doc_ids)} comparison={output.get('comparison_id', 'none')}"
        )

    except SoftTimeLimitExceeded:
        output['partial'] = True
        run.mark_failed('Workflow exceeded time limit (900s)', partial_output=output)
        run.save()
        raise
    except Exception as e:
        logger.error(f"[WORKFLOW] Failed run={run_id}: {e}\n{traceback.format_exc()}")
        run.mark_failed(str(e), partial_output=output)
        run.save()
